// ── Same-scope `let` shadowing (design.md § Variables > Shadowing) ──

#[test]
fn test_same_scope_let_shadowing_value() {
    // The shadowing initializer reads the previous binding; the new binding
    // wins for later uses.
    assert_eq!(
        run_no_errors("fn main() { let x = 5; let x = x + 1; println(x); }"),
        "6\n"
    );
}

#[test]
fn test_same_scope_let_shadowing_changes_type() {
    // Canonical type-changing shadow: String rebound to its length (i64).
    assert_eq!(
        run_no_errors("fn main() { let s = \"hello\"; let s = s.len(); println(s); }"),
        "5\n"
    );
}

#[test]
fn test_same_scope_let_mut_shadowing_value() {
    // `let mut` shadowing is permitted regardless of the prior mutability.
    assert_eq!(
        run_no_errors("fn main() { let mut y = 10; let y = y * 2; println(y); }"),
        "20\n"
    );
}

#[test]
fn test_abs_signed_int() {
    assert_eq!(run("fn main() { println((-5i64).abs()); }"), "5\n");
    assert_eq!(run("fn main() { println((7i64).abs()); }"), "7\n");
    assert_eq!(run("fn main() { println((0i64).abs()); }"), "0\n");
}

#[test]
fn test_struct_display_declaration_order() {
    // `#[derive(Display)]` structs render `Name { field: value, … }` in
    // DECLARATION order (the `Value::Struct` HashMap had lost source order and
    // rendered in random hash order before `display_render`). println,
    // .to_string(), and f-string interpolation all agree.
    let src = "#[derive(Display)]
        struct Wrap { p: Point, name: String, ok: bool }
        #[derive(Display)]
        struct Point { x: i64, y: i64 }
        fn main() {
            let w = Wrap { p: Point { x: 1, y: 2 }, name: \"hi\", ok: true };
            println(w);
            println(w.to_string());
            println(f\"w={w}\");
        }";
    let expected = "Wrap { p: Point { x: 1, y: 2 }, name: hi, ok: true }\n".repeat(2)
        + "w=Wrap { p: Point { x: 1, y: 2 }, name: hi, ok: true }\n";
    assert_eq!(run_no_errors(src), expected);
}

#[test]
fn test_enum_display_unit_variants() {
    // All-unit `#[derive(Display)]` enum renders the bare variant name across
    // println, .to_string(), and f-string — matching codegen.
    let src = "#[derive(Display)]
        enum Color { Red, Green, Blue }
        fn main() {
            let a = Color.Green;
            println(a.to_string());
            println(f\"c={a}\");
            println(a);
        }";
    assert_eq!(run_no_errors(src), "Green\nc=Green\nGreen\n");
}

#[test]
fn test_enum_display_payload_variants_to_string() {
    // Explicit `.to_string()` on a `#[derive(Display)]` enum with PAYLOAD
    // variants renders identically to `f"{e}"` / `println(e)`, including a
    // struct-field receiver. Guards the codegen sibling
    // (`test_e2e_payload_enum_to_string`) — the all-unit restriction on
    // `.to_string()` was stale, and this keeps interp == build.
    let src = "#[derive(Display)]
        enum IoErr { NotFound, Other(String) }
        struct Wrap { e: IoErr }
        fn main() {
            let a: IoErr = IoErr.NotFound;
            let b: IoErr = IoErr.Other(String.from(\"disk full\"));
            println(a.to_string());
            println(b.to_string());
            let w: Wrap = Wrap { e: IoErr.Other(String.from(\"boom\")) };
            println(w.e.to_string());
        }";
    assert_eq!(
        run_no_errors(src),
        "NotFound\nOther(disk full)\nOther(boom)\n"
    );
}

#[test]
fn test_enum_self_to_string_in_impl_method() {
    // `self.to_string()` inside an impl method (a `ref self` receiver) renders
    // a `#[derive(Display)]` enum — both all-unit and payload variants — the
    // `impl Error { fn message(ref self) -> String { self.to_string() } }`
    // pattern. Guards the codegen sibling (`test_e2e_enum_self_to_string`):
    // codegen recognizes the `SelfValue` receiver in the Display helpers so
    // build == run. (The struct receiver is a separate, still-open case —
    // B-2026-07-12-17 — so this covers enums only.)
    let src = "#[derive(Display)]
        enum IoErr { NotFound, Other(String) }
        trait Error { fn message(ref self) -> String; }
        impl Error for IoErr { fn message(ref self) -> String { self.to_string() } }
        fn report[E: Error](e: ref E) -> String { e.message() }
        fn main() {
            let a: IoErr = IoErr.NotFound;
            let b: IoErr = IoErr.Other(String.from(\"disk full\"));
            println(a.message());
            println(b.message());
            println(report(a));
        }";
    assert_eq!(run_no_errors(src), "NotFound\nOther(disk full)\nNotFound\n");
}

#[test]
fn test_method_on_enum_unit_variant_literal() {
    // B-2026-07-13-4: `Dir.North.code()` — a method on an enum unit-variant
    // LITERAL — parses as a 3-segment path call the interpreter had no
    // evaluation rule for ("path 'Dir.North.code' has no interpreter evaluation
    // rule"). The typechecker now types it and lowering materializes the
    // receiver into a fresh local, so the tree-walk interpreter dispatches it
    // like `let d = Dir.North; d.code()`.
    let src = "enum Dir { North, South, East, West }
        impl Dir {
            fn code(self) -> i64 {
                match self { Dir.North => 0, Dir.South => 1, Dir.East => 2, Dir.West => 3 }
            }
            fn opposite(self) -> i64 { self.code() + 100 }
        }
        fn main() {
            println(Dir.North.code().to_string());
            println(Dir.West.code().to_string());
            let z = Dir.East.code() + 5;
            println(z.to_string());
            println(Dir.South.opposite().to_string());
        }";
    assert_eq!(run_no_errors(src), "0\n3\n7\n101\n");
}

#[test]
fn test_generic_shared_struct_heap_field_aliases() {
    // B-2026-07-13-9 oracle pin. A generic `shared struct Box[T] { v: T }`
    // instantiated at a HEAP type (`Box[String]`) is reference-semantics
    // (RC): `let b = a` aliases the same object, so writing `b.v` is visible
    // through `a.v`. The tree-walk interpreter is the oracle for this shape —
    // it computes the correct "bye" answer — while the native/JIT backend
    // refuses to compile it (the shared heap layout erases the `v: T` field to
    // one word and does not monomorphize per instantiation at v1). This test
    // locks the interpreter's correctness so the backend refusal never
    // masquerades as the language semantics.
    let src = "shared struct Box[T] { mut v: T }
        fn main() {
            let a = Box { v: \"hi\" };
            let b = a;
            b.v = \"bye\";
            println(a.v);
            println(b.v);
        }";
    assert_eq!(run_no_errors(src), "bye\nbye\n");
}

#[test]
fn test_shared_vec_field_index_field_read_store_aliasing() {
    // B-2026-07-13-10 oracle pin. A chained read/store through a Vec that is a
    // FIELD of a shared struct (`root.kids[i].val`) is reference-semantics: the
    // pushed element is the SAME RC object as the original handle, so a write
    // through the Vec-field chain is observable via that handle (`a`/`b`). The
    // codegen backends returned the const-0 placeholder for the read and
    // silently dropped the store until fixed; the interpreter has always been
    // correct and is the oracle this locks.
    let src = "shared struct Node { mut val: i64, mut kids: Vec[Node] }
        fn main() {
            let root = Node { val: 1, kids: Vec.new() };
            let a = Node { val: 10, kids: Vec.new() };
            let b = Node { val: 20, kids: Vec.new() };
            root.kids.push(a);
            root.kids.push(b);
            println(f\"{root.kids[0].val}\");
            root.kids[0].val = root.kids[0].val + 5;
            root.kids[1].val = 99;
            println(f\"{root.kids[0].val}\");
            println(f\"{root.kids[1].val}\");
            println(f\"{a.val}\");
            println(f\"{b.val}\");
        }";
    assert_eq!(run_no_errors(src), "10\n15\n99\n15\n99\n");
}

#[test]
fn test_user_impl_display_dispatches_through_to_string() {
    // A user `impl Display { fn to_string(ref self) -> String }` must win over
    // the built-in renderer across all three Display positions — `.to_string()`,
    // f-string interpolation, and `println(x)` — for both enums (incl. payload
    // variants) and structs. GAP-W4 (operator-trait gate lifted for Display).
    let src = "enum Color { Red, Green, Blue }
        impl Display for Color {
            fn to_string(ref self) -> String {
                match self { Red => \"red\", Green => \"green\", Blue => \"blue\" }
            }
        }
        enum Msg { Info(i64), Quit }
        impl Display for Msg {
            fn to_string(ref self) -> String {
                match self { Info(c) => f\"info#{c}\", Quit => \"quit\" }
            }
        }
        struct Point { x: i64, y: i64 }
        impl Display for Point {
            fn to_string(ref self) -> String { f\"({self.x}, {self.y})\" }
        }
        fn main() {
            let c = Color.Green;
            println(c.to_string());      // green
            println(f\"c={c}\");           // c=green
            println(c);                  // green
            let m = Msg.Info(7);
            let q = Msg.Quit;
            println(f\"{m} {q}\");          // info#7 quit
            let p = Point { x: 3, y: 4 };
            println(f\"p={p}\");            // p=(3, 4)
        }";
    let out = run_no_errors(src);
    assert!(out.contains("green\n"), "to_string user impl: {out}");
    assert!(out.contains("c=green\n"), "f-string user impl: {out}");
    assert!(
        out.contains("info#7 quit\n"),
        "payload-enum + unit-variant user impl: {out}"
    );
    assert!(out.contains("p=(3, 4)\n"), "struct user impl: {out}");
    // No built-in variant names leak through.
    assert!(!out.contains("Green"), "built-in must not leak: {out}");
    assert!(!out.contains("Info"), "built-in must not leak: {out}");
}

#[test]
fn a_conditional_store_into_a_mut_ref_param_runs_one_body_on_both_paths() {
    // B-2026-08-30-28. The interpreter twin of
    // `e2e_conditional_store_that_misses_still_runs_one_body`, and the reason
    // it exists as a separate test: this row's fix had to move BOTH backends,
    // and a codegen-only fix would have left the interpreter losing the body —
    // a run-vs-build divergence rather than a shared gap.
    //
    // `take` stores its by-value parameter into a `mut ref` container on ONE
    // path. Before the fix nobody owned the body on the other: the caller stood
    // down because `fn_moves_param_into_outliving_place` saw a store, and the
    // callee registered nothing for the same reason, so `drop 7` simply never
    // printed on any of the four surfaces.
    //
    // The STORING path is asserted in the same program, because the two paths
    // fail in opposite directions — losing a body and doubling one — and a test
    // that pins only the miss would pass a fix that doubled the hit.
    let src = "struct Res { id: i64 }
        impl Drop for Res { fn drop(mut ref self) { println(f\"drop {self.id}\"); } }
        fn take(sink: mut ref Vec[Res], r: Res) { if r.id > 100 { sink.push(r); } }
        fn main() {
            let mut sink: Vec[Res] = Vec.new();
            take(mut sink, Res { id: 7 });
            println(\"--missed--\");
            let named: Res = Res { id: 9 };
            take(mut sink, named);
            println(\"--missed-named--\");
            take(mut sink, Res { id: 200 });
            println(f\"pushed {sink.len()}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "drop 7\n--missed--\ndrop 9\n--missed-named--\npushed 1\ndrop 200\n",
        "each object runs its body exactly once: the two that were not stored die \
         in the callee, the one that was stored dies at the container's drain"
    );
}

#[test]
fn a_user_impl_drop_on_a_map_key_fires_like_one_on_a_value() {
    // B-2026-08-26-41. `emit_map_val_user_drop_bodies_fn` had no key twin, so
    // an `impl Drop` on a KEY type never ran at map teardown while the same
    // impl on the VALUE type did. design.md § Drop owes it: "the compiler
    // invokes `drop` at the end of each value's live range", and a key stored
    // in a map is a value whose live range ends when the map is destroyed.
    //
    // Four destruction sites in one program, because the walk had to be added
    // at each: binding death, `clear()`, a map held in a struct FIELD, and a
    // map reached as a container element. Order within an entry is KEY then
    // VALUE — an entry's halves drop in the order `Map[K, V]` declares them,
    // the rule a struct's fields already follow. Codegen twin:
    // `test_e2e_user_impl_drop_on_a_map_key_fires`.
    let src = "#[derive(Hash, Eq, PartialEq)]
        struct K { id: i64 }
        struct V { id: i64 }
        impl Drop for K { fn drop(mut ref self) { println(f\"dropK {self.id}\"); } }
        impl Drop for V { fn drop(mut ref self) { println(f\"dropV {self.id}\"); } }
        struct Holder { m: Map[K, V] }
        fn main() {
            let mut a: Map[K, V] = Map.new();
            a.insert(K { id: 1 }, V { id: 1 });
            println(\"--before-clear--\");
            a.clear();
            println(\"--after-clear--\");
            { let mut b: Map[K, V] = Map.new();
              b.insert(K { id: 2 }, V { id: 2 });
              let h = Holder { m: b };
              println(\"--field-in-scope--\"); }
            println(\"--field-gone--\");
        }";
    assert_eq!(
        run_no_errors(src),
        "--before-clear--\ndropK 1\ndropV 1\n--after-clear--\n\
         dropK 2\ndropV 2\n--field-in-scope--\n--field-gone--\n"
    );
}

#[test]
fn container_element_drop_order_is_the_containers_own_iteration_order() {
    // B-2026-08-27-7. The drop walk read STORAGE (`MapData::iter`), which is
    // insertion-ordered, while every other read path goes through the seeded
    // permutation `iter_observable` (B-2026-08-21-6). One run therefore printed
    // `iter 1 3 5 6 4 2` and then `drop 1 2 3 4 5 6` over the SAME map: two
    // walks of one container disagreeing with each other.
    //
    // The stability was the damage, not the disagreement. design.md § Map says
    // element destruction order is unspecified and per-process, and the
    // compiled backends deliver that (bucket order). The interpreter handed out
    // a STABLE insertion order instead, so a program that came to depend on it
    // looked correct under `karac run` and reordered under `karac build` — the
    // dependency only became visible at the backend boundary, which is the
    // worst place to find it.
    //
    // THE ASSERTION IS SELF-RELATIVE ON PURPOSE, and that is what makes it
    // runnable at all: it compares the program's own two walks rather than
    // pinning either to a literal, so it holds on every seed and every run
    // without asserting hash order — the thing CLAUDE.md § `Map`/`Set`
    // iteration order forbids. Eight elements, so a regression survives only on
    // the 1-in-40320 of seeds whose hash order happens to equal insertion order.
    let src = "struct V { id: i64 }
        impl Drop for V { fn drop(mut ref self) { println(f\"drop {self.id}\"); } }
        fn main() {
            let mut a: Map[i64, V] = Map.new();
            let mut i = 1;
            while i <= 8 { a.insert(i, V { id: i }); i = i + 1; }
            for (k, v) in a { println(f\"iter {k}\"); }
        }";
    let out = run_no_errors(src);
    let seq = |tag: &str| -> Vec<String> {
        out.lines()
            .filter_map(|l| l.strip_prefix(tag))
            .map(|s| s.trim().to_string())
            .collect()
    };
    let iterated = seq("iter ");
    let dropped = seq("drop ");
    assert_eq!(iterated.len(), 8, "all eight entries iterated: {out}");
    assert_eq!(
        dropped.len(),
        8,
        "each element's body fires exactly once: {out}"
    );
    assert_eq!(
        dropped, iterated,
        "elements must be destroyed in the container's own iteration order: {out}"
    );
}

#[test]
fn vec_equality_is_content_equality_in_the_interpreter() {
    // B-2026-08-27-10. The interpreter had NO `Array` arm in its binop
    // dispatcher, so `Vec[T] == Vec[T]` fell to the catch-all whose message
    // says "this is a type error the typechecker reports as a hard error".
    // That claim was false: `karac check` printed "All checks passed." on the
    // same file, deliberately -- `type_supports_partial_eq` has recursed into
    // a `Vec`'s element since B-2026-08-18-6, and design.md § Conditional
    // `impl` Blocks specifies `impl[T: Eq] Eq for Vec[T]` outright.
    //
    // So the interpreter was the half that had to move. Asserting the ANSWERS
    // rather than the absence of an error is what makes this a regression test
    // for the compiled backends too: they were silently WRONG here, not
    // erroring, and this is the oracle their E2E twin
    // (`test_e2e_vec_equality_compares_contents_not_bytes`) is checked against.
    let src = "fn cmp_ref(a: ref Vec[i64], b: ref Vec[i64]) -> bool { return a == b; }
        fn main() {
            let mut a: Vec[i64] = Vec.new();
            a.push(1);
            a.push(2);
            let mut c: Vec[i64] = Vec.new();
            c.push(1);
            c.push(9);
            let mut d: Vec[i64] = Vec.new();
            d.push(1);
            println(f\"{a == a}\");
            println(f\"{a == c}\");
            println(f\"{a == d}\");
            println(f\"{a != c}\");
            println(f\"{cmp_ref(a, c)}\");
            let mut p: Vec[String] = Vec.new();
            p.push(\"hello\");
            let mut q: Vec[String] = Vec.new();
            q.push(\"hello\");
            println(f\"{p == q}\");
        }";
    // `a == c` is the leg that answered TRUE on the compiled backends: both
    // vecs have length 2, and the string comparison they fell into memcmp'd
    // two BYTES of the i64 element buffers, which are `01 00` in both.
    assert_eq!(
        run_no_errors(src),
        "true\nfalse\nfalse\ntrue\nfalse\ntrue\n"
    );
}

#[test]
fn tuple_comparison_and_equality_in_the_interpreter() {
    // B-2026-08-27-33 -- the third member of the family above, and the same
    // shape as both: `type_supports_ord` / `type_supports_partial_eq` have
    // recursed through `Type::Tuple` since long before the row, so
    // `karac check` printed "All checks passed." on this file while the
    // interpreter died on the catch-all arm whose message claims the
    // typechecker reports this as a hard error. It does not, and did not.
    //
    // Ordering goes through `value_compare`, which is the TOTAL order
    // `karac_cmp_<T>` implements on the compiled side -- so the two backends
    // agree by construction rather than by convention, and this is the oracle
    // for `test_e2e_tuple_comparison_and_equality`.
    //
    // Equality is `Value`'s own `PartialEq` (IEEE element-wise), the same
    // comparator the `Vec` and `Slice` arms above use. That split is why the
    // float rows differ: `(1, 1.5, 2) == (1, 2.5, 2)` answers, while
    // `(1, 1.5) < (1, 2.5)` deliberately does NOT lower on either backend --
    // `value_compare` orders a bare float by `total_cmp` (NaN last) because
    // every one of its other callers is a sort key, and that is not what `<`
    // means on an `f64`.
    //
    // Arity is varied because the compiled twin has an arity-selective defect
    // the interpreter does not share (a three-scalar tuple collides with the
    // `{ptr, i64, i64}` String header there); keeping the two fixtures
    // row-for-row is what makes them checkable against each other.
    let src = "fn main() {
            let a = (1, 2);
            let b = (1, 3);
            println(f\"{a < b}\");
            println(f\"{b < a}\");
            println(f\"{a <= a}\");
            println(f\"{a >= a}\");
            println(f\"{a > b}\");
            println(f\"{a == b}\");
            println(f\"{a != b}\");
            let sa = (\"b\", 1);
            let sc = (\"c\", 0);
            println(f\"{sa < sc}\");
            let na = (1, (2, 3));
            let nb = (1, (2, 4));
            println(f\"{na < nb}\");
            println(f\"{na == nb}\");
            let t3 = (1, 2, 3);
            let u3 = (1, 2, 4);
            println(f\"{t3 < u3}\");
            println(f\"{t3 == u3}\");
            println(f\"{t3 == t3}\");
            let n3a = ((1, 2, 3), 4);
            let n3b = ((1, 2, 5), 4);
            println(f\"{n3a == n3b}\");
            println(f\"{n3a == n3a}\");
            let f3a = (1, 1.5, 2);
            let f3b = (1, 2.5, 2);
            println(f\"{f3a == f3b}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "true\nfalse\ntrue\ntrue\nfalse\nfalse\ntrue\n\
         true\n\
         true\nfalse\n\
         true\nfalse\ntrue\n\
         false\ntrue\n\
         false\n"
    );
}

#[test]
fn array_ordering_in_the_interpreter() {
    // B-2026-08-27-42 -- the `Array[T, N]` sibling of the tuple test above,
    // and the same shape a level down: `type_supports_ord` recurses through
    // `Type::Array`, so `karac check` printed "All checks passed." while the
    // interpreter died on the catch-all arm whose message claims the
    // typechecker reports this as a hard error. It does not, and did not.
    //
    // Ordering goes through `value_compare`, which has had an Array arm since
    // B-2026-06-30-15 -- so unlike the compiled twin, which needed the
    // comparator WRITTEN, this side needed only the dispatch. Both order by
    // the same rule, which is what makes this the oracle for
    // `test_e2e_array_ordering_and_equality`.
    //
    // The last two rows are the deliberate NON-fix, pinned so a later widening
    // has to be deliberate. A NESTED array declines on both backends, and for
    // a reason specific to this backend: `Value::Array` is how a `Vec` is
    // represented here too, so no value-shape test can tell the two apart, and
    // admitting the element would make a tuple holding a `Vec` orderable here
    // while codegen still refuses it. Declining is what keeps the two gates
    // accepting the same set. A bare-float element declines for the sibling
    // reason the tuple test records: `value_compare` orders a float by
    // `total_cmp` (NaN last), which is a sort key's order, not `<`'s.
    let src = "fn main() {
            let a: Array[i64, 2] = Array[1, 2];
            let b: Array[i64, 2] = Array[1, 3];
            let c: Array[i64, 2] = Array[1, 2];
            println(f\"{a < b}\");
            println(f\"{b < a}\");
            println(f\"{a < c}\");
            println(f\"{a <= c}\");
            println(f\"{a >= c}\");
            println(f\"{b > a}\");
            println(f\"{a == c}\");
            let s: Array[String, 2] = Array[\"aa\", \"bb\"];
            let t: Array[String, 2] = Array[\"aa\", \"bc\"];
            println(f\"{s < t}\");
            println(f\"{t < s}\");
            let p: Array[i64, 3] = Array[2, 0, 0];
            let q: Array[i64, 3] = Array[1, 9, 9];
            println(f\"{p < q}\");
            let ta: Array[(i64, i64), 2] = Array[(1, 2), (3, 4)];
            let tb: Array[(i64, i64), 2] = Array[(1, 2), (3, 5)];
            println(f\"{ta < tb}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "true\nfalse\nfalse\ntrue\ntrue\ntrue\ntrue\n\
         true\nfalse\n\
         false\n\
         true\n"
    );
}

#[test]
fn slice_ordering_in_the_interpreter() {
    // B-2026-08-27-45 -- the last member of the tuple / array / slice family,
    // and the same shape as the other two: `type_supports_ord` carries a
    // `Type::Slice` arm, so `karac check` printed "All checks passed." while
    // the interpreter died on the catch-all whose message claims the
    // typechecker reports this as a hard error. It does not, and did not.
    //
    // `value_compare` has had a `Slice` arm (comparing the viewed ranges) as
    // long as its `Vec` one, so this side needed only the dispatch -- unlike
    // codegen, which needed the `Vec` comparator's header made a parameter.
    // Both order by the same rule, which is what makes this the oracle for
    // `test_e2e_slice_ordering`.
    //
    // The prefix row (`p < a`) pins the length tiebreak after a common
    // prefix compares equal; the `heap` rows pin per-element CONTENT
    // comparison, with element 0 content-equal but separately built so a
    // pointer-word comparison could not pass them by accident.
    //
    // The last two rows are the deliberate NON-fix, pinned so a later widening
    // has to be deliberate and has to move both backends together: a slice of
    // `Vec`s and a slice of bare floats each decline here and on the compiled
    // backend. The float case is the carve-out the tuple row records
    // (`value_compare` orders a float by `total_cmp`, a sort key's order, not
    // `<`'s); the `Vec` case is what the per-element gate exists to decline.
    let src = "fn build(p: String) -> String {
            let mut s = String.new();
            s.push_str(p);
            s.push_str(\"x\");
            return s;
        }
        fn main() {
            let mut v: Vec[i64] = Vec.new();
            v.push(1); v.push(2); v.push(1); v.push(3);
            let a: Slice[i64] = v[0..2];
            let b: Slice[i64] = v[2..4];
            let c: Slice[i64] = v[0..2];
            println(f\"{a < b}\");
            println(f\"{b < a}\");
            println(f\"{a < c}\");
            println(f\"{a <= c}\");
            println(f\"{b > a}\");
            let p: Slice[i64] = v[0..1];
            println(f\"{p < a}\");
            println(f\"{a < p}\");
            let mut w: Vec[String] = Vec.new();
            w.push(build(\"a\")); w.push(\"m\");
            w.push(build(\"a\")); w.push(\"n\");
            let x: Slice[String] = w[0..2];
            let y: Slice[String] = w[2..4];
            println(f\"{x < y}\");
            println(f\"{y < x}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "true\nfalse\nfalse\ntrue\ntrue\n\
         true\nfalse\n\
         true\nfalse\n"
    );
}

#[test]
fn tuple_type_arg_through_a_nested_generic_call_in_the_interpreter() {
    // B-2026-08-27-40 -- the ORACLE for
    // `test_e2e_tuple_type_arg_survives_a_nested_generic_call`, kept
    // row-for-row with it so each is the other's check.
    //
    // The interpreter was never wrong here, and that is the point: it carries
    // a generic binding as a `Value`, not as a NAME, so a type argument with
    // no name costs it nothing. The compiled backend threaded the binding
    // through `type_subst_names` and silently dropped the tuple at the first
    // nested call -- `T` fell to the `i64` default and a 16-byte element was
    // swapped 8 bytes at a time. This fixture is what pins the answer the
    // compiled twin has to match; without it, "both backends agree" could be
    // satisfied by both being wrong.
    let src = r#"
struct Bag[=T] { xs: Vec[T] }

impl[T] Bag[T] {
    fn sw(mut ref self, i: i64, j: i64) { self.xs.swap(i, j); }
    fn mid(mut ref self) { self.sw(0, 1); }
    fn outer(mut ref self) { self.mid(); }
    fn at(ref self, i: i64) -> T { return self.xs[i]; }
}

fn main() {
    let mut p: Bag[(i64, i64)] = Bag { xs: Vec.new() };
    p.xs.push((1, 10));
    p.xs.push((2, 20));
    p.outer();
    let p0 = p.at(0);
    let p1 = p.at(1);
    println(f"{p0.0}:{p0.1} {p1.0}:{p1.1}");

    let mut t: Bag[(i64, i64, i64)] = Bag { xs: Vec.new() };
    t.xs.push((1, 2, 3));
    t.xs.push((4, 5, 6));
    t.outer();
    let t0 = t.at(0);
    let t1 = t.at(1);
    println(f"{t0.0},{t0.1},{t0.2} {t1.0},{t1.1},{t1.2}");

    let mut s: Bag[(String, i64)] = Bag { xs: Vec.new() };
    s.xs.push(("x" + "y", 1));
    s.xs.push(("p" + "q", 2));
    s.outer();
    let s0 = s.at(0);
    let s1 = s.at(1);
    println(f"{s0.0}:{s0.1} {s1.0}:{s1.1}");

    let mut n: Bag[((i64, i64), i64)] = Bag { xs: Vec.new() };
    n.xs.push(((1, 2), 3));
    n.xs.push(((4, 5), 6));
    n.outer();
    let n0 = n.at(0);
    println(f"{n0.0.0},{n0.0.1},{n0.1}");

    let mut c: Bag[i64] = Bag { xs: Vec.new() };
    c.xs.push(1);
    c.xs.push(2);
    c.outer();
    println(f"{c.at(0)} {c.at(1)}");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "2:20 1:10\n4,5,6 1,2,3\npq:2 xy:1\n4,5,6\n2 1\n"
    );
}

#[test]
fn slice_equality_is_content_equality_in_the_interpreter() {
    // B-2026-08-27-24 -- the `Vec` sibling's bug one type over, and unfixed by
    // that work. The interpreter had no `Value::Slice` arm in its binop
    // dispatcher, so `Slice[T] == Slice[T]` fell to the same catch-all, whose
    // message says "this is a type error the typechecker reports as a hard
    // error". False again: `type_supports_partial_eq` has a `Type::Slice` arm
    // right beside the `Vec` one, so `karac check` printed "All checks passed."
    // on the same file.
    //
    // `Value`'s `PartialEq` already compared slices by content, which is why a
    // slice-typed struct field worked and only the bare operator did not.
    //
    // The SAME-BUFFER rows (`c[0..2]` vs `c[1..3]`) carry a second point: two
    // slices of one `Vec` share an `Arc<RwLock<..>>`, and comparing them used
    // to take two read locks on it. `RwLock::read` is not documented to be
    // reentrant, so that pair now takes one lock -- an ordinary comparison
    // must not depend on a recursive read succeeding.
    let src = "fn cmp_slices(a: Slice[i64], b: Slice[i64]) -> bool { return a == b; }
        fn main() {
            let mut a: Vec[i64] = Vec.new();
            a.push(1);
            a.push(2);
            a.push(3);
            let mut c: Vec[i64] = Vec.new();
            c.push(1);
            c.push(2);
            c.push(9);
            let s1: Slice[i64] = a[0..2];
            let s2: Slice[i64] = c[0..2];
            let s3: Slice[i64] = c[1..3];
            let s4: Slice[i64] = a[0..3];
            println(f\"{s1 == s2}\");
            println(f\"{s1 == s3}\");
            println(f\"{s1 != s3}\");
            println(f\"{s1 == s4}\");
            println(f\"{cmp_slices(a[0..2], c[0..2])}\");
            let mut p: Vec[String] = Vec.new();
            p.push(\"hello\");
            let mut q: Vec[String] = Vec.new();
            q.push(\"hello\");
            println(f\"{p[0..1] == q[0..1]}\");
        }";
    assert_eq!(run_no_errors(src), "true\nfalse\ntrue\nfalse\ntrue\ntrue\n");
}

#[test]
fn array_equality_is_content_equality_in_the_interpreter() {
    // B-2026-08-27-25's oracle. The interpreter was ALREADY right here --
    // `Array[T, N]` is a `Value::Array` and took the `Vec` arm -- and that is
    // exactly why this test exists: the row is a run-vs-build split where
    // `karac run` works and `karac build` refuses, so the interpreter's answers
    // are the reference its E2E twin
    // (`test_e2e_array_equality_compares_contents`) is checked against. Pinning
    // them keeps the two halves from drifting apart in the other direction.
    let src = "#[derive(PartialEq)]
        struct WrapS { a: Array[String, 2] }
        fn main() {
            let x: Array[i64, 2] = Array[1, 2];
            let y: Array[i64, 2] = Array[1, 9];
            println(f\"{x == y}\");
            println(f\"{x != y}\");
            let p: Array[String, 2] = Array[\"ab\", \"cd\"];
            let q: Array[String, 2] = Array[\"ab\", \"cd\"];
            let r: Array[String, 2] = Array[\"ab\", \"zz\"];
            println(f\"{p == q}\");
            println(f\"{p == r}\");
            println(f\"{WrapS { a: Array[\"ab\", \"cd\"] } == WrapS { a: Array[\"ab\", \"cd\"] }}\");
            let n3: Array[Array[i64, 3], 2] = Array[Array[1, 2, 3], Array[4, 5, 6]];
            let m3: Array[Array[i64, 3], 2] = Array[Array[1, 2, 3], Array[4, 5, 7]];
            println(f\"{n3 == m3}\");
            let mut km: Map[Array[String, 2], i64] = Map.new();
            km.insert(Array[\"ab\", \"cd\"], 1);
            km.insert(Array[\"ab\", \"cd\"], 2);
            km.insert(Array[\"ab\", \"zz\"], 3);
            println(f\"{km.len()}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "false\ntrue\ntrue\nfalse\ntrue\nfalse\n2\n"
    );
}

#[test]
fn a_sorted_container_destroys_its_elements_in_key_order() {
    // B-2026-08-27-7's other half — the escape hatch, pinned. design.md § Map
    // sends code that needs a defined order to `SortedMap`/`SortedSet`, and
    // that advice has to hold for DESTRUCTION as well as iteration or it is
    // useless to anyone with an RAII element type.
    //
    // Unlike the sibling test above this one CAN assert literals: key order is
    // seed-independent, so it is identical on every run and on every backend
    // (measured against `karac build` and the JIT at seeds 1/3/7). Values are
    // inserted at `9 - i` so key order and insertion order DISAGREE — inserting
    // them in ascending order would let a walk that ignored the ordering pass.
    let src = "struct V { id: i64 }
        impl Drop for V { fn drop(mut ref self) { println(f\"drop {self.id}\"); } }
        fn main() {
            let mut a: SortedMap[i64, V] = SortedMap.new();
            let mut i = 1;
            while i <= 8 { a.insert(9 - i, V { id: i }); i = i + 1; }
            println(\"--\");
        }";
    // The `--` lands LAST, not first: the map's last use is the final insert,
    // so NLL ends its live range there and the whole walk fires before the
    // println — design.md's "drop at the end of each value's live range".
    assert_eq!(
        run_no_errors(src),
        "drop 8\ndrop 7\ndrop 6\ndrop 5\ndrop 4\ndrop 3\ndrop 2\ndrop 1\n--\n"
    );
}

#[test]
fn removing_an_entry_runs_the_key_or_element_drop_body() {
    // B-2026-08-27-2 — the site B-2026-08-26-41 deliberately left out.
    // `remove` destroys an entry's KEY in place while its VALUE moves out into
    // the returned `Some(old)`, so the value's body already ran at the caller
    // and only the key's was missing. All four containers are covered because
    // all four were affected: a Set's ELEMENT is the key half, so `Set.remove`
    // ran no body at all.
    //
    // Key before value falls out of the semantics rather than being imposed:
    // the key dies at the call, the value dies wherever the returned `Option`
    // does. Codegen twin: `test_e2e_remove_runs_the_key_drop_body`.
    let src = "#[derive(Hash, Eq, PartialEq, Ord)]
        struct K { n: i64 }
        struct V { n: i64 }
        impl Drop for K { fn drop(mut ref self) { println(f\"dropK {self.n}\"); } }
        impl Drop for V { fn drop(mut ref self) { println(f\"dropV {self.n}\"); } }
        fn main() {
            let mut m: Map[K, V] = Map.new();
            m.insert(K { n: 1 }, V { n: 1 });
            m.remove(K { n: 1 });
            println(f\"map len={m.len()}\");
            let mut sm: SortedMap[K, V] = SortedMap.new();
            sm.insert(K { n: 2 }, V { n: 2 });
            sm.remove(K { n: 2 });
            println(f\"smap len={sm.len()}\");
            let mut st: Set[K] = Set.new();
            st.insert(K { n: 3 });
            st.remove(K { n: 3 });
            println(f\"set len={st.len()}\");
            let mut ss: SortedSet[K] = SortedSet.new();
            ss.insert(K { n: 4 });
            ss.remove(K { n: 4 });
            println(f\"sset len={ss.len()}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "dropK 1\ndropV 1\nmap len=0\n\
         dropK 2\ndropV 2\nsmap len=0\n\
         dropK 3\nset len=0\n\
         dropK 4\nsset len=0\n"
    );
}

#[test]
fn a_user_type_shadowing_a_prelude_name_keeps_its_own_comparison() {
    // B-2026-08-27-11. The total-order float wrapper machinery was keyed on
    // the bare NAME, so a user `struct F64 { .. }` inherited the wrapper's
    // comparison — which reads ONE float field and stops. Two values whose
    // second field differed compared EQUAL on the compiled backends: a
    // FALSE-POSITIVE equality, worse than a false negative because a dedup, a
    // cache hit, or a guard clause then takes the wrong branch instead of
    // merely doing redundant work.
    //
    // design.md § Module System is what makes this the user's type to define:
    // "Users can shadow prelude names in their own code — the language does
    // not reserve them." The existing shadowing test covers LAYOUT, which was
    // already correct; comparison was the half that was captured.
    //
    // Both struct kinds, because the shadow was recorded for PLAIN structs
    // only — a `shared struct F64` was never marked at all, so every consumer
    // of `user_shadowed_prelude_types` went on treating it as the stdlib type.
    // Codegen twin: `test_e2e_shadowed_prelude_name_keeps_its_own_comparison`.
    let src = "#[derive(PartialEq)]
        struct F64 { x: i64, tag: i64 }
        #[derive(PartialEq)]
        shared struct F32 { x: i64, tag: i64 }
        #[derive(Eq, PartialEq)]
        struct F16 { x: i64, tag: i64 }
        fn main() {
            let a = F64 { x: 1, tag: 1 };
            let b = F64 { x: 1, tag: 2 };
            let c = F64 { x: 1, tag: 1 };
            println(f\"plain-ne={a == b}\");
            println(f\"plain-eq={a == c}\");

            let d = F32 { x: 1, tag: 1 };
            let e = F32 { x: 1, tag: 2 };
            println(f\"shared-ne={d == e}\");

            let g = F16 { x: 1, tag: 1 };
            let h = F16 { x: 1, tag: 2 };
            println(f\"derived-ne={g == h}\");

            println(f\"fields={a.x} {a.tag}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "plain-ne=false\nplain-eq=true\nshared-ne=false\n\
         derived-ne=false\nfields=1 1\n"
    );
}

#[test]
fn a_float_field_compares_by_ieee_semantics_not_by_bits() {
    // B-2026-08-27-9. Every TYPE-DIRECTED comparator routed a float field to
    // `emit_eq_fn_for_type`'s byte loop, and bit equality differs from float
    // equality in exactly the two places IEEE-754 defines specially. So `==`
    // was wrong in BOTH directions on the compiled backends: `0.0` and `-0.0`
    // are numerically EQUAL with different bits (answered false), and NaN is
    // UNEQUAL TO ITSELF with identical bits (answered true).
    //
    // THE OPERANDS COME FROM OPAQUE FUNCTIONS ON PURPOSE. With `0.0 / 0.0`
    // written inline, LLVM constant-folds the whole comparison and returns the
    // RIGHT answer without ever running the emitted comparator — which is
    // exactly how the first version of this fix looked correct while the
    // runtime path was untouched. A test that lets the folder answer proves
    // nothing about codegen.
    //
    // Four shapes because four routes reach the comparator family: a shared
    // struct's direct field, a `Vec[f64]` element (via the vec comparator), a
    // PLAIN struct with a Vec field (a Vec field is what pulls a plain struct
    // onto the type-directed path at all), and a nested plain struct inside a
    // shared one. Codegen twin: `test_e2e_float_field_compares_by_ieee`.
    let src = "#[derive(PartialEq)]
        shared struct Sf { x: f64 }
        #[derive(PartialEq)]
        shared struct Sv { v: Vec[f64] }
        #[derive(PartialEq)]
        struct Pv { v: Vec[f64] }
        #[derive(PartialEq)]
        struct Inner { x: f64 }
        #[derive(PartialEq)]
        shared struct Outer { i: Inner }
        fn nan64(z: f64) -> f64 { return z / z; }
        fn negzero(z: f64) -> f64 { return -z; }
        fn one(x: f64) -> Vec[f64] {
            let mut v: Vec[f64] = Vec.new();
            v.push(x);
            return v;
        }
        fn main() {
            let p = 0.0;
            let n = negzero(p);
            let q = nan64(p);

            println(f\"scalar-negzero={p == n}\");
            println(f\"scalar-nan={q == q}\");

            let sa = Sf { x: p };
            let sb = Sf { x: n };
            let sq1 = Sf { x: q };
            let sq2 = Sf { x: q };
            println(f\"shared-negzero={sa == sb}\");
            println(f\"shared-nan={sq1 == sq2}\");

            let va = Sv { v: one(p) };
            let vb = Sv { v: one(n) };
            let vq1 = Sv { v: one(q) };
            let vq2 = Sv { v: one(q) };
            println(f\"sharedvec-negzero={va == vb}\");
            println(f\"sharedvec-nan={vq1 == vq2}\");

            let pa = Pv { v: one(p) };
            let pb = Pv { v: one(n) };
            let pq1 = Pv { v: one(q) };
            let pq2 = Pv { v: one(q) };
            println(f\"plainvec-negzero={pa == pb}\");
            println(f\"plainvec-nan={pq1 == pq2}\");

            let o1 = Outer { i: Inner { x: p } };
            let o2 = Outer { i: Inner { x: n } };
            println(f\"nested-negzero={o1 == o2}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "scalar-negzero=true\nscalar-nan=false\n\
         shared-negzero=true\nshared-nan=false\n\
         sharedvec-negzero=true\nsharedvec-nan=false\n\
         plainvec-negzero=true\nplainvec-nan=false\n\
         nested-negzero=true\n"
    );
}

#[test]
fn eq_on_a_shared_struct_reads_a_niche_option_field_as_a_niche() {
    // B-2026-08-27-5. `==` on a shared struct with a niche-encoded
    // `Option[shared T]` field answered `false` for structurally equal values
    // on the compiled backends. The slot is ONE pointer (null = None); the
    // comparator `emit_eq_fn_for_type_expr` builds for `Option[T]` is for the
    // conventional `{tag, w0, w1, w2}`, FOUR words — so its byte loop ran off
    // the end of the field.
    //
    // The `padded` case is the one that shows the mechanism rather than just
    // the symptom: with three trailing `i64` fields the surplus 24 bytes land
    // on p1/p2/p3, and the compiled answer came out RIGHT purely because those
    // were equal. Same defect, opposite symptom — which is why a test that
    // only checked the last-field shape could be satisfied by a fix that
    // merely shifted the over-read.
    // Codegen twin: `test_e2e_eq_on_a_shared_struct_niche_option_field`.
    let src = "#[derive(Hash, Eq, PartialEq)]
        shared struct Node { v: i64, next: Option[Node] }
        #[derive(Hash, Eq, PartialEq)]
        shared struct Padded { v: i64, next: Option[Padded], p1: i64, p2: i64 }
        fn chain(n: i64) -> Node {
            if n == 0 { return Node { v: 0, next: None }; }
            return Node { v: n, next: Some(chain(n - 1)) };
        }
        fn main() {
            let a = Node { v: 1, next: None };
            let b = Node { v: 1, next: None };
            println(f\"none-none={a == b}\");

            let leaf = Node { v: 2, next: None };
            let c = Node { v: 1, next: Some(leaf) };
            let leaf2 = Node { v: 2, next: None };
            let d = Node { v: 1, next: Some(leaf2) };
            println(f\"some-some={c == d}\");
            println(f\"some-none={c == a}\");

            let x = chain(4);
            let y = chain(4);
            let z = chain(3);
            println(f\"deep={x == y}\");
            println(f\"deep-ne={x == z}\");

            let p = Padded { v: 1, next: None, p1: 7, p2: 8 };
            let q = Padded { v: 1, next: None, p1: 7, p2: 8 };
            let r = Padded { v: 1, next: None, p1: 7, p2: 9 };
            println(f\"padded={p == q}\");
            println(f\"padded-ne={p == r}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "none-none=true\nsome-some=true\nsome-none=false\n\
         deep=true\ndeep-ne=false\n\
         padded=true\npadded-ne=false\n"
    );
}

#[test]
fn nested_index_store_from_a_named_local_is_balanced() {
    // B-2026-08-27-20 — a NESTED index store whose RHS is a NAMED LOCAL
    // double-freed under codegen, while the same store from a TEMPORARY was
    // clean and the interpreter was right in both. One binding was the whole
    // difference.
    //
    // The move-suppression that keeps the source from freeing a buffer the
    // container now owns was gated on the target's object being an `Identifier`
    // (`v[i] = x`) or a `FieldAccess` (`h.xs[j] = t`). For `d[0][1] = x` the
    // object is ITSELF an `Index`, so it matched neither arm and never ran: the
    // store released the displaced element and moved `x`'s buffer into the slot,
    // then `x`'s scope-exit cleanup freed that same buffer.
    //
    // `str` is the failing shape. `deep` is the three-level form, which the same
    // arm has to cover because `vec_index_elem_type_expr` peels one Vec layer per
    // index level — a fix that special-cased two levels would pass `str` and
    // still abort here.
    //
    // `int` and `whole` are the controls, and they are why this survived. `int`
    // stores a scalar into `Vec[Vec[i64]]`: nothing is owned, so no suppression
    // is due and over-suppressing would be invisible. `whole` replaces an entire
    // inner Vec (`outer[0] = nb`), which takes the `Identifier` arm that already
    // worked. Between them they pin that the new arm neither under- nor
    // over-reaches.
    //
    // Every payload is built by `mk(n)` rather than written as a literal: two
    // identical string literals can fold to one global, and a double free of a
    // shared global does not necessarily abort, so distinct allocations are what
    // make the defect reachable at all.
    //
    // Codegen twin: `test_e2e_nested_index_store_from_a_named_local_is_balanced`.
    // The interpreter was already right, so this pins it as the oracle.
    let src = r#"
fn mk(n: i64) -> String { return f"v{n}"; }

fn main() {
    let mut r: Vec[String] = Vec.new();
    r.push(mk(1)); r.push(mk(2));
    let mut d: Vec[Vec[String]] = Vec.new();
    d.push(r);
    let x: String = mk(3);
    d[0][1] = x;
    println(f"str={d[0][1]}");

    let mut i0: Vec[i64] = Vec.new();
    i0.push(1); i0.push(2);
    let mut di: Vec[Vec[i64]] = Vec.new();
    di.push(i0);
    let n: i64 = 9;
    di[0][1] = n;
    println(f"int={di[0][1]}");

    let mut inner: Vec[String] = Vec.new();
    inner.push(mk(4));
    let mut mid: Vec[Vec[String]] = Vec.new();
    mid.push(inner);
    let mut top: Vec[Vec[Vec[String]]] = Vec.new();
    top.push(mid);
    let y: String = mk(5);
    top[0][0][0] = y;
    println(f"deep={top[0][0][0]}");

    let mut vv: Vec[String] = Vec.new();
    vv.push(mk(6));
    let mut outer: Vec[Vec[String]] = Vec.new();
    outer.push(vv);
    let mut nb: Vec[String] = Vec.new();
    nb.push(mk(7));
    outer[0] = nb;
    println(f"whole={outer[0][0]}");
}
"#;
    assert_eq!(run_no_errors(src), "str=v3\nint=9\ndeep=v5\nwhole=v7\n");
}

#[test]
fn enum_eq_is_not_gated_on_a_drop_classification() {
    // B-2026-08-27-19 — `==` on an enum was gated on a DROP classification, so
    // an enum the drop path deliberately declines to own compared its payload
    // WORDS.
    //
    // `enum_has_heap_payload` folds over `field_drop_kinds`, and
    // `enum_drop_kind_for_type_expr` refuses to classify a payload struct
    // `NestedStruct` unless it is word-ALIGNED — because the drop path and the
    // deep-copy-on-entry must stay symmetric, and classifying one the entry-copy
    // cannot duplicate turns a status-quo leak into a DOUBLE FREE. That `None` is
    // correct for ownership and wrong as an answer to "can these bytes be
    // compared as words". `subword` is the shape: `{ a: i32, b: i32, s: String }`
    // spends one word per field where LLVM packs the two `i32`s into eight bytes,
    // so it is not word-aligned, and `==` compared the `String`'s heap POINTER.
    //
    // `zeros` and `nan` are the SECOND symptom of the same gate, and the reason
    // the new predicate is not simply "owns heap". A float payload has no heap at
    // all, so no drop classification would ever have routed it — but bit equality
    // is not IEEE equality in exactly the two places the standard defines
    // specially: `0.0` and `-0.0` are equal with different bits, NaN is unequal
    // to itself with identical bits. Both answered backwards. The operands come
    // from opaque functions so LLVM cannot constant-fold the comparison and
    // answer correctly without running the emitted code.
    //
    // `scalarstruct` and `ints` are the controls: an all-scalar payload, struct
    // or not, is wholly inline and keeps the cheaper word compare. `AllScalar`
    // is deliberately three `i32`s — also not word-aligned, so it proves the
    // predicate keys on what the bytes MEAN rather than on alignment.
    //
    // The `-tag` lines guard the same dereference hazard B-2026-08-27-16 closed:
    // the payload walk must not run when the tags differ, since a unit variant's
    // uninitialised words become a wild pointer once a field is read through.
    //
    // Codegen twin: `test_e2e_enum_eq_is_not_gated_on_a_drop_classification`.
    // The interpreter was already right, so this pins it as the oracle.
    let src = r#"
#[derive(Hash, Eq, PartialEq)]
struct TwoNarrow { a: i32, b: i32, s: String }
#[derive(Hash, Eq, PartialEq)]
struct AllScalar { a: i32, b: i32, c: i32 }
#[derive(Hash, Eq, PartialEq)]
enum Holder { W(TwoNarrow), S(AllScalar), N }
#[derive(PartialEq)]
enum Num { F(f64), I(i64), N }

fn mk(n: i64) -> String { return f"v{n}"; }
fn nan64(z: f64) -> f64 { return z / z; }
fn negzero(z: f64) -> f64 { return -z; }

fn main() {
    let x: Holder = Holder.W(TwoNarrow { a: 1, b: 2, s: mk(1) });
    let y: Holder = Holder.W(TwoNarrow { a: 1, b: 2, s: mk(1) });
    println(f"subword={x == y}");
    println(f"subword-ne-s={x == Holder.W(TwoNarrow { a: 1, b: 2, s: mk(2) })}");
    println(f"subword-ne-a={x == Holder.W(TwoNarrow { a: 9, b: 2, s: mk(1) })}");
    println(f"subword-ne-b={x == Holder.W(TwoNarrow { a: 1, b: 9, s: mk(1) })}");
    println(f"subword-tag={x == Holder.N}");

    let p: Holder = Holder.S(AllScalar { a: 1, b: 2, c: 3 });
    println(f"scalarstruct={p == Holder.S(AllScalar { a: 1, b: 2, c: 3 })}");
    println(f"scalarstruct-ne={p == Holder.S(AllScalar { a: 1, b: 2, c: 4 })}");

    let z = 0.0;
    let neg = negzero(z);
    let nan = nan64(z);
    println(f"zeros={Num.F(0.0) == Num.F(neg)}");
    println(f"nan={Num.F(nan) == Num.F(nan)}");
    println(f"floats={Num.F(1.5) == Num.F(1.5)}");
    println(f"floats-ne={Num.F(1.5) == Num.F(2.5)}");
    println(f"ints={Num.I(7) == Num.I(7)}");
    println(f"ints-ne={Num.I(7) == Num.I(8)}");
    println(f"num-tag={Num.F(1.5) == Num.N}");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "subword=true\nsubword-ne-s=false\nsubword-ne-a=false\n\
         subword-ne-b=false\nsubword-tag=false\n\
         scalarstruct=true\nscalarstruct-ne=false\nzeros=true\n\
         nan=false\nfloats=true\nfloats-ne=false\nints=true\n\
         ints-ne=false\nnum-tag=false\n"
    );
}

#[test]
fn assert_eq_compares_an_enum_by_content() {
    // B-2026-08-27-17 — `assert_eq` / `assert_ne` compared an ENUM by its
    // payload WORDS, so an assertion over two structurally-equal enums PASSED on
    // the interpreter and FAILED compiled. A test asserting enum equality got the
    // wrong verdict, which is worse than a wrong value: it makes a correct
    // program look broken, and for `assert_ne` a broken one look correct.
    //
    // `test_assert.rs` compiled its two operands and called `compile_binop`
    // directly. That dispatches an aggregate by shape and sent the enum to the
    // word-wise `compile_struct_eq` — a heap-pointer compare for any payload
    // owning heap. The `==` OPERATOR site had a structural path all along
    // (`compile_enum_eq`), selected by running `enum_name_of_expr` over the
    // operand EXPRESSIONS; the assertion helper simply never consulted it.
    //
    // The fix lifts that decision into one helper both sites call, so "how a
    // compiled `==` on an enum is decided" has a single definition. Unlike
    // `Vec.contains` (B-2026-08-27-13), this site HAS the operand expressions, so
    // it can reach the operator's own path rather than needing the pointer
    // comparator.
    //
    // EVERY PAYLOAD IS BUILT BY A FUNCTION CALL, never a literal: two identical
    // string literals can fold to one global, and a pointer compare would then
    // answer `true` and hide the defect. The struct, string and int lines are
    // controls that were already correct — `compile_struct_eq` recurses per
    // FIELD, and only an enum's fields are raw payload words.
    //
    // Codegen twin: `test_e2e_assert_eq_compares_an_enum_by_content`.
    // The interpreter was already right, so this pins it as the oracle.
    let src = r#"
#[derive(Hash, Eq, PartialEq)]
enum E { A(String), Pair(i64, String), B }
#[derive(Hash, Eq, PartialEq)]
struct S { a: i64, s: String }

fn mk(n: i64) -> String { return f"v{n}"; }

fn main() {
    assert_eq(E.A(mk(1)), E.A(mk(1)));
    println(f"eq-payload ok");
    assert_ne(E.A(mk(1)), E.A(mk(2)));
    println(f"ne-payload ok");
    assert_eq(E.Pair(7, mk(3)), E.Pair(7, mk(3)));
    println(f"eq-tuple ok");
    assert_ne(E.Pair(7, mk(3)), E.Pair(7, mk(4)));
    println(f"ne-tuple ok");
    assert_eq(E.B, E.B);
    println(f"eq-unit ok");
    assert_ne(E.A(mk(1)), E.B);
    println(f"ne-tag ok");

    let a: Option[String] = Some(mk(5));
    let b: Option[String] = Some(mk(5));
    let c: Option[String] = Some(mk(6));
    assert_eq(a, b);
    println(f"eq-generic ok");
    assert_ne(a, c);
    println(f"ne-generic ok");

    assert_eq(S { a: 1, s: mk(7) }, S { a: 1, s: mk(7) });
    println(f"eq-struct ok");
    assert_eq(mk(8), mk(8));
    println(f"eq-string ok");
    assert_eq(1, 1);
    println(f"eq-int ok");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "eq-payload ok\nne-payload ok\neq-tuple ok\nne-tuple ok\n\
         eq-unit ok\nne-tag ok\neq-generic ok\nne-generic ok\n\
         eq-struct ok\neq-string ok\neq-int ok\n"
    );
}

#[test]
fn enum_eq_handles_a_boxed_or_wide_generic_payload() {
    // B-2026-08-27-16 — `==` on a generic enum whose argument OVERFLOWS its
    // erased payload allotment PANICKED THE COMPILER, and a wide inline payload
    // was compared by its words.
    //
    // `compile_enum_eq` packed offsets sequentially from the RESOLVED field
    // widths. That is right only while every field still fits the allotment the
    // erased layout reserved; when it does not,
    // `coerce_to_payload_words` heap-BOXED the field into one word at
    // construction, so the sequential sum indexed past an area that never held
    // those words and `build_extract_value` returned an unwrapped `Err`.
    // `boxed` and `boxed2` are that shape — `enum Box1[T] { One(T) }` allots `T`
    // ONE word, so a `String` does not fit. Before the fix this fixture did not
    // produce a wrong answer; `karac build` aborted.
    //
    // `wide` is the second defect: a field over three words fell to a
    // best-effort word-wise compare, so `struct Big { a: i64, b: i64, s: String }`
    // (five words) compared the `String`'s heap POINTER and `x == y` answered
    // `false` for equal contents.
    //
    // THE `-tag` LINES ARE THE SOUNDNESS CASE, and they are why the payload walk
    // is now gated on tag equality. The switch dispatches on the LEFT tag, so
    // with mismatched tags it still entered that variant's block and read the
    // RIGHT operand's words as that variant's payload. That was harmless while
    // those reads were integer extracts feeding an `icmp` — the tag conjunction
    // discarded the answer — but the fix DEREFERENCES a field (a boxed payload
    // is `inttoptr` + load, a rebuilt one is loaded through by its comparator),
    // and an uninitialised word from a unit variant is a wild pointer.
    // `Box1.One(s) == Box1.Nil` segfaulted under the JIT. One line per read
    // mode, since each dereferences differently.
    //
    // `opt-scalar` is the control: a payload that fits its allotment and is
    // wholly inline was correct before and must stay so.
    //
    // Codegen twin: `test_e2e_enum_eq_handles_a_boxed_or_wide_generic_payload`. The interpreter was already right,
    // so this pins it as the oracle.
    let src = r#"
#[derive(Hash, Eq, PartialEq)]
enum Box1[T] { One(T), Nil }
#[derive(Hash, Eq, PartialEq)]
enum Pair2[T] { P(T, i64), Nil }
#[derive(Hash, Eq, PartialEq)]
struct Big { a: i64, b: i64, s: String }
#[derive(Hash, Eq, PartialEq)]
enum H { W(Big), N }

fn mk(n: i64) -> String { return f"v{n}"; }

fn main() {
    let a: Box1[String] = Box1.One(mk(1));
    let b: Box1[String] = Box1.One(mk(1));
    let c: Box1[String] = Box1.One(mk(2));
    println(f"boxed={a == b}");
    println(f"boxed-ne={a == c}");
    println(f"boxed-tag={a == Box1.Nil}");

    let d: Pair2[String] = Pair2.P(mk(3), 7);
    let e: Pair2[String] = Pair2.P(mk(3), 7);
    let g: Pair2[String] = Pair2.P(mk(4), 7);
    let h: Pair2[String] = Pair2.P(mk(3), 8);
    println(f"boxed2={d == e}");
    println(f"boxed2-ne-s={d == g}");
    println(f"boxed2-ne-n={d == h}");
    println(f"boxed2-tag={d == Pair2.Nil}");

    let i: H = H.W(Big { a: 1, b: 2, s: mk(5) });
    let j: H = H.W(Big { a: 1, b: 2, s: mk(5) });
    let k: H = H.W(Big { a: 1, b: 2, s: mk(6) });
    let l: H = H.W(Big { a: 1, b: 9, s: mk(5) });
    println(f"wide={i == j}");
    println(f"wide-ne-s={i == k}");
    println(f"wide-ne-b={i == l}");
    println(f"wide-tag={i == H.N}");

    let m: Option[String] = Some(mk(7));
    let n: Option[String] = Some(mk(7));
    println(f"opt={m == n}");
    let q: Option[String] = None;
    println(f"opt-tag={m == q}");
    let o: Option[i64] = Some(5);
    let p: Option[i64] = Some(5);
    println(f"opt-scalar={o == p}");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "boxed=true\nboxed-ne=false\nboxed-tag=false\n\
         boxed2=true\nboxed2-ne-s=false\nboxed2-ne-n=false\n\
         boxed2-tag=false\nwide=true\nwide-ne-s=false\n\
         wide-ne-b=false\nwide-tag=false\nopt=true\n\
         opt-tag=false\nopt-scalar=true\n"
    );
}

#[test]
fn vec_contains_matches_an_enum_element_by_content() {
    // B-2026-08-27-13 — `Vec.contains` compared an ENUM element by its raw
    // payload words, reaching neither of the compiler's two structural enum
    // comparators, so it answered `false` for an element that IS in the vector.
    //
    // WHY NEITHER WAS REACHABLE, which is the whole shape of the bug: the site
    // loaded `data[i]` and the needle as VALUES and called `compile_binop`.
    // `compile_enum_eq` is selected at the `==` OPERATOR site by running
    // `enum_name_of_expr` over the operand EXPRESSIONS, which a loaded value does
    // not carry; `emit_eq_fn_for_type_expr` — the one `Map`/`Set` use — takes
    // pointers, not values. So the aggregate fell to `compile_struct_eq`, whose
    // per-field recursion over an enum's `{tag, w0, w1, …}` compares payload words
    // as i64s.
    //
    // THE STRING AND STRUCT LINES ARE THE CONTROLS, and they are why this looked
    // fine almost everywhere: `compile_struct_eq` recurses per FIELD, so a
    // `String` element and a struct with typed fields both compared by content
    // already. An enum aggregate's fields are raw payload words, and recursing
    // per field over those is a pointer compare wearing a field walk.
    // `enum-unit` and `int` are the second kind of control — wholly inline, so
    // the word compare was already right for them.
    //
    // EVERY PAYLOAD IS BUILT BY A FUNCTION CALL, never a literal. Two identical
    // string literals can be folded to one global, which would let a pointer
    // compare answer `true` and hide the defect; `mk(n)` forces distinct
    // allocations, so a pointer compare must answer `false`.
    //
    // `generic` and `shared` are what the one-comparator routing buys beyond the
    // filed shape: both now go through the same fixed path rather than needing
    // their own arm here.
    //
    // Codegen twin: `test_e2e_vec_contains_matches_an_enum_element_by_content`.
    // The interpreter was already right, so this pins it as the oracle.
    let src = r#"
#[derive(Hash, Eq, PartialEq)]
struct S { a: i64, s: String }
#[derive(Hash, Eq, PartialEq)]
enum E { A(String), Pair(i64, String), B }
#[derive(Hash, Eq, PartialEq)]
shared struct Sh { id: i64, name: String }

fn mk(n: i64) -> String { return f"v{n}"; }

fn main() {
    let ve: Vec[E] = vec![E.A(mk(1)), E.Pair(2, mk(3)), E.B];
    println(f"enum={ve.contains(E.A(mk(1)))}");
    println(f"enum-ne={ve.contains(E.A(mk(2)))}");
    println(f"enum-pair={ve.contains(E.Pair(2, mk(3)))}");
    println(f"enum-pair-ne={ve.contains(E.Pair(2, mk(4)))}");
    println(f"enum-unit={ve.contains(E.B)}");

    let vo: Vec[Option[String]] = vec![Some(mk(5)), None];
    println(f"generic={vo.contains(Some(mk(5)))}");
    println(f"generic-ne={vo.contains(Some(mk(6)))}");
    println(f"generic-none={vo.contains(None)}");

    let vh: Vec[Sh] = vec![Sh { id: 1, name: mk(7) }];
    println(f"shared={vh.contains(Sh { id: 1, name: mk(7) })}");
    println(f"shared-ne={vh.contains(Sh { id: 1, name: mk(8) })}");

    let vs: Vec[String] = vec![mk(9), mk(10)];
    println(f"str={vs.contains(mk(9))}");
    println(f"str-ne={vs.contains(mk(11))}");
    let vt: Vec[S] = vec![S { a: 1, s: mk(12) }];
    println(f"struct={vt.contains(S { a: 1, s: mk(12) })}");
    println(f"struct-ne={vt.contains(S { a: 1, s: mk(13) })}");
    let vi: Vec[i64] = vec![1, 2];
    println(f"int={vi.contains(2)}");
    println(f"int-ne={vi.contains(3)}");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "enum=true\nenum-ne=false\nenum-pair=true\n\
         enum-pair-ne=false\nenum-unit=true\ngeneric=true\n\
         generic-ne=false\ngeneric-none=true\nshared=true\n\
         shared-ne=false\nstr=true\nstr-ne=false\nstruct=true\n\
         struct-ne=false\nint=true\nint-ne=false\n"
    );
}

#[test]
fn a_generic_or_sub_word_enum_key_is_matched_by_content() {
    // B-2026-08-27-12 — the two payload shapes B-2026-08-27-6's structural enum
    // key walk DECLINED, so they kept the byte compare it replaced and stayed
    // wrong: a GENERIC enum key, and a payload struct whose word image is not its
    // LLVM layout.
    //
    // BOTH ARE ONE CAUSE — reading a payload by pointer-casting into its words
    // only works where the words ARE the value. Three ways they are not, and the
    // three read modes that answer them:
    //
    //   * `subword` — `struct { a: i32, b: i32, s: String }` spends three word
    //     runs where LLVM packs the two `i32`s into eight bytes, so `s` sits at
    //     byte 8 by the word stream and byte 8 by LLVM only by luck; field `b`
    //     does not. Rebuilt from its words through the same helper a match arm
    //     binds a payload with. `subword-ne-b` is the line that catches a walk
    //     reading `b` out of `a`'s padding.
    //   * `opt` / `res` — the payload type is the enum's PARAMETER, resolved by
    //     substituting the instantiation, exactly as `compile_enum_eq` does.
    //   * `boxed` / `boxed2` — `enum Box1[T] { One(T) }` allots `T` ONE word from
    //     its erased layout, so a `String` argument does not fit and construction
    //     heap-BOXES it. The word holds a box pointer, not the value.
    //
    // `inst-a` and `inst-b` are the collision guard. `mangled_type_name` drops
    // generic arguments, so `Option[String]` and `Option[i64]` would share one
    // `karac_eq_Option`; once the comparator resolves payloads per instantiation,
    // whichever was emitted first would answer for both. Two live maps of
    // different instantiations in one program is what makes that observable.
    //
    // The `-ne` lines are not padding: a comparator that answered `true`
    // unconditionally passes every positive assertion above them. `dedup` and
    // `removed` check that hash moved with eq — equal keys that hash differently
    // never meet in the same bucket.
    //
    // Codegen twin: `test_e2e_a_generic_or_sub_word_enum_key_is_matched_by_content`.
    // The interpreter was already right, so this pins it as the oracle.
    let src = r#"
#[derive(Hash, Eq, PartialEq)]
struct TwoNarrow { a: i32, b: i32, s: String }
#[derive(Hash, Eq, PartialEq)]
enum Holder { W(TwoNarrow), N }
#[derive(Hash, Eq, PartialEq)]
enum Box1[T] { One(T), Nil }
#[derive(Hash, Eq, PartialEq)]
enum Pair2[T] { P(T, i64), Nil }

fn main() {
    let mut m: Map[Holder, i64] = Map.new();
    m.insert(Holder.W(TwoNarrow { a: 1, b: 2, s: f"zz" }), 7);
    println(f"subword={m.contains_key(Holder.W(TwoNarrow { a: 1, b: 2, s: f"zz" }))}");
    println(f"subword-ne-s={m.contains_key(Holder.W(TwoNarrow { a: 1, b: 2, s: f"zy" }))}");
    println(f"subword-ne-b={m.contains_key(Holder.W(TwoNarrow { a: 1, b: 3, s: f"zz" }))}");

    let mut o: Map[Option[String], i64] = Map.new();
    o.insert(Some(f"kk"), 1);
    o.insert(None, 2);
    println(f"opt={o.contains_key(Some(f"kk"))}");
    println(f"opt-ne={o.contains_key(Some(f"kj"))}");
    println(f"opt-none={o.contains_key(None)}");

    let mut r: Map[Result[String, i64], i64] = Map.new();
    r.insert(Ok(f"rr"), 1);
    r.insert(Err(9), 2);
    println(f"res-ok={r.contains_key(Ok(f"rr"))}");
    println(f"res-ok-ne={r.contains_key(Ok(f"rq"))}");
    println(f"res-err={r.contains_key(Err(9))}");

    let mut b: Map[Box1[String], i64] = Map.new();
    b.insert(Box1.One(f"bb"), 1);
    println(f"boxed={b.contains_key(Box1.One(f"bb"))}");
    println(f"boxed-ne={b.contains_key(Box1.One(f"bc"))}");

    let mut p: Map[Pair2[String], i64] = Map.new();
    p.insert(Pair2.P(f"pp", 3), 1);
    println(f"boxed2={p.contains_key(Pair2.P(f"pp", 3))}");
    println(f"boxed2-ne-s={p.contains_key(Pair2.P(f"pq", 3))}");
    println(f"boxed2-ne-n={p.contains_key(Pair2.P(f"pp", 4))}");

    let mut i: Map[Option[i64], i64] = Map.new();
    i.insert(Some(5), 1);
    println(f"scalar={i.contains_key(Some(5))}");
    println(f"scalar-ne={i.contains_key(Some(6))}");

    let mut two: Map[Option[String], i64] = Map.new();
    two.insert(Some(f"aa"), 1);
    let mut three: Map[Option[i64], i64] = Map.new();
    three.insert(Some(7), 1);
    println(f"inst-a={two.contains_key(Some(f"aa"))}");
    println(f"inst-b={three.contains_key(Some(7))}");

    let mut s: Set[Box1[String]] = Set.new();
    s.insert(Box1.One(f"dup"));
    s.insert(Box1.One(f"dup"));
    println(f"dedup={s.len()}");
    b.remove(Box1.One(f"bb"));
    println(f"removed={b.len()}");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "subword=true\nsubword-ne-s=false\nsubword-ne-b=false\n\
         opt=true\nopt-ne=false\nopt-none=true\nres-ok=true\n\
         res-ok-ne=false\nres-err=true\nboxed=true\n\
         boxed-ne=false\nboxed2=true\nboxed2-ne-s=false\n\
         boxed2-ne-n=false\nscalar=true\nscalar-ne=false\n\
         inst-a=true\ninst-b=true\ndedup=1\nremoved=0\n"
    );
}

#[test]
fn an_enum_key_with_a_heap_payload_is_matched_by_content() {
    // B-2026-08-27-6 — a plain (non-shared) ENUM key with a heap-bearing
    // payload was compared by its payload WORDS instead of recursing, so the
    // compiled backends missed a structurally-equal key the interpreter found.
    // `emit_eq_fn_for_type_expr` had arms for tuples, `Vec` and STRUCTS but
    // none for enums, and the byte-compare fallback it fell to reads a
    // `String` payload's two distinct heap POINTERS.
    //
    // THE SCALAR-PAYLOAD LEG IS THE CONTROL, and the reason this sat unseen:
    // a byte compare IS correct when the whole value is inline, so the common
    // enum key always worked.
    //
    // `Scalar(5)` and `Alt(5)` are the tag leg — identical payload words under
    // different discriminants. They must not collide, which is what a walk
    // that compared payloads without first gating on the tag would do.
    //
    // EQ AND HASH HAD TO MOVE TOGETHER; `dedup` and `removed` are what check
    // it. Equal keys that hash differently never land in the same bucket, so
    // an equality-only fix leaves every lookup missing exactly as before.
    //
    // THE LAST TWO LINES PIN THE TWO PATHS TOGETHER. `==` on an enum VALUE
    // does not use this comparator at all — the operator site routes a
    // heap-payload enum to `compile_enum_eq`, which has walked tags and
    // rebuilt payloads structurally all along. That asymmetry IS this bug:
    // `x == y` and `m.contains_key(y)` disagreed on the same two values,
    // because only one of the two enum comparators in this compiler knew how
    // to look past the payload words. They must keep agreeing.
    //
    // The `-ne` lines are not padding: a comparator that answered `true`
    // unconditionally passes every positive assertion above them.
    //
    // `shared` closes the loop with B-2026-08-27-4, whose shared-enum leg was
    // defined as "behaves as its non-shared twin does" and so inherited this
    // defect. Fixing the plain enum without it would have broken that parity
    // in the other direction.
    //
    // Codegen twin: `test_e2e_an_enum_key_with_a_heap_payload_is_matched_by_content`.
    // The interpreter was already right, so this pins it as the oracle.
    let src = r#"
#[derive(Hash, Eq, PartialEq)]
struct Inner { id: i64, tag: String }
#[derive(Hash, Eq, PartialEq)]
enum Shape {
    Unit,
    Scalar(i64),
    Alt(i64),
    Text { s: String },
    Pair(i64, String),
    Items(Vec[i64]),
    Nested(Inner),
    Narrow(u8, i64),
}
#[derive(Hash, Eq, PartialEq)]
shared enum Node { Named { s: String }, Anon }
fn main() {
    let mut m: Map[Shape, i64] = Map.new();
    m.insert(Shape.Unit, 1);
    m.insert(Shape.Scalar(5), 2);
    m.insert(Shape.Alt(5), 3);
    m.insert(Shape.Text { s: f"hello" }, 4);
    m.insert(Shape.Pair(9, f"pp"), 5);
    m.insert(Shape.Items(vec![1, 2, 3]), 6);
    m.insert(Shape.Nested(Inner { id: 7, tag: f"nn" }), 7);
    m.insert(Shape.Narrow(200, 11), 8);
    println(f"len={m.len()}");
    println(f"unit={m.contains_key(Shape.Unit)}");
    println(f"text={m.contains_key(Shape.Text { s: f"hello" })}");
    println(f"text-ne={m.contains_key(Shape.Text { s: f"hellp" })}");
    println(f"pair={m.contains_key(Shape.Pair(9, f"pp"))}");
    println(f"pair-ne={m.contains_key(Shape.Pair(9, f"pq"))}");
    println(f"items={m.contains_key(Shape.Items(vec![1, 2, 3]))}");
    println(f"items-ne={m.contains_key(Shape.Items(vec![1, 2, 4]))}");
    println(f"nested={m.contains_key(Shape.Nested(Inner { id: 7, tag: f"nn" }))}");
    println(f"nested-ne={m.contains_key(Shape.Nested(Inner { id: 7, tag: f"nm" }))}");
    println(f"narrow={m.contains_key(Shape.Narrow(200, 11))}");
    println(f"narrow-ne={m.contains_key(Shape.Narrow(201, 11))}");
    match m.get(Shape.Scalar(5)) { Some(v) => { println(f"tag-a={v}") } None => { println(f"tag-a=miss") } }
    match m.get(Shape.Alt(5)) { Some(v) => { println(f"tag-b={v}") } None => { println(f"tag-b=miss") } }

    let mut s: Set[Shape] = Set.new();
    s.insert(Shape.Text { s: f"dup" });
    s.insert(Shape.Text { s: f"dup" });
    println(f"dedup={s.len()}");
    m.remove(Shape.Text { s: f"hello" });
    println(f"removed={m.len()}");

    let mut n: Map[Node, i64] = Map.new();
    n.insert(Node.Named { s: f"aa" }, 1);
    println(f"shared={n.contains_key(Node.Named { s: f"aa" })}");
    println(f"shared-ne={n.contains_key(Node.Named { s: f"ab" })}");

    let p = Shape.Text { s: f"eq" };
    let q = Shape.Text { s: f"eq" };
    let r = Shape.Text { s: f"ne" };
    println(f"eq={p == q}");
    println(f"eq-ne={p == r}");
}
"#;
    assert_eq!(
        run_no_errors(src),
        "len=8\nunit=true\ntext=true\ntext-ne=false\npair=true\n\
         pair-ne=false\nitems=true\nitems-ne=false\nnested=true\n\
         nested-ne=false\nnarrow=true\nnarrow-ne=false\ntag-a=2\n\
         tag-b=3\ndedup=1\nremoved=7\nshared=true\n\
         shared-ne=false\neq=true\neq-ne=false\n"
    );
}

#[test]
fn a_shared_key_is_matched_structurally_not_by_pointer_identity() {
    // B-2026-08-27-4. The compiled backends matched a `shared` map/set key by
    // POINTER IDENTITY: `contains_key` answered `false` for a structurally
    // equal twin, `remove` silently removed nothing, and a `Set` failed to
    // dedup. design.md § Equality settles which side is right -- "`==` always
    // means structural equality ... The `Eq` trait determines `==` regardless
    // of whether the compiler chose RC or owned representation. There is no
    // reference-identity short-circuit" -- and reference identity has its own
    // name, `ref_eq`. So the interpreter was already correct and this pins it
    // as the oracle. Codegen twin:
    // `test_e2e_shared_key_is_matched_structurally`.
    //
    // Four shapes because four distinct emitter paths reach a shared key: a
    // scalar-field struct, a struct with a `String` field (the child eq fn has
    // to recurse, not compare headers), a struct with a nested shared field,
    // and a shared ENUM (whose payload area is not a field list at all).
    let src = "#[derive(Hash, Eq, PartialEq)]
        shared struct Scalar { id: i64, n: i64 }
        #[derive(Hash, Eq, PartialEq)]
        shared struct Named { id: i64, name: String }
        #[derive(Hash, Eq, PartialEq)]
        shared struct Inner { v: i64 }
        #[derive(Hash, Eq, PartialEq)]
        shared struct Outer { id: i64, inner: Inner }
        #[derive(Hash, Eq, PartialEq)]
        shared enum Tag { A { x: i64 }, B }
        fn main() {
            let mut a: Map[Scalar, i64] = Map.new();
            a.insert(Scalar { id: 1, n: 2 }, 7);
            println(f\"scalar={a.contains_key(Scalar { id: 1, n: 2 })}\");

            let mut b: Map[Named, i64] = Map.new();
            b.insert(Named { id: 1, name: f\"aa\" }, 7);
            println(f\"named={b.contains_key(Named { id: 1, name: f\"aa\" })}\");
            println(f\"named-ne={b.contains_key(Named { id: 1, name: f\"ab\" })}\");

            let mut c: Map[Outer, i64] = Map.new();
            c.insert(Outer { id: 1, inner: Inner { v: 5 } }, 7);
            println(f\"nested={c.contains_key(Outer { id: 1, inner: Inner { v: 5 } })}\");
            println(f\"nested-ne={c.contains_key(Outer { id: 1, inner: Inner { v: 6 } })}\");

            let mut d: Map[Tag, i64] = Map.new();
            d.insert(Tag.A { x: 1 }, 7);
            println(f\"enum={d.contains_key(Tag.A { x: 1 })}\");
            println(f\"enum-ne={d.contains_key(Tag.A { x: 2 })}\");

            let mut s: Set[Scalar] = Set.new();
            s.insert(Scalar { id: 1, n: 2 });
            s.insert(Scalar { id: 1, n: 2 });
            println(f\"dedup={s.len()}\");

            let mut m: Map[Named, i64] = Map.new();
            m.insert(Named { id: 1, name: f\"aa\" }, 7);
            m.remove(Named { id: 1, name: f\"aa\" });
            println(f\"removed={m.len()}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "scalar=true\nnamed=true\nnamed-ne=false\n\
         nested=true\nnested-ne=false\n\
         enum=true\nenum-ne=false\n\
         dedup=1\nremoved=0\n"
    );
}

#[test]
fn removing_a_shared_key_releases_it_through_the_refcount() {
    // B-2026-08-27-3, the `shared` key half. `remove` gave back nothing: the
    // per-key drop fn declines for a shared half by design (teardown and
    // `clear` release it through the rc_dec WALK, and a drop fn there would
    // double-dec), and `remove` runs no walk — so the count the map took at
    // `insert` was never returned and the whole control block leaked.
    //
    // Both directions are asserted because the fix is a REFCOUNT dec, not an
    // unconditional destruction, and only the count knows which one is due:
    // with no other reference the body runs AT the remove; with a live alias
    // it must wait for that alias's own end. Running the body beside the dec
    // rather than inside it satisfies the first and breaks the second — and
    // prints twice in the first, which is what it did when measured.
    // Codegen twin: `test_e2e_remove_releases_a_shared_key_through_the_refcount`.
    let last = "#[derive(Hash, Eq, PartialEq)]
        shared struct K { id: i64 }
        impl Drop for K { fn drop(mut ref self) { println(f\"dropK {self.id}\"); } }
        fn main() {
            let mut m: Map[K, i64] = Map.new();
            let k = K { id: 1 };
            m.insert(k, 1);
            println(\"--before--\");
            m.remove(k);
            println(\"--after--\");
        }";
    assert_eq!(run_no_errors(last), "--before--\ndropK 1\n--after--\n");

    let aliased = "#[derive(Hash, Eq, PartialEq)]
        shared struct K { id: i64 }
        impl Drop for K { fn drop(mut ref self) { println(f\"dropK {self.id}\"); } }
        fn main() {
            let mut m: Map[K, i64] = Map.new();
            let k = K { id: 1 };
            let keep = k;
            m.insert(k, 1);
            println(\"--before--\");
            m.remove(keep);
            println(\"--after-remove--\");
            println(f\"keep still {keep.id}\");
            println(\"--end--\");
        }";
    assert_eq!(
        run_no_errors(aliased),
        "--before--\n--after-remove--\nkeep still 1\ndropK 1\n--end--\n"
    );
}

#[test]
fn clearing_a_set_runs_its_elements_drop_body() {
    // B-2026-08-27-3 (found while fixing the leak). `Map.clear` got the key
    // and value body walks in B-2026-08-26-41; `Set.clear` is a different
    // codegen arm and got neither, so the compiled backends dropped nothing
    // while the interpreter — which runs the same element walk for every
    // container — printed the body. A run-vs-build divergence, and the
    // interpreter is the side that was already right; this pins it as the
    // oracle. Codegen twin: `test_e2e_set_clear_runs_the_element_drop_body`.
    let src = "#[derive(Hash, Eq, PartialEq, Ord)]
        struct E { n: i64 }
        impl Drop for E { fn drop(mut ref self) { println(f\"dropE {self.n}\"); } }
        fn main() {
            let mut s: Set[E] = Set.new();
            s.insert(E { n: 1 });
            println(\"--before--\");
            s.clear();
            println(f\"--after len={s.len()}--\");
        }";
    assert_eq!(run_no_errors(src), "--before--\ndropE 1\n--after len=0--\n");
}

#[test]
fn a_moved_map_key_runs_its_drop_body_exactly_once() {
    // The half of B-2026-08-26-41 that had to move WITH the walk. Before it,
    // a BOUND-LOCAL key moved into a map ran its body at the MOVE SITE — the
    // row's repro used an inline temporary and so never saw this — and the
    // compiled backend ran it over a moved-from slot, printing an empty field
    // where `--interp` printed the value.
    //
    // `disarm_moved_value_arg_user_drops` documented the pairing: keys stayed
    // on the container-only disarm precisely because no walk covered them. So
    // the walk alone would double-fire this, and the disarm alone would stop
    // an RAII key releasing at all. Both assertions below are needed: the
    // COUNT (exactly one) and the CONTENT (the field survives, so the body did
    // not run over a moved-from slot).
    let src = "#[derive(Hash, Eq, PartialEq)]
        struct K { s: String }
        impl Drop for K { fn drop(mut ref self) { println(f\"dropK {self.s}\"); } }
        fn main() {
            let mut m: Map[K, i64] = Map.new();
            let k = K { s: \"kk\" };
            m.insert(k, 1);
            println(\"--after-insert--\");
            println(f\"len={m.len()}\");
        }";
    let out = run_no_errors(src);
    assert_eq!(out.matches("dropK").count(), 1, "exactly one body: {out}");
    assert!(
        out.contains("dropK kk\n"),
        "field must survive the move: {out}"
    );
    assert!(
        out.find("dropK").unwrap() > out.find("len=1").unwrap(),
        "the body belongs at teardown, not at the move site: {out}"
    );
}

#[test]
fn a_match_bound_string_slice_keeps_its_methods() {
    // Oracle twin of `test_e2e_match_bound_string_slice_keeps_method_dispatch`
    // in `tests/codegen.rs` — the two assert the same bytes. The interpreter
    // always ran this; codegen refused every method but `to_string` on a
    // match-bound view, so the pair is what pins the two backends together.
    //
    // The `SplitIter` is the zero-copy tokenizing spelling the language can
    // express today, and the reason the codegen gap mattered: it is the
    // non-allocating alternative to `s.split(",")` (B-2026-08-26-13).
    let src = "fn head(s: ref String) -> Option[StringSlice] { return Some(s.slice(0, 3)); }
        struct SplitIter { rest: StringSlice, done: bool }
        impl SplitIter {
            fn next(mut ref self) -> Option[StringSlice] {
                if self.done { return None; }
                match self.rest.find(\",\") {
                    Some(k) => {
                        let head = self.rest.slice(0, k);
                        self.rest = self.rest.slice(k + 1, self.rest.len());
                        return Some(head);
                    }
                    None => { self.done = true; return Some(self.rest); }
                }
            }
        }
        fn main() {
            let s = \"hello\";
            match head(s) {
                Some(v) => println(f\"len={v.len()}\"),
                None => println(\"none\")
            }
            match head(s) {
                Some(v) => println(f\"sub={v.slice(0, 2).to_string()}\"),
                None => println(\"none\")
            }
            let text = \"aa,bb,cc\";
            let mut it = SplitIter { rest: text.slice(0, text.len()), done: false };
            let mut n = 0;
            let mut c = 0;
            while true {
                match it.next() { None => break, Some(f) => { n = n + f.len(); c = c + 1; } }
            }
            println(f\"{c} fields, {n} bytes\");
        }";
    assert_eq!(run_no_errors(src), "len=3\nsub=he\n3 fields, 6 bytes\n");
}

#[test]
fn user_impl_display_wins_at_every_depth_not_just_the_top_level() {
    // B-2026-08-26-29. A hand-written `impl Display` took effect at depth 0
    // (`f"{e}"` -> `aye 7`) and was IGNORED one level down, where the DERIVED
    // shape rendered instead (`f"{[e]}"` -> `[A { n: 7 }, B]`). That made the
    // one mechanism the language offers for overriding a rendering stop
    // applying inside a container, so a type whose `Display` exists to hide its
    // internals leaked them from inside any `Vec` / `Option` / struct field.
    //
    // Every container contributes only its punctuation; each element renders
    // through its own `Display` (design.md § derive(Display) on enums, "The
    // override applies at every depth").
    let src = "enum Ue { A { n: i64 }, B }
        impl Display for Ue {
            fn to_string(ref self) -> String {
                match self { A { n } => f\"aye {n}\", B => \"bee\" }
            }
        }
        struct Wrap { u: Ue }
        impl Display for Wrap {
            fn to_string(ref self) -> String { f\"<{self.u}>\" }
        }
        struct Holder { u: Ue }
        fn main() {
            let e = Ue.A { n: 7 };
            println(f\"top={e}\");
            let v = [Ue.A { n: 7 }, Ue.B];
            println(f\"vec={v}\");
            println(f\"nest={[[Ue.B]]}\");
            let o = Some(Ue.B);
            println(f\"opt={o}\");
            let r: Result[Ue, i64] = Ok(Ue.B);
            println(f\"res={r}\");
            let t = (Ue.B, 1);
            println(f\"tup={t}\");
            let h = Holder { u: Ue.B };
            println(f\"fld={h.u}\");
            let w = Wrap { u: Ue.A { n: 3 } };
            println(f\"wrap={w}\");
            println(f\"vw={[Wrap { u: Ue.B }]}\");
            let mut m: Map[String, Ue] = Map.new();
            m.insert(\"k\", Ue.B);
            println(f\"map={m}\");
            println(f\"str={v.to_string()}\");
        }";
    let out = run_no_errors(src);
    for want in [
        "top=aye 7\n",
        "vec=[aye 7, bee]\n",
        "nest=[[bee]]\n",
        "opt=Some(bee)\n",
        "res=Ok(bee)\n",
        "tup=(bee, 1)\n",
        "fld=bee\n",
        "wrap=<aye 3>\n",
        "vw=[<bee>]\n",
        "map={k: bee}\n",
        "str=[aye 7, bee]\n",
    ] {
        assert!(out.contains(want), "missing {want:?} in:\n{out}");
    }
    // The derived shape must not leak from ANY position — that is the bug.
    assert!(!out.contains("A {"), "derived shape leaked: {out}");
    assert!(!out.contains("Some(B)"), "derived shape leaked: {out}");
}

#[test]
fn user_impl_display_reaches_set_and_sorted_collection_elements() {
    // B-2026-08-26-29, second half. `Set` / `SortedSet` / `SortedMap` were the
    // three shapes the typed walker never destructured — they fell to a
    // catch-all that formats through `Value`'s RUST `Display`, which cannot
    // reach a user impl. Codegen's Set renderer DOES recurse through the shared
    // dispatcher, so honoring the impl there and not here would have turned a
    // consistent-but-wrong rendering into a run-vs-build divergence.
    //
    // `SortedSet`/`SortedMap` with a user-enum key are refused by codegen today
    // for an unrelated reason, so only the `Set` line has a compiled twin; the
    // other two are asserted here because the rule is the interpreter's to keep
    // either way.
    let src = "#[derive(Hash, Eq, PartialEq, Ord)]
        enum Ue { A { n: i64 }, B }
        impl Display for Ue {
            fn to_string(ref self) -> String {
                match self { A { n } => f\"aye {n}\", B => \"bee\" }
            }
        }
        fn main() {
            let mut s: Set[Ue] = Set.new();
            s.insert(Ue.B);
            println(f\"set={s}\");
            let mut ss: SortedSet[Ue] = SortedSet.new();
            ss.insert(Ue.B);
            println(f\"sset={ss}\");
            let mut sm: SortedMap[Ue, i64] = SortedMap.new();
            sm.insert(Ue.B, 1);
            println(f\"smap={sm}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "set=Set{bee}\nsset=SortedSet{bee}\nsmap=SortedMap{bee: 1}\n"
    );
}

#[test]
fn user_impl_display_on_a_shared_struct_is_honored_like_any_other() {
    // B-2026-08-26-29, third leg — and the only one that was ALREADY a
    // run-vs-build divergence at DEPTH 0 before this row touched anything.
    //
    // `user_display_impl_to_string_key` matched `Struct` and `EnumVariant` and
    // not `SharedStruct`, so the interpreter ignored a `shared struct`'s
    // `impl Display` everywhere — even for a bare `println(a)` and an explicit
    // `a.to_string()`. Codegen resolves a shared struct through
    // `expr_user_struct_name` (shared types are registered in
    // `struct_field_names`), so it honored the impl and printed `sh(1)` where
    // `--interp` printed `Sh { v: 1 }`.
    //
    // A shared ENUM was never affected: it rides as a `Value::EnumVariant`,
    // which the helper already matched. It is asserted here as the control.
    let src = "shared struct Sh { v: i64 }
        impl Display for Sh {
            fn to_string(ref self) -> String { f\"sh({self.v})\" }
        }
        shared enum Se { X { n: i64 }, Y }
        impl Display for Se {
            fn to_string(ref self) -> String { \"se\" }
        }
        fn main() {
            let a = Sh { v: 1 };
            println(f\"top={a}\");
            println(a.to_string());
            let v = [Sh { v: 2 }];
            println(f\"vec={v}\");
            let e = Se.Y;
            println(f\"enum={e}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "top=sh(1)\nsh(1)\nvec=[sh(2)]\nenum=se\n"
    );
}

#[test]
fn debug_keeps_the_field_shape_when_display_is_overridden() {
    // The companion invariant to the test above: `Debug` is a DIFFERENT trait
    // and a user `impl Display` must not reach it. `dbg()` reports the `{:?}`
    // form, which design.md pins as the field-name shape — so the same vector
    // that prints `[aye 7, bee]` through `Display` must still report
    // `[A { n: 7 }, B]` through `Debug`.
    let src = "enum Ue { A { n: i64 }, B }
        impl Display for Ue {
            fn to_string(ref self) -> String {
                match self { A { n } => f\"aye {n}\", B => \"bee\" }
            }
        }
        fn main() {
            let v = [Ue.A { n: 7 }, Ue.B];
            println(f\"disp={v}\");
            dbg(v);
        }";
    let (out, dbg) = run_program_with_dbg(src, DbgOutputMode::Terminal);
    let out = out.join("");
    assert!(out.contains("disp=[aye 7, bee]\n"), "Display: {out}");
    assert_eq!(dbg.len(), 1, "expected one dbg line, got {dbg:?}");
    assert!(
        dbg[0].contains("[A { n: 7 }, B]"),
        "Debug must keep the field shape: {:?}",
        dbg[0]
    );
    assert!(
        !dbg[0].contains("aye 7"),
        "the user Display must not reach Debug: {:?}",
        dbg[0]
    );
}

#[test]
fn a_derived_display_is_unaffected_by_the_depth_dispatch() {
    // Control for the two tests above: the depth dispatch fires ONLY for a
    // hand-written impl. A `#[derive(Display)]` type keeps the derived shape at
    // every depth, so the fix cannot have shifted any existing rendering.
    let src = "#[derive(Display)]
        struct Plain { n: i64 }
        fn main() {
            let p = Plain { n: 5 };
            println(f\"top={p}\");
            println(f\"vec={[Plain { n: 5 }]}\");
            println(f\"opt={Some(Plain { n: 5 })}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "top=Plain { n: 5 }\nvec=[Plain { n: 5 }]\nopt=Some(Plain { n: 5 })\n"
    );
}

#[test]
fn a_compound_option_payload_renders_through_its_own_display() {
    // design.md § Strings names this exact example: `Some(p)` for a `p: Point`
    // with an `impl Display` prints `Some((3, 4))`, NOT the field-name form.
    // Both backends rendered `Some(Point { x: 3, y: 4 })` before B-2026-08-26-29
    // — the `Debug`-in-`Display` bug that paragraph was written against.
    let src = "struct Point { x: i64, y: i64 }
        impl Display for Point {
            fn to_string(ref self) -> String { f\"({self.x}, {self.y})\" }
        }
        fn main() {
            let p = Point { x: 3, y: 4 };
            let o = Some(p);
            println(f\"{o}\");
        }";
    assert_eq!(run_no_errors(src), "Some((3, 4))\n");
}

#[test]
fn test_struct_display_nested_in_container() {
    // A struct nested in a Vec still renders in declaration order (the
    // renderer recurses through containers).
    let src = "#[derive(Display)]
        struct Point { x: i64, y: i64 }
        fn main() {
            let v: Vec[Point] = [Point { x: 9, y: 8 }, Point { x: 7, y: 6 }];
            println(f\"list={v}\");
        }";
    assert_eq!(
        run_no_errors(src),
        "list=[Point { x: 9, y: 8 }, Point { x: 7, y: 6 }]\n"
    );
}

#[test]
fn test_abs_float() {
    assert_eq!(run("fn main() { println((-2.5f64).abs()); }"), "2.5\n");
    assert_eq!(run("fn main() { println((2.5f64).abs()); }"), "2.5\n");
}

#[test]
fn test_sqrt_float() {
    assert_eq!(run("fn main() { println((16.0f64).sqrt()); }"), "4\n");
    assert_eq!(
        run("fn main() { println((2.0f64).sqrt()); }"),
        "1.4142135623730951\n"
    );
}

/// B-2026-08-30-34 — A `u64` AT OR ABOVE 2^63 CONVERTED TO EVERY FLOAT TYPE AS
/// ITS NEGATIVE TWO'S-COMPLEMENT IMAGE, on the interpreter only.
///
/// `Value::Int` is a signed `i128` with no signedness tag — deliberately — so a
/// `u64` past 2^63 rides as its negative twin and each reader that must know
/// consults the recorded type (`span_unsigned_int_width` / `int_width_at`). The
/// float conversions were the readers that never did, so `u64::MAX as f64`
/// answered -1 here while all three compiled surfaces answered
/// 18446744073709552000. The cast-path residual of B-2026-07-04-8, which built
/// that u64 model for printing, comparison and sorting and never mentions casts.
///
/// It was NOT one site. An integer reaches a float slot by ten routes and each
/// converted the carrier independently: the `as` cast, `to_f32`/`to_f64`, a
/// float-annotated `let`, a call argument, a method argument, a function's tail
/// expression, an explicit `return`, a struct-literal field, a field
/// assignment, and a `Vec[f64]` element store. Measured over a 9-value x
/// 10-shape sweep: 45 of 90 rows diverged from the compiled backends before,
/// 0 of 90 after.
///
/// The last two rows are the CONTROL, and they are what makes this test able to
/// fail in both directions: `ints` pins that the integer-target casts and the
/// division still read the carrier as they always have (`mx as i64` is -1,
/// `mx as u32` is 4294967295), so a "fix" that normalized the carrier
/// everywhere — breaking B-2026-07-04-8's model — would fail here rather than
/// pass quietly. `u128` pins the widening this fix also had to correct:
/// `u64 as u128` kept the sign and stored -1, which printing and comparison
/// got wrong too, not just the float read.
///
/// Twin: `tests/codegen.rs::e2e_u64_above_2_63_converts_to_float_as_unsigned`.
#[test]
fn u64_above_2_63_converts_to_every_float_type_as_unsigned() {
    // Literal seed rather than `env.args().len()` — an in-process interpreter
    // test sees the TEST binary's argv; the codegen twin needs an opaque seed
    // to survive -O2 folding and 1 is what that yields under its harness.
    assert_eq!(
        run(
            r#"
fn tailf(v: u64) -> f64 { v }
fn retf(v: u64) -> f64 { return v; }
fn takef(x: f64) -> f64 { x }
struct S { f: f64 }
impl S { fn setm(mut ref self, x: f64) -> f64 { self.f = x; self.f } }
fn main() {
    let n = 1i64;
    let zero: i64 = n - 1;
    let mx: u64 = (18446744073709551615u64 + (zero as u64));
    let hi: u64 = (9223372036854775808u64 + (zero as u64));
    let lo: u64 = (9223372036854775807u64 + (zero as u64));
    println(f"cast {(mx as f64)} {(hi as f64)} {(lo as f64)}");
    println(f"f32  {(mx as f32)} {(hi as f32)}");
    println(f"half {(mx as f16)} {(mx as bf16)}");
    println(f"meth {mx.to_f64()} {mx.to_f32()}");
    let slot: f64 = mx;
    println(f"slot {slot}");
    println(f"call {takef(mx)} {tailf(mx)} {retf(mx)}");
    let mut s: S = S { f: mx };
    println(f"fldi {s.f}");
    s.f = hi;
    println(f"flda {s.f} {s.setm(mx)}");
    let w: u128 = (mx as u128);
    println(f"u128 {w} {(w as f64)}");
    let mut vf: Vec[f64] = [];
    vf.push(mx);
    println(f"push {vf[0]}");
    println(f"ints {mx} {(mx as i64)} {(mx as u32)} {(mx / 3u64)}");
}
"#
        ),
        "cast 18446744073709552000 9223372036854776000 9223372036854776000\nf32  18446744073709552000 9223372036854776000\nhalf inf 18446744073709552000\nmeth 18446744073709552000 18446744073709552000\nslot 18446744073709552000\ncall 18446744073709552000 18446744073709552000 18446744073709552000\nfldi 18446744073709552000\nflda 9223372036854776000 18446744073709552000\nu128 18446744073709551615 18446744073709552000\npush 18446744073709552000\nints 18446744073709551615 -1 4294967295 6148914691236517205\n"
    );
}

/// B-2026-08-30-9 — a `Vector[T, N]` renders its lanes through the TYPE-DIRECTED
/// renderer, so an unsigned lane above `i64::MAX` reads back as unsigned.
///
/// The headline shape is the SELF-CONTRADICTION inside one program: `u[0]` and
/// `u` disagreed about the very same lane. The indexed read reinterprets by the
/// expression's static type and printed 18446744073709551615; the whole vector
/// fell through `render_typed_mode`'s arms to the untyped `Display` in
/// `value.rs`, which sees a bare `Value::Int(-1)` carrier and prints `-1`.
/// Asserting both in ONE program is the point — either line alone looks right.
///
/// The nested cases (`Vec` / tuple of a vector) are worth pinning here because
/// they come from the container arms recursing INTO the new one, so they are
/// what proves the fix was made at the recursion point rather than
/// special-cased at depth 0.
///
/// They HAD no codegen twin when this was written, because the compiled
/// backends could not render a nested vector at all — they aborted with
/// `emit_display_fn_for_type: type_name 'Vector_u64_2' not yet supported`.
/// B-2026-08-30-39 closed that, and the `Vec` and tuple rows are now twinned in
/// `tests/codegen.rs::e2e_nested_vector_display_agrees_with_the_interpreter`.
///
/// `inopt` is the one row that is still interpreter-only, and for a reason
/// unrelated to vectors: an `Option` whose payload makes the option's LLVM
/// value a non-`String` struct has no f-string Display path in codegen at all
/// — `Option[Vec[i64]]` fails identically, while `Option[i64]` is fine. Filed
/// separately; do not read its absence here as a vector gap.
///
/// `i64` lanes are in the table as the control that keeps the fix honest — a
/// signed `-1` must still print `-1`, which is what stops "render lanes
/// unsigned" from being implemented as "render lanes unsigned unconditionally".
///
/// Twin (depth-0 rows only): `tests/codegen.rs::e2e_vector_display_agrees_with_the_interpreter`.
#[test]
fn vector_display_renders_wide_unsigned_lanes_as_unsigned() {
    assert_eq!(
        run(
            r#"
fn main() {
    let u: Vector[u64, 2] = Vector[u64, 2](18446744073709551615u64, 1u64);
    println(f"lane {u[0]}");
    println(f"whole {u}");
    println(f"bare");
    println(u);
    let w: Vector[u128, 2] = Vector[u128, 2](340282366920938463463374607431768211455u128, 1u128);
    println(f"u128 {w[0]} {w}");
    let b: Vector[u64, 2] = Vector[u64, 2](9223372036854775808u64, 1u64);
    println(f"bound {b}");
    let s: Vector[i64, 2] = Vector[i64, 2](-1, 1);
    println(f"signed {s}");
    let n: Vector[u8, 4] = Vector[u8, 4](200u8, 1u8, 2u8, 3u8);
    println(f"narrow {n}");
    let vs: Vec[Vector[u64, 2]] = [u];
    println(f"invec {vs}");
    let t = (u, 7i64);
    println(f"intup {t}");
    let o: Option[Vector[u64, 2]] = Some(u);
    println(f"inopt {o}");
}
"#
        ),
        "lane 18446744073709551615\nwhole Vector(18446744073709551615, 1)\nbare\nVector(18446744073709551615, 1)\nu128 340282366920938463463374607431768211455 Vector(340282366920938463463374607431768211455, 1)\nbound Vector(9223372036854775808, 1)\nsigned Vector(-1, 1)\nnarrow Vector(200, 1, 2, 3)\ninvec [Vector(18446744073709551615, 1)]\nintup (Vector(18446744073709551615, 1), 7)\ninopt Some(Vector(18446744073709551615, 1))\n"
    );
}

/// B-2026-08-30-46 — `dbg()` OF A `Set` / `SortedSet` / `SortedMap` RENDERED A
/// `u64` ELEMENT AT OR ABOVE 2^63 AS ITS NEGATIVE, while `f"{s}"` on the SAME
/// container in the SAME program rendered it unsigned.
///
/// The sibling of B-2026-08-30-9 one arm over: those three arms of
/// `render_typed_mode` were guarded `if !debug`, so under `dbg` they fell past
/// the typed walker to the untyped `debug_fmt` catch-all, which sees a bare
/// signed `Value::Int` carrier and cannot know the element was unsigned.
///
/// The guard's stated reason was that routing them through the typed walker
/// "would also start quoting their leaves". MEASURED: it does not — the
/// catch-all it fell to is `debug_fmt`, which already quotes, so both paths
/// print `Set{"a"}`. That is why the string rows below are here: they pin the
/// property the deferral was protecting, which was never actually at risk.
///
/// `Map` is the CONTROL and the reason this is a defect rather than a
/// convention: its arm never carried the guard, so it printed the unsigned
/// value under `dbg` all along while its three siblings did not. BOTH compiled
/// backends also print unsigned in both modes, so this was an
/// interpreter-only run-vs-build divergence.
///
/// One element per container deliberately: `Set` iteration order is per-process
/// random (design.md § Map), so a multi-element row would assert an order the
/// language does not define.
#[test]
fn dbg_of_a_set_or_sorted_container_renders_wide_unsigned_elements_as_unsigned() {
    let src = "fn main() {
            let big: u64 = 18446744073709551615u64;
            let mut s: Set[u64] = Set.new(); s.insert(big);
            let mut ss: SortedSet[u64] = SortedSet.new(); ss.insert(big);
            let mut sm: SortedMap[u64, u64] = SortedMap.new(); sm.insert(big, big);
            let mut m: Map[u64, u64] = Map.new(); m.insert(big, big);
            dbg(s); dbg(ss); dbg(sm); dbg(m);
            let neg: i64 = -1;
            let mut si: Set[i64] = Set.new(); si.insert(neg);
            dbg(si);
            let mut st: Set[String] = Set.new(); st.insert(f\"a\");
            let mut smt: SortedMap[String, String] = SortedMap.new(); smt.insert(f\"k\", f\"v\");
            dbg(st); dbg(smt);
        }";
    let (_out, dbg) = run_program_with_dbg(src, DbgOutputMode::Terminal);
    let hay = dbg.join("\n");
    for needle in [
        "Set{18446744073709551615}",
        "SortedSet{18446744073709551615}",
        "SortedMap{18446744073709551615: 18446744073709551615}",
        // The `Map` control, correct before this row and after it.
        "{18446744073709551615: 18446744073709551615}",
        // A genuinely signed element still reads as signed: a fix that simply
        // reinterpreted every carrier as unsigned would fail here.
        "Set{-1}",
        // Leaf quoting is UNCHANGED — the property the `!debug` guard was
        // deferring to protect, and which it was not in fact protecting.
        "Set{\"a\"}",
        "SortedMap{\"k\": \"v\"}",
    ] {
        assert!(
            hay.contains(needle),
            "missing {needle:?} in dbg output:\n{hay}"
        );
    }
}

/// B-2026-08-30-26 — the interpreter half of the int <-> `bf16` conversion
/// fixture, and a PARITY PIN rather than a regression test: the interpreter was
/// never wrong here. It performed every one of these while both compiled
/// backends refused to build the program at all, which is what made the bug a
/// run-vs-build divergence instead of a wrong answer.
///
/// It is pinned because the codegen fix routes int->bf16 through f32 while this
/// side goes through f64, so the two agree by a double-rounding argument
/// (p1 >= 2*p2 + 2) rather than by sharing code. If either route is ever
/// changed, this and its codegen twin move apart and both fail.
///
/// Twin: `tests/codegen.rs::e2e_int_bf16_conversions_are_lowered_through_f32`.
#[test]
fn int_bf16_conversions_round_and_saturate() {
    // The seed is the literal 1 rather than `env.args().len()`: the codegen
    // twin needs an opaque seed to survive -O2 constant folding and 1 is what
    // that yields under its harness, while `env.args()` in an IN-PROCESS
    // interpreter test reports the TEST binary's argv (same reasoning as
    // `test_optres_tuple_payload_is_owned_exactly_once`). The interpreter folds
    // nothing, so it needs no opacity — only the same values.
    assert_eq!(
        run(
            r#"
fn main() {
    let n = 1i64;
    let zero: i64 = n - 1;
    let onef: f32 = (n as f32);
    let a1: i8 = (-127i8 + (zero as i8));
    let a2: i8 = (3i8 + (zero as i8));
    let a3: u8 = (255u8 + (zero as u8));
    let a4: i16 = (257i16 + (zero as i16));
    let a5: i16 = (-12345i16 + (zero as i16));
    let a6: u16 = (65535u16 + (zero as u16));
    let a7: i32 = (2147483647i32 + (zero as i32));
    let a8: u32 = (4294967295u32 + (zero as u32));
    let a9: i64 = (9223372036854775807i64 + zero);
    let a10: i64 = (-9223372036854775807i64 + zero);
    let a11: u64 = (6148914691236517205u64 + (zero as u64));
    println(f"i2b {(a1 as bf16)} {(a2 as bf16)} {(a3 as bf16)} {(a4 as bf16)}");
    println(f"i2b {(a5 as bf16)} {(a6 as bf16)} {(a7 as bf16)} {(a8 as bf16)}");
    println(f"i2b {(a9 as bf16)} {(a10 as bf16)} {(a11 as bf16)}");
    let b1: bf16 = ((2.5f32 * onef) as bf16);
    let b2: bf16 = ((-2.5f32 * onef) as bf16);
    let b3: bf16 = ((1000.0f32 * onef) as bf16);
    let b4: bf16 = ((-1000.0f32 * onef) as bf16);
    let b5: bf16 = ((1.0e30f32 * onef) as bf16);
    let b6: bf16 = ((-1.0e30f32 * onef) as bf16);
    let b7: bf16 = ((0.4f32 * onef) as bf16);
    println(f"b2i {(b1 as i8)} {(b2 as i8)} {(b3 as i8)} {(b4 as i8)}");
    println(f"b2i {(b1 as u8)} {(b2 as u8)} {(b3 as u8)} {(b7 as u8)}");
    println(f"b2i {(b5 as i32)} {(b6 as i32)} {(b5 as u32)} {(b6 as u32)}");
    println(f"b2i {(b5 as i64)} {(b6 as i64)} {(b3 as i16)} {(b4 as i16)}");
}
"#
        ),
        "i2b -127 3 255 256\ni2b -12352 65536 2147483648 4294967296\ni2b 9223372036854776000 -9223372036854776000 6160924290242839000\nb2i 2 -2 127 -128\nb2i 2 0 255 0\nb2i 2147483647 -2147483648 4294967295 0\nb2i 9223372036854775807 -9223372036854775808 1000 -1000\n"
    );
}

#[test]
fn test_float_math_transcendental_and_rounding() {
    // Scalar transcendental + rounding math (`crate::float_math`): unary
    // `sin`/`cos`/`tan`/`exp`/`ln`/`log2`/`floor`/`ceil`/`round` and binary
    // `pow`/`atan2`, delegating to Rust's `f64::*`. Exact-result inputs so the
    // assertion is platform-independent (codegen's libm twin must match).
    assert_eq!(run("fn main() { println((0.0f64).sin()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).cos()); }"), "1\n");
    assert_eq!(run("fn main() { println((0.0f64).tan()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).exp()); }"), "1\n");
    assert_eq!(run("fn main() { println((1.0f64).ln()); }"), "0\n");
    assert_eq!(run("fn main() { println((1024.0f64).log2()); }"), "10\n");
    assert_eq!(
        run("fn main() { println((2.0f64).pow(10.0f64)); }"),
        "1024\n"
    );
    assert_eq!(run("fn main() { println((0.0f64).atan2(1.0f64)); }"), "0\n");
    assert_eq!(run("fn main() { println((2.7f64).floor()); }"), "2\n");
    assert_eq!(run("fn main() { println((2.2f64).ceil()); }"), "3\n");
    // `round` is half-away-from-zero (Rust `f64::round` / `llvm.round`).
    assert_eq!(run("fn main() { println((2.5f64).round()); }"), "3\n");
    assert_eq!(run("fn main() { println((-2.5f64).round()); }"), "-3\n");
    // Irrational checks — the interpreter is the f64 reference oracle.
    assert_eq!(
        run("fn main() { println((1.0f64).sin()); }"),
        "0.8414709848078965\n"
    );
    assert_eq!(
        run("fn main() { println((2.0f64).ln()); }"),
        "0.6931471805599453\n"
    );
}

#[test]
fn test_float_math_inverse_hyperbolic_and_extras() {
    // Second wave of the `crate::float_math` surface: inverse trig
    // (`asin`/`acos`/`atan`), hyperbolics (`sinh`/`cosh`/`tanh`), and
    // `exp2`/`log10`/`trunc`. Exact-result inputs so the assertion is
    // platform-independent (codegen's libm twin must match — the inverse-trig /
    // hyperbolic set lowers to direct libm calls, the rest to LLVM intrinsics).
    assert_eq!(run("fn main() { println((0.0f64).asin()); }"), "0\n");
    assert_eq!(run("fn main() { println((1.0f64).acos()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).atan()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).sinh()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).cosh()); }"), "1\n");
    assert_eq!(run("fn main() { println((0.0f64).tanh()); }"), "0\n");
    assert_eq!(run("fn main() { println((3.0f64).exp2()); }"), "8\n");
    assert_eq!(run("fn main() { println((1000.0f64).log10()); }"), "3\n");
    assert_eq!(run("fn main() { println((2.7f64).trunc()); }"), "2\n");
    assert_eq!(run("fn main() { println((-2.7f64).trunc()); }"), "-2\n");
    // Irrational check — the interpreter is the f64 reference oracle. Compared
    // numerically (not by exact string) because asin lowers to libm, whose
    // last ULP differs macOS vs Linux (see `assert_prints_float_near`).
    assert_prints_float_near(
        "fn main() { println((0.5f64).asin()); }",
        std::f64::consts::FRAC_PI_6,
    );
}

#[test]
fn test_float_math_hypot_inverse_hyperbolic_exp1p() {
    // Third wave of the `crate::float_math` surface: `hypot` (binary) plus the
    // inverse hyperbolics (`asinh`/`acosh`/`atanh`) and `exp_m1`/`ln_1p`. All
    // lower to direct libm calls in codegen (no LLVM intrinsic; `exp_m1`/`ln_1p`
    // map to libm's `expm1`/`log1p`). Exact-result inputs for a
    // platform-independent assertion; NB `cbrt` is intentionally excluded —
    // Rust's in-Rust `f64::cbrt` disagrees with libm's, breaking run == build.
    assert_eq!(run("fn main() { println((3.0f64).hypot(4.0f64)); }"), "5\n");
    assert_eq!(run("fn main() { println((0.0f64).asinh()); }"), "0\n");
    assert_eq!(run("fn main() { println((1.0f64).acosh()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).atanh()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).exp_m1()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).ln_1p()); }"), "0\n");
    // Irrational check — the interpreter is the f64 reference oracle. Compared
    // numerically (not by exact string): asinh lowers to libm, whose last ULP
    // differs macOS vs Linux (see `assert_prints_float_near`).
    assert_prints_float_near(
        "fn main() { println((0.7f64).asinh()); }",
        0.6526665660823557,
    );
}

#[test]
fn test_signum_signed_int_and_float() {
    // `x.signum()`: signed ints → -1 / 0 / 1 (`iN::signum`), floats →
    // -1.0 / +1.0 / NaN (`f64::signum`). The float form carries the sign of a
    // signed zero (`(-0.0).signum() == -1.0`) and preserves NaN — codegen
    // mirrors this with `copysign` + a NaN guard.
    assert_eq!(run("fn main() { println((42i64).signum()); }"), "1\n");
    assert_eq!(run("fn main() { println((-42i64).signum()); }"), "-1\n");
    assert_eq!(run("fn main() { println((0i64).signum()); }"), "0\n");
    assert_eq!(
        run("fn main() { println((0i32 - 7i32).signum()); }"),
        "-1\n"
    );
    assert_eq!(run("fn main() { println((3.5f64).signum()); }"), "1\n");
    assert_eq!(run("fn main() { println((-3.5f64).signum()); }"), "-1\n");
    // +0.0 → 1.0; -0.0 (built as `0.0 * -1.0`) → -1.0; NaN → NaN.
    assert_eq!(run("fn main() { println((0.0f64).signum()); }"), "1\n");
    assert_eq!(
        run("fn main() { let z: f64 = 0.0 * (0.0 - 1.0); println(z.signum()); }"),
        "-1\n"
    );
    assert_eq!(
        run("fn main() { let n: f64 = (0.0 - 1.0).sqrt(); println(n.signum()); }"),
        "NaN\n"
    );
}

#[test]
fn test_float_recip_and_angle_conversions() {
    // `recip` = `1.0 / x`; `to_degrees` / `to_radians` scale by Rust's exact
    // constants. Codegen replicates the same `fdiv`/`fmul` + constants, so the
    // irrational results below are bit-exact between `karac run` and
    // `karac build` (the interpreter is the f64 reference oracle).
    assert_eq!(run("fn main() { println((4.0f64).recip()); }"), "0.25\n");
    assert_eq!(run("fn main() { println((0.5f64).recip()); }"), "2\n");
    assert_eq!(run("fn main() { println((0.0f64).to_degrees()); }"), "0\n");
    assert_eq!(run("fn main() { println((0.0f64).to_radians()); }"), "0\n");
    assert_eq!(
        run("fn main() { println((1.0f64).to_radians()); }"),
        "0.017453292519943295\n"
    );
    assert_eq!(
        run("fn main() { println((1.0f64).to_degrees()); }"),
        "57.29577951308232\n"
    );
}

#[test]
fn test_float_copysign_and_fract() {
    // `copysign(x, y)` carries `y`'s sign onto `|x|` (a single sign-bit op);
    // `fract` = `x - x.trunc()`, sign-preserving. Both are exact IEEE
    // operations, so codegen (`llvm.copysign`, `fsub` against `llvm.trunc`)
    // matches the interpreter's `f64::*` bit-for-bit.
    assert_eq!(
        run("fn main() { println((3.5f64).copysign(-1.0f64)); }"),
        "-3.5\n"
    );
    assert_eq!(
        run("fn main() { println((-3.5f64).copysign(1.0f64)); }"),
        "3.5\n"
    );
    assert_eq!(run("fn main() { println((2.75f64).fract()); }"), "0.75\n");
    assert_eq!(run("fn main() { println((-2.75f64).fract()); }"), "-0.75\n");
    assert_eq!(run("fn main() { println((5.0f64).fract()); }"), "0\n");
    // Irrational fraction round-trips exactly (both sides do `x - trunc(x)`).
    assert_eq!(run("fn main() { println((0.1f64).fract()); }"), "0.1\n");
}

#[test]
fn test_float_bit_reinterpret_roundtrip() {
    // IEEE-754 bit reinterpretation: `to_bits`/`to_bits32` and the inverse
    // `bits_as_f64`/`bits_as_f32` round-trip a float through its integer bits.
    assert_eq!(
        run("fn main() { let d: f64 = 3.5; println(d.to_bits().bits_as_f64() == d); }"),
        "true\n"
    );
    assert_eq!(
        run("fn main() { let f: f32 = 2.25; println(f.to_bits32().bits_as_f32() == f); }"),
        "true\n"
    );
    // 1.0f64 has the bit pattern 0x3FF0000000000000.
    assert_eq!(
        run("fn main() { println((1.0f64).to_bits()); }"),
        "4607182418800017408\n"
    );
}

#[test]
fn test_abs_int_min_traps() {
    // `iN::MIN.abs()` has no representable result and traps as integer
    // overflow, matching the checked-neg arm — not a panic/ICE.
    let errors =
        runtime_errors("fn main() { let x = -9223372036854775807i64 - 1i64; println(x.abs()); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer overflow")),
        "expected integer-overflow trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_no_cascading_diagnostic_after_fault_in_compound_expr() {
    // B-2026-07-15-7: a runtime fault in a SUB-expression of a compound
    // operator expression must not cascade into a spurious second diagnostic.
    // `min / -1 + 0` lowers to `i64.add(i64.div(min, -1), 0)`; the div
    // overflows and sets `pending_cf`, but the lowered-operator dispatch used
    // to evaluate the `add`'s rhs anyway (short-circuiting it to `Unit` via
    // check_cf) and then run `eval_binary(Add, Unit, Unit)`, emitting a bogus
    // "operator 'Add' is not defined for operands of type 'Unit' and 'Unit'".
    // The fix short-circuits after the faulted operand, so exactly one error —
    // the real `integer overflow` — is reported.
    let errors = runtime_errors(
        "fn main() {\n\
             let m: i64 = -9223372036854775807i64 - 1i64;\n\
             let x: i64 = m / -1i64 + 0i64;\n\
             println(x);\n\
         }",
    );
    assert_eq!(
        errors.len(),
        1,
        "expected exactly one runtime error (no cascade), got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
    assert!(
        errors[0].message.contains("integer overflow"),
        "expected the sole error to be integer overflow, got: {:?}",
        errors[0].message
    );
    assert!(
        !errors[0].message.contains("is not defined for operands"),
        "must not surface the spurious operator-on-Unit cascade, got: {:?}",
        errors[0].message
    );

    // Same guarantee for a div-by-zero fault nested in a compound expression
    // (the other common sub-expression fault), and inside an f-string
    // interpolation (the original repro shape).
    let errors = runtime_errors(
        "fn main() {\n\
             let a: i64 = 10i64; let b: i64 = 0i64;\n\
             print(f\"{a / b + 5i64}\");\n\
         }",
    );
    assert_eq!(
        errors.len(),
        1,
        "div-by-zero in an f-string compound must not cascade, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
    assert!(errors[0].message.contains("division by zero"));
}

#[test]
fn test_i64_div_rem_euclid() {
    // `i64::{div_euclid, rem_euclid}` — the remainder is always non-negative,
    // so the quotient rounds toward negative infinity. Exercises all four
    // dividend/divisor sign combinations against Rust's semantics.
    let out = run("fn main() {\n\
             println((-7i64).div_euclid(3i64));\n\
             println((-7i64).rem_euclid(3i64));\n\
             println((7i64).div_euclid(3i64));\n\
             println((7i64).rem_euclid(3i64));\n\
             println((-7i64).div_euclid(-3i64));\n\
             println((-7i64).rem_euclid(-3i64));\n\
             println((7i64).div_euclid(-3i64));\n\
             println((7i64).rem_euclid(-3i64));\n\
             println((6i64).div_euclid(3i64));\n\
             println((6i64).rem_euclid(3i64));\n\
         }");
    assert_eq!(out, "-3\n2\n2\n1\n3\n2\n-2\n1\n2\n0\n");
}

#[test]
fn test_i64_div_rem_euclid_traps() {
    // Same trap set as `/` and `%`: a zero divisor is `division by zero`, and
    // `i64::MIN.{div,rem}_euclid(-1)` overflows (`checked_*_euclid` → None).
    for m in ["div_euclid", "rem_euclid"] {
        let errors = runtime_errors(&format!(
            "fn main() {{ let z: i64 = 0; println((5i64).{m}(z)); }}"
        ));
        assert!(
            errors
                .iter()
                .any(|e| e.message.contains("division by zero")),
            "expected division-by-zero trap for {m}, got: {:?}",
            errors.iter().map(|e| &e.message).collect::<Vec<_>>()
        );
        let errors = runtime_errors(&format!(
            "fn main() {{ let m: i64 = -9223372036854775807i64 - 1i64; \
             let n: i64 = 0i64 - 1i64; println(m.{m}(n)); }}"
        ));
        assert!(
            errors
                .iter()
                .any(|e| e.message.contains("integer overflow")),
            "expected MIN/-1 overflow trap for {m}, got: {:?}",
            errors.iter().map(|e| &e.message).collect::<Vec<_>>()
        );
    }
}

#[test]
fn test_narrow_int_overflow_traps() {
    // Narrow integers are real fixed-width types (design.md § Integer
    // overflow): `u8 200 + u8 100 = 300` overflows the width and traps,
    // rather than silently widening to i64. Codegen mirrors this.
    let errors = runtime_errors("fn main() { let a: u8 = 200; let b: u8 = 100; println(a + b); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer overflow")),
        "expected u8-overflow trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_overflow_arith_methods_width_correct() {
    // checked/saturating/overflowing _add/_sub/_mul are width-aware: the
    // receiver's width (recovered from the typechecker) sizes the overflow
    // check. i32 2e9+2e9 overflows (checked None / saturating MAX / overflowing
    // wraps+flags); i64 stays exact; u8 sub underflows to 0; u32 mul overflows.
    let out = run("fn main() {\n\
             let a = 2000000000i32;\n\
             match a.checked_add(2000000000i32) { Some(v) => println(v), None => println(-1i32) }\n\
             match a.checked_add(100i32) { Some(v) => println(v), None => println(-1i32) }\n\
             println(a.saturating_add(2000000000i32));\n\
             let u: u8 = 3u8;\n\
             println(u.saturating_sub(10u8));\n\
             let pair = a.overflowing_add(2000000000i32);\n\
             println(pair.0);\n\
             if pair.1 { println(1i32); } else { println(0i32); }\n\
             let big = 9000000000000000000i64;\n\
             match big.checked_add(big) { Some(v) => println(v), None => println(-7i64) }\n\
             let w: u32 = 4000000000u32;\n\
             println(w.checked_mul(2u32).is_none());\n\
             println(w.saturating_add(1000000000u32));\n\
         }");
    assert_eq!(
        out,
        "-1\n2000000100\n2147483647\n0\n-294967296\n1\n-7\ntrue\n4294967295\n"
    );
}

#[test]
fn test_int_pow_values_and_zero_exponent() {
    // `n.pow(k)` is repeated multiplication; `k` is `u32`. `pow(0)` is 1 for any
    // base. Defined on every integer width (here i64 / u64).
    let out = run("fn main() {\n\
             println(2i64.pow(10u32));\n\
             println(3i64.pow(0u32));\n\
             println(5i64.pow(3u32));\n\
             let e: u32 = 6;\n\
             println(2i64.pow(e));\n\
             let b: u64 = 1000000;\n\
             println(b.pow(2u32));\n\
         }");
    assert_eq!(out, "1024\n1\n125\n64\n1000000000000\n");
}

#[test]
fn test_int_pow_overflow_traps_at_receiver_width() {
    // `pow` traps `integer overflow` at the receiver width, like the `*` it
    // iterates: `u8 16^2 = 256` exceeds the u8 range and traps (it does not
    // silently widen to i64).
    let errors = runtime_errors("fn main() { let x: u8 = 16; println(x.pow(2u32)); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer overflow")),
        "expected u8 pow-overflow trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
    // i64 10^19 overflows i64 (10^18 fits).
    let errors = runtime_errors("fn main() { let b: i64 = 10; println(b.pow(19u32)); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer overflow")),
        "expected i64 pow-overflow trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_int_float_min_max() {
    // `a.min(b)` / `a.max(b)` on numeric scalars pick the smaller / larger,
    // like Rust's `Ord::min`/`max` (ints) and `f64::min`/`max` (floats). The
    // arg is the same numeric type (a bare literal coerces). Defined on signed,
    // unsigned, and float widths.
    let out = run("fn main() {\n\
             println(7i64.min(3i64));\n\
             println(7i64.max(3i64));\n\
             println((0 - 5i64).max(0i64));\n\
             let x: f64 = 1.5;\n\
             let y: f64 = 2.5;\n\
             println(x.min(y));\n\
             println(x.max(y));\n\
             let u: u8 = 200;\n\
             println(u.min(100u8));\n\
             let w: u32 = 4000000000;\n\
             println(w.max(1u32));\n\
         }");
    assert_eq!(out, "3\n7\n0\n1.5\n2.5\n100\n4000000000\n");
}

#[test]
fn test_int_float_clamp_method() {
    // `v.clamp(lo, hi)` (method sibling of the `clamp` free fn): pins `v` into
    // `[lo, hi]`, nested-bound form so `lo` wins on an inverted range. Defined
    // on signed / unsigned / float widths. Line 4 (`7.clamp(10, 5)`) pins the
    // inverted-range case, line 5–6 float, 7–8 unsigned.
    let out = run("fn main() {\n\
             println(15i64.clamp(0i64, 10i64));\n\
             println((0 - 3i64).clamp(0i64, 10i64));\n\
             println(5i64.clamp(0i64, 10i64));\n\
             println(7i64.clamp(10i64, 5i64));\n\
             let x: f64 = 1.5;\n\
             println(x.clamp(2.0, 3.0));\n\
             let y: f64 = 2.5;\n\
             println(y.clamp(0.0, 2.0));\n\
             let u: u8 = 200;\n\
             println(u.clamp(0u8, 100u8));\n\
             let w: u32 = 4000000000;\n\
             println(w.clamp(1u32, 4294967295u32));\n\
         }");
    assert_eq!(out, "10\n0\n5\n10\n2\n2\n100\n4000000000\n");
}

#[test]
fn test_bit_intrinsics_width_correct() {
    // count_ones / leading_zeros / trailing_zeros are width-dependent: they count
    // within the receiver's bit width. A signed `iN`'s sign-extended model value
    // is masked to width first (`i8 -1` has 8 set bits, not 64), and the all-zero
    // value has `bits` leading/trailing zeros.
    let out = run("fn main() {\n\
             let b: u8 = 200;\n\
             println(b.count_ones());\n\
             let n: u64 = 1024;\n\
             println(n.leading_zeros());\n\
             println(n.trailing_zeros());\n\
             let z: u8 = 0;\n\
             println(z.leading_zeros());\n\
             println(z.trailing_zeros());\n\
             let neg: i8 = -1;\n\
             println(neg.count_ones());\n\
             let m: i32 = 1;\n\
             println(m.leading_zeros());\n\
             let w: u32 = 0;\n\
             println(w.count_ones());\n\
         }");
    assert_eq!(out, "3\n53\n10\n8\n8\n8\n31\n0\n");
}

#[test]
fn test_bit_permute_and_count_zeros_width_correct() {
    // `count_zeros` (complement of count_ones), `reverse_bits`, and `swap_bytes`
    // are all width-dependent (Rust `iN::*`). `reverse_bits` reverses the
    // receiver's `bits`; `swap_bytes` reverses its bytes (identity on u8/i8).
    // A signed narrow result is sign-extended in the i64 model
    // (`1i8.reverse_bits() == -128`). Codegen mirrors this bit-for-bit
    // (`tests/codegen.rs::e2e_bit_permute_and_count_zeros_width_correct`).
    let out = run("fn main() {\n\
             println((200u8).count_zeros());\n\
             println((255u8).count_zeros());\n\
             println((0i64).count_zeros());\n\
             println((1u8).reverse_bits());\n\
             println((258u16).swap_bytes());\n\
             println((1u32).swap_bytes());\n\
             println((5u8).swap_bytes());\n\
             println((4278255360u32).reverse_bits());\n\
             println((1i8).reverse_bits());\n\
             println((1i32).reverse_bits());\n\
             let big: u64 = 1;\n\
             println(big.reverse_bits());\n\
         }");
    assert_eq!(
        out,
        // Last line: `1u64.reverse_bits()` = 2^63, which MUST print as the
        // unsigned 9223372036854775808 (not the signed -9223372036854775808).
        "5\n0\n64\n128\n513\n16777216\n5\n16711935\n-128\n-2147483648\n9223372036854775808\n"
    );
}

#[test]
fn test_bit_rotate_width_correct() {
    // `rotate_left(n)` / `rotate_right(n)` wrap within the receiver's `bits`
    // (Rust `iN::rotate_*`, amount mod width). Signed-narrow results
    // sign-extend (`1i8.rotate_right(1) == -128`); a `u64` result with the
    // high bit set prints unsigned. Codegen mirrors this via `llvm.fshl`/`fshr`
    // (`tests/codegen.rs::e2e_bit_rotate_width_correct`).
    let out = run("fn main() {\n\
             println((1u8).rotate_left(1));\n\
             println((128u8).rotate_left(1));\n\
             println((1u8).rotate_right(1));\n\
             println((16u32).rotate_right(4));\n\
             println((5u8).rotate_left(8));\n\
             println((1i8).rotate_right(1));\n\
             let big: u64 = 1;\n\
             println(big.rotate_left(63));\n\
         }");
    assert_eq!(out, "2\n1\n128\n1\n5\n-128\n9223372036854775808\n");
}

#[test]
fn test_is_power_of_two_unsigned() {
    // `uN::is_power_of_two` -> bool: true iff exactly one bit is set (0 is NOT a
    // power of two). Unsigned-only. Includes the 2^63 `u64` case (high bit set)
    // and narrow widths (u8/u16). Codegen mirrors this bit-for-bit
    // (`tests/codegen.rs::e2e_is_power_of_two_unsigned`).
    let out = run("fn main() {\n\
             println((1u32).is_power_of_two());\n\
             println((2u32).is_power_of_two());\n\
             println((3u32).is_power_of_two());\n\
             println((0u32).is_power_of_two());\n\
             let big: u64 = 1;\n\
             println(big.rotate_left(63).is_power_of_two());\n\
             println((128u8).is_power_of_two());\n\
             println((129u8).is_power_of_two());\n\
             println((1024u16).is_power_of_two());\n\
         }");
    assert_eq!(out, "true\ntrue\nfalse\nfalse\ntrue\ntrue\nfalse\ntrue\n");
}

#[test]
fn test_abs_diff_unsigned_result() {
    // `iN/uN::abs_diff(other) -> uN`: the absolute difference, always
    // non-negative, never overflows. Signed inputs (incl. i8 MIN/MAX → 255u8
    // and a near-full-i64-range diff that exceeds i64::MAX and MUST print as
    // the unsigned u64) and unsigned inputs are all covered. Codegen mirrors
    // this (`tests/codegen.rs::e2e_abs_diff_unsigned_result`).
    let out = run("fn main() {\n\
             let a: i32 = 5;\n\
             let b: i32 = 3;\n\
             println(a.abs_diff(b));\n\
             println(b.abs_diff(a));\n\
             let n: i32 = -5;\n\
             println(n.abs_diff(b));\n\
             let u: u32 = 3;\n\
             let v: u32 = 10;\n\
             println(u.abs_diff(v));\n\
             let x: u8 = 200;\n\
             let y: u8 = 10;\n\
             println(x.abs_diff(y));\n\
             let big: i64 = -9223372036854775807;\n\
             let top: i64 = 9223372036854775807;\n\
             println(big.abs_diff(top));\n\
             let s1: i8 = -128;\n\
             let s2: i8 = 127;\n\
             println(s1.abs_diff(s2));\n\
         }");
    // Line 3 (-5.abs_diff(3)) = 8; line 6 = 2*9223372036854775807 =
    // 18446744073709551614, which MUST print unsigned (not -2).
    assert_eq!(out, "2\n2\n8\n7\n190\n18446744073709551614\n255\n");
}

#[test]
fn test_next_power_of_two_unsigned() {
    // `uN::next_power_of_two`: smallest power of two ≥ self (0 and 1 → 1), at
    // the receiver width. Includes u8 128 (2^7, fits — no trap), u32 2^31, and
    // u64 2^63 / 2^63-1 (both → 2^63, which MUST print unsigned). Codegen
    // mirrors this (`tests/codegen.rs::e2e_next_power_of_two_unsigned`).
    let out = run("fn main() {\n\
             println((0u32).next_power_of_two());\n\
             println((1u32).next_power_of_two());\n\
             println((2u32).next_power_of_two());\n\
             println((3u32).next_power_of_two());\n\
             println((5u32).next_power_of_two());\n\
             println((100u32).next_power_of_two());\n\
             println((128u8).next_power_of_two());\n\
             let h: u32 = 1u32 << 31;\n\
             println(h.next_power_of_two());\n\
             let i: u64 = 1u64 << 63;\n\
             println(i.next_power_of_two());\n\
             let j: u64 = (1u64 << 63) - 1;\n\
             println(j.next_power_of_two());\n\
         }");
    assert_eq!(
        out,
        "1\n1\n2\n4\n8\n128\n128\n2147483648\n9223372036854775808\n9223372036854775808\n"
    );
}

#[test]
fn test_next_power_of_two_overflow_traps() {
    // The result would exceed the width (`u8 129` → 256 doesn't fit u8), so it
    // traps `integer overflow` — the same trap policy as `*`/`pow`.
    let errors = runtime_errors("fn main() { let g: u8 = 129; println(g.next_power_of_two()); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer overflow")),
        "expected an integer-overflow trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_char_to_digit_some_none_and_radix() {
    // `c.to_digit(radix) -> Option[u32]`: digit value in the given radix, None
    // when not a digit. Radix is u32 (suffix-free literal promotes); 'a'/'z'
    // count in hex/base-36.
    let out = run("fn main() {\n\
             match '7'.to_digit(10) { Some(d) => println(d), None => println(99u32) }\n\
             match 'a'.to_digit(16) { Some(d) => println(d), None => println(99u32) }\n\
             match 'z'.to_digit(36) { Some(d) => println(d), None => println(99u32) }\n\
             match 'x'.to_digit(10) { Some(d) => println(d), None => println(99u32) }\n\
             let r: u32 = 2;\n\
             match '1'.to_digit(r) { Some(d) => println(d), None => println(99u32) }\n\
         }");
    assert_eq!(out, "7\n10\n35\n99\n1\n");
}

#[test]
fn test_char_to_digit_radix_out_of_range_traps() {
    // An out-of-range radix (> 36) traps, matching Rust's `char::to_digit` panic.
    // The trap fires inside the `match` scrutinee — exercises the scrutinee-fault
    // short-circuit (otherwise the poison value matches no Some/None arm and the
    // tree-walker would hit a non-exhaustive `unreachable!`).
    let errors = runtime_errors(
        "fn main() { match '5'.to_digit(40) { Some(d) => println(d), None => println(0u32) } }",
    );
    assert!(
        errors.iter().any(|e| e.message.contains("radix")),
        "expected a to_digit radix-range trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_faulting_match_scrutinee_propagates_not_ice() {
    // Regression: a faulting expression in `match` scrutinee position (here an
    // index-out-of-bounds) sets the control-flow fault and must propagate as a
    // runtime error, NOT reach `eval_match`'s non-exhaustive `unreachable!`
    // when the poison value matches no arm.
    let errors = runtime_errors(
        "fn main() {\n\
         let v: Vec[i64] = Vec.new();\n\
         match v[5] { 0 => println(1i64), 1 => println(2i64) }\n\
         }",
    );
    assert!(
        !errors.is_empty(),
        "expected an out-of-bounds runtime error from the faulting scrutinee"
    );
}

#[test]
fn test_no_arm_match_degrades_to_runtime_error_not_panic() {
    // B-2026-07-17-6 defense-in-depth: if a match ever reaches
    // `eval_match` with no arm matching (a front-end gap), the interpreter
    // must degrade to a clean runtime diagnostic rather than a Rust
    // `unreachable!` panic. `Some(v)`/`None` against an `i64` is exactly such
    // a program — the typechecker now rejects it, but `run_program_full` runs
    // the interpreter regardless of type errors, so this exercises the
    // degraded path directly. Before the fix this panicked the interp thread.
    let errors = runtime_errors(
        "fn main() {\n\
             let x: i64 = 5;\n\
             match x {\n\
                 Some(v) => println(v),\n\
                 None => println(\"none\"),\n\
             }\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("non-exhaustive match")),
        "no-arm match must record a runtime error, got: {errors:?}"
    );
}

#[test]
fn test_legitimate_variant_matches_run() {
    // Parity guard for B-2026-07-17-6: the scrutinee-mismatch gate must not
    // disturb legitimate Option / Result / user-enum (bare + dotted) /
    // tuple-variant matches, which must still run and produce correct output.
    let out = run_no_errors(
        "enum Color { Red, Green, Blue }\n\
         enum Shape { Circle(i64), Square(i64) }\n\
         fn col(c: Color) -> i64 { match c { Red => 1, Color.Green => 2, _ => 3 } }\n\
         fn shp(s: Shape) -> i64 { match s { Shape.Circle(r) => r, Square(w) => w } }\n\
         fn opt(o: Option[i64]) -> i64 { match o { Some(v) => v, None => -1 } }\n\
         fn main() {\n\
             println(col(Color.Red));\n\
             println(col(Color.Green));\n\
             println(col(Color.Blue));\n\
             println(shp(Shape.Circle(7)));\n\
             println(shp(Shape.Square(4)));\n\
             println(opt(Some(9)));\n\
             println(opt(None));\n\
         }",
    );
    assert_eq!(out, "1\n2\n3\n7\n4\n9\n-1\n");
}

#[test]
fn test_narrow_int_in_range_does_not_trap() {
    // A narrow-int sum that fits the width is the value, no trap: `u8 97 + u8
    // 98 = 195` (≤ 255).
    assert_eq!(
        run("fn main() { let a: u8 = 97; let b: u8 = 98; println(a + b); }"),
        "195\n"
    );
}

#[test]
fn test_float_to_int_saturating() {
    // phase-8 cast slice 2: saturating clamps to the target's MIN/MAX and
    // truncates toward zero in range.
    assert_eq!(
        run("fn main() { println((3.7f64).saturating_to_i32()); }"),
        "3\n"
    );
    assert_eq!(
        run("fn main() { println((-3.7f64).saturating_to_i32()); }"),
        "-3\n"
    );
    assert_eq!(
        run("fn main() { println((1e30f64).saturating_to_i32()); }"),
        "2147483647\n"
    );
    assert_eq!(
        run("fn main() { println((-1e30f64).saturating_to_i32()); }"),
        "-2147483648\n"
    );
    assert_eq!(
        run("fn main() { println((1e30f64).saturating_to_u8()); }"),
        "255\n"
    );
    assert_eq!(
        run("fn main() { println((-1.0f64).saturating_to_u8()); }"),
        "0\n"
    );
}

#[test]
fn test_float_to_int_wrapping() {
    // Modular truncation: 300 → 44 in i8, 256 → 0 / 257 → 1 in u8.
    assert_eq!(
        run("fn main() { println((300.0f64).wrapping_to_i8()); }"),
        "44\n"
    );
    assert_eq!(
        run("fn main() { println((256.0f64).wrapping_to_u8()); }"),
        "0\n"
    );
    assert_eq!(
        run("fn main() { println((257.9f64).wrapping_to_u8()); }"),
        "1\n"
    );
}

#[test]
fn test_float_to_int_checked() {
    // `checked_*` → `Some(trunc)` in range, `None` on NaN / out-of-range.
    assert_eq!(
        run("fn main() { match (1.5f64).checked_to_i32() { Some(v) => println(v), None => println(-1) }; }"),
        "1\n"
    );
    assert_eq!(
        run("fn main() { match (1e30f64).checked_to_i32() { Some(v) => println(v), None => println(-1) }; }"),
        "-1\n"
    );
    assert_eq!(
        run("fn main() { match (f64.NAN).checked_to_i32() { Some(v) => println(v), None => println(-1) }; }"),
        "-1\n"
    );
}

#[test]
fn test_float_to_int_trunc_traps_out_of_range() {
    // `trunc_*` is the trapping form — out-of-range / NaN records a structured
    // "float-to-int out of range" runtime error (not a panic/ICE).
    let errors = runtime_errors("fn main() { println((1e30f64).trunc_to_i32()); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("float-to-int out of range")),
        "expected out-of-range trap, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
    // In-range `trunc_*` returns the truncated value.
    assert_eq!(
        run("fn main() { println((42.9f64).trunc_to_i32()); }"),
        "42\n"
    );
}

#[test]
fn test_int_to_float_methods() {
    // Symmetric `to_f32` / `to_f64` widen an integer to a float.
    assert_eq!(run("fn main() { println((42i64).to_f64()); }"), "42\n");
    assert_eq!(run("fn main() { println((42i32).to_f32()); }"), "42\n");
}

#[test]
fn test_unknown_primitive_method_is_runtime_error_not_ice() {
    // `karac run` bypasses typecheck enforcement, so an unknown method on a
    // primitive reaches the interpreter. It used to hit `unreachable!` and
    // panic (ICE); it now records a structured runtime error.
    let errors = runtime_errors("fn main() { let x = 5i64; let _ = x.bogus(); }");
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("bogus") && e.message.contains("i64")),
        "expected a structured runtime error, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_mmio_intrinsics_clean_error_not_panic() {
    // B-2026-07-12-7 — the tree-walk interpreter has no raw-pointer model, so
    // `ptr.mut`/`ptr.const` and `volatile_read`/`volatile_write` are codegen-
    // only. Reaching them used to panic with `unreachable!("variable 'ptr' not
    // found")` (the `ptr` receiver evaluated as an unbound identifier); they now
    // record a clean structured runtime error naming the intrinsic + the
    // `karac build` / non-`--interp` workaround.
    let errors = runtime_errors(
        "fn main() { let cell: i32 = 0; unsafe { let p: *const i32 = ptr.const(cell); } }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("ptr.const") && e.message.contains("codegen")),
        "expected a clean ptr-intrinsic runtime error, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
    // The `volatile_write` free-call peer.
    let errors = runtime_errors(
        "fn main() { let cell: i32 = 0; unsafe { volatile_write(ptr.mut(cell), 5); } }",
    );
    assert!(
        errors.iter().any(|e| e.message.contains("codegen")
            && (e.message.contains("volatile_write") || e.message.contains("ptr.mut"))),
        "expected a clean MMIO-intrinsic runtime error, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_fences_are_interpreter_noops() {
    // `fence` / `compiler_fence` (`runtime/stdlib/intrinsics.kara`) have empty
    // `#[compiler_builtin]` bodies. A single-threaded tree-walk interpreter
    // observes no memory reordering, so a fence is semantically inert there —
    // the empty body runs as a natural no-op (like `forget`), and the program
    // continues normally. (Codegen lowers them to real LLVM `fence`s; the
    // interpreter simply does nothing, which is the correct sequential
    // semantics.)
    assert_eq!(
        run("fn main() { unsafe { fence(MemoryOrdering.SeqCst) } compiler_fence(MemoryOrdering.Acquire); println(7); }"),
        "7\n"
    );
}

