#[test]
fn test_vec_deque_new_and_push_back() {
    let out = run(r#"
        fn main() {
            let mut q: VecDeque[i64] = VecDeque.new();
            q.push_back(1);
            q.push_back(2);
            q.push_back(3);
            println(q.len());
            println(q.is_empty());
        }
    "#);
    assert_eq!(out, "3\nfalse\n");
}

#[test]
fn test_vec_deque_push_front_then_pop_back_observes_correct_order() {
    // Mixed push_front/push_back with full pop_front/pop_back drain —
    // pins the front/back distinction under the shared `Vec[Value]`
    // storage that the interpreter uses internally.
    let out = run(r#"
        fn main() {
            let mut q: VecDeque[i64] = VecDeque.new();
            q.push_back(2);
            q.push_back(3);
            q.push_front(1);
            let f = q.pop_front();
            let b = q.pop_back();
            let m = q.pop_front();
            println(f);
            println(b);
            println(m);
        }
    "#);
    assert_eq!(out, "Some(1)\nSome(3)\nSome(2)\n");
}

#[test]
fn test_vec_deque_pop_empty_returns_none() {
    let out = run(r#"
        fn main() {
            let mut q: VecDeque[i64] = VecDeque.new();
            let f = q.pop_front();
            let b = q.pop_back();
            println(f);
            println(b);
        }
    "#);
    assert_eq!(out, "None\nNone\n");
}

#[test]
fn test_vec_insert_scalar_and_heap() {
    // `Vec[T].insert(idx, value)` — shift the tail up, place value at idx
    // (`idx == len` appends). Exercises front/middle/end for scalars and a
    // heap (String) element (move semantics). Interpreter is the oracle for the
    // codegen twin in tests/codegen.rs::test_e2e_vec_insert.
    let out = run(r#"
        fn main() {
            let mut v: Vec[i64] = [1, 2, 4, 5];
            v.insert(2, 3);
            v.insert(0, 0);
            v.insert(6, 6);
            let mut i = 0;
            while i < v.len() { print(f"{v[i]}"); i = i + 1; }
            println("");
            let mut s: Vec[String] = Vec.new();
            s.push(f"a");
            s.push(f"c");
            let mid = f"b-{1}";
            s.insert(1, mid);
            println(s[1]);
        }
    "#);
    assert_eq!(out, "0123456\nb-1\n");
}

// `Vec[T].pop()` — the bare form, alias for `pop_back`. Both the
// typechecker (`src/typechecker/expr_method_call.rs:1156`) and codegen
// (`src/codegen/vec_method.rs:300` collapses `pop | pop_back |
// pop_front` into one arm) already supported it; the interpreter
// dispatch arm was missing, so `karac run` panicked with
// "method 'pop' not found on type 'unknown'". Surfaced by
// kara-katas/leetcode/71-simplify-path which wanted stack-style
// push/pop on a `Vec[i64]`.
#[test]
fn test_vec_macro_literal_end_to_end() {
    // `vec![...]` desugars to the same node as `Vec[...]`, so it flows through
    // the interpreter unchanged. Pins the parser desugaring end-to-end.
    let out = run(r#"
        fn main() {
            let v = vec![10, 20, 30];
            let mut total = 0;
            for x in v {
                total = total + x;
            }
            println(total);
            let zeros = vec![0; 4];
            println(zeros.len());
        }
    "#);
    assert_eq!(out, "60\n4\n");
}

#[test]
fn test_vec_pop_returns_some_then_none_on_drain() {
    let out = run(r#"
        fn main() {
            let mut v: Vec[i64] = Vec.new();
            v.push(10);
            v.push(20);
            v.push(30);
            let a = v.pop();
            let b = v.pop();
            let c = v.pop();
            let d = v.pop();
            println(a);
            println(b);
            println(c);
            println(d);
            println(v.len());
        }
    "#);
    assert_eq!(out, "Some(30)\nSome(20)\nSome(10)\nNone\n0\n");
}

#[test]
fn test_vec_clear_and_extend() {
    // `Vec[T].clear()` empties the Vec (len → 0) and it stays usable
    // (push/extend rebuild it); `extend(other)` appends clones of `other`'s
    // elements. Exercised on a pod (`i64`) and a heap (`String`) element type
    // — the heap case is leak-checked in
    // `tests/memory_sanitizer.rs::asan_vec_clear_extend_heap_no_leak_no_double_free`.
    let out = run(r#"
        fn main() {
            let mut v: Vec[i64] = Vec.new();
            v.push(1);
            v.push(2);
            v.push(3);
            v.clear();
            println(v.len());
            v.push(9);
            let mut w: Vec[i64] = Vec.new();
            w.push(7);
            w.push(8);
            v.extend(w);
            println(v.len());
            println(v[0]);
            println(v[1]);
            println(v[2]);

            let mut s: Vec[String] = Vec.new();
            s.push("alpha");
            s.push("beta");
            s.clear();
            println(s.len());
            s.push("gamma");
            println(s[0]);
        }
    "#);
    assert_eq!(out, "0\n3\n9\n7\n8\n0\ngamma\n");
}

#[test]
fn test_vec_truncate() {
    // `Vec[T].truncate(n)` — shorten to at most `n` elements, dropping the tail;
    // `n >= len` is a no-op, `n < 0` clamps to 0. Exercised on pod (`i64`) and
    // heap (`String`) element types; heap-drop leak-safety is covered in
    // `tests/memory_sanitizer.rs::asan_vec_truncate_heap_no_leak`. Codegen
    // mirrors this (`tests/codegen.rs::e2e_vec_truncate`).
    let out = run(r#"
        fn main() {
            let mut a: Vec[i64] = Vec.new();
            a.push(1);
            a.push(2);
            a.push(3);
            a.push(4);
            a.truncate(2);
            println(a.len());
            println(a[0]);
            println(a[1]);
            a.truncate(5);
            println(a.len());
            a.truncate(0);
            println(a.len());

            let mut s: Vec[String] = Vec.new();
            s.push("aa");
            s.push("bb");
            s.push("cc");
            s.truncate(1);
            println(s.len());
            println(s[0]);
            s.push("dd");
            println(s.len());
            println(s[1]);
        }
    "#);
    assert_eq!(out, "2\n1\n2\n2\n0\n1\naa\n2\ndd\n");
}

#[test]
fn test_vec_swap_remove() {
    // `Vec[T].swap_remove(i) -> T` — O(1) remove: return element `i` and move
    // the LAST element into slot `i` (order NOT preserved). Covers a middle
    // index (swap-with-last) and heap (`String`) elements. Codegen mirrors this
    // (`tests/codegen.rs::e2e_vec_swap_remove`); heap leak-safety in
    // `tests/memory_sanitizer.rs::asan_vec_swap_remove_heap_no_leak`.
    let out = run(r#"
        fn main() {
            let mut a: Vec[i64] = Vec.new();
            a.push(10);
            a.push(20);
            a.push(30);
            a.push(40);
            let x = a.swap_remove(1);
            println(x);
            println(a.len());
            println(a[0]);
            println(a[1]);
            println(a[2]);

            let mut s: Vec[String] = Vec.new();
            s.push("aa");
            s.push("bb");
            s.push("cc");
            let z = s.swap_remove(0);
            println(z);
            println(s.len());
            println(s[0]);
            println(s[1]);
        }
    "#);
    // swap_remove(1) on [10,20,30,40] → returns 20, a=[10,40,30]; String
    // swap_remove(0) on [aa,bb,cc] → returns "aa", s=[cc,bb].
    assert_eq!(out, "20\n3\n10\n40\n30\naa\n2\ncc\nbb\n");
}

#[test]
fn test_vec_pop_string_elements() {
    // Non-Copy element type flows through the same dispatch — pins the
    // generic shape against future regressions where the arm might
    // accidentally specialize to numerics.
    let out = run(r#"
        fn main() {
            let mut v: Vec[String] = Vec.new();
            v.push("a");
            v.push("b");
            println(v.pop());
            println(v.pop());
            println(v.pop());
        }
    "#);
    assert_eq!(out, "Some(b)\nSome(a)\nNone\n");
}

#[test]
fn test_vec_pop_used_as_stack_for_simplify_path_shape() {
    // Mirrors the kata-katas/leetcode/71-simplify-path stack discipline:
    // push components, pop on `'..'`, skip on `'.'`, never underflow.
    // Tests that the `pop` arm interacts cleanly with the surrounding
    // push/len control flow the kata exercises.
    let out = run(r#"
        fn main() {
            let mut stack: Vec[i64] = Vec.new();
            stack.push(1);
            stack.push(2);
            stack.push(3);
            let _ = stack.pop();
            stack.push(4);
            let _ = stack.pop();
            let _ = stack.pop();
            println(stack.len());
            println(stack.pop());
            println(stack.pop());
        }
    "#);
    assert_eq!(out, "1\nSome(1)\nNone\n");
}

#[test]
fn test_vec_deque_iter_yields_in_front_to_back_order() {
    // `iter()` must yield items front-to-back. The runtime is
    // `Value::Array` so iter routes through the existing eager-
    // snapshot Iterator path; this pins the order against shape
    // changes.
    let out = run(r#"
        fn main() {
            let mut q: VecDeque[i64] = VecDeque.new();
            q.push_back(20);
            q.push_back(30);
            q.push_front(10);
            for x in q.iter() {
                println(x);
            }
        }
    "#);
    assert_eq!(out, "10\n20\n30\n");
}

#[test]
fn test_vec_deque_string_elements() {
    // Non-Copy element type flows through unchanged.
    let out = run(r#"
        fn main() {
            let mut q: VecDeque[String] = VecDeque.new();
            q.push_back("first");
            q.push_back("second");
            q.push_front("zero");
            let f = q.pop_front();
            let b = q.pop_back();
            println(f);
            println(b);
        }
    "#);
    assert_eq!(out, "Some(zero)\nSome(second)\n");
}

#[test]
fn test_vec_deque_bfs_frontier_pattern() {
    // The kata's actual workflow shape: a BFS frontier with
    // push_back at the producer side and pop_front at the consumer
    // side. Verifies FIFO order with mixed enqueue/dequeue.
    let out = run(r#"
        fn main() {
            let mut frontier: VecDeque[i64] = VecDeque.new();
            frontier.push_back(1);
            let mut count = 0;
            loop {
                let next = frontier.pop_front();
                match next {
                    Some(node) => {
                        count = count + 1;
                        if node < 3 {
                            frontier.push_back(node + 1);
                            frontier.push_back(node + 2);
                        }
                    },
                    None => { break; },
                }
            }
            println(count);
        }
    "#);
    // Frontier: [1] → pop 1 (1), push 2,3 → [2,3]
    //               → pop 2 (2), push 3,4 → [3,3,4]
    //               → pop 3 (3), no push     → [3,4]
    //               → pop 3 (4), no push     → [4]
    //               → pop 4 (5), no push     → []
    //               → pop None, break. count=5.
    assert_eq!(out, "5\n");
}

// ── `Vec.filled(n, val)` (design.md:1631) ───────────────────────

#[test]
fn test_vec_filled_i64() {
    // `Vec.filled(3, 7)` → length 3, all 7s.
    let out = run(r#"
        fn main() {
            let v: Vec[i64] = Vec.filled(3, 7);
            println(v.len());
            println(v[0]);
            println(v[2]);
        }
    "#);
    assert_eq!(out, "3\n7\n7\n");
}

#[test]
fn test_vec_filled_bool() {
    // Kata's actual usage shape: `Vec.filled(n, false)` for a
    // visited bitset, then index-write through it.
    let out = run(r#"
        fn main() {
            let mut visited: Vec[bool] = Vec.filled(5, false);
            visited[2] = true;
            println(visited.len());
            println(visited[0]);
            println(visited[2]);
            println(visited[4]);
        }
    "#);
    assert_eq!(out, "5\nfalse\ntrue\nfalse\n");
}

#[test]
fn test_vec_filled_string() {
    // Non-`Copy` element type — the per-slot clone in the dispatch
    // arm satisfies the spec's `T: Clone` requirement.
    let out = run(r#"
        fn main() {
            let v: Vec[String] = Vec.filled(2, "hi");
            println(v.len());
            println(v[0]);
            println(v[1]);
        }
    "#);
    assert_eq!(out, "2\nhi\nhi\n");
}

#[test]
fn test_vec_filled_nested_vec_independent_storage() {
    // `Vec.filled(n, Vec.new())` must produce n independent Vecs —
    // a per-slot deep clone, not an `Arc`-bump (the interpreter's
    // `Value::Array` storage is `Arc<RwLock<...>>`; the default
    // `Value::Clone` would alias every slot to the same underlying
    // Vec, so pushing into one would be visible in all). Spec says
    // `Vec.filled[T: Clone]` — Clone semantics for `Vec[T]` are deep.
    let out = run(r#"
        fn main() {
            let mut grid: Vec[Vec[i64]] = Vec.filled(3, Vec.new());
            grid[0].push(99);
            println(grid[0].len());
            println(grid[1].len());
            println(grid[2].len());
        }
    "#);
    assert_eq!(out, "1\n0\n0\n");
}

#[test]
fn test_vec_filled_zero_length() {
    // `Vec.filled(0, x)` is legal — produces an empty Vec.
    let out = run(r#"
        fn main() {
            let v: Vec[i64] = Vec.filled(0, 99);
            println(v.len());
        }
    "#);
    assert_eq!(out, "0\n");
}

#[test]
fn test_vec_filled_negative_length_runtime_error() {
    // Negative length is a runtime error — Kāra has no usize,
    // so the typechecker accepts `i64` and the interpreter
    // guards at the call site.
    let errs = runtime_errors(
        r#"
        fn main() {
            let v: Vec[i64] = Vec.filled(-1, 0);
            println(v.len());
        }
    "#,
    );
    assert!(
        errs.iter()
            .any(|e| format!("{e:?}").contains("Vec.filled length must be non-negative")),
        "expected non-negative-length runtime error; got: {errs:?}"
    );
}

// ── `Vec.with_capacity(n)` ──────────────────────────────────────

#[test]
fn test_vec_with_capacity_len_is_zero_then_push_works() {
    // `Vec.with_capacity(N)` returns an empty Vec — `len() == 0`
    // — but the underlying buffer is sized for at least N pushes
    // without reallocating. Test verifies the observable contract:
    // initial len is 0, push fills slots 0..N correctly.
    let out = run(r#"
        fn main() {
            let mut v: Vec[i64] = Vec.with_capacity(5);
            println(v.len());
            let mut i = 0i64;
            while i < 5 {
                v.push(i * 10);
                i = i + 1;
            }
            println(v.len());
            println(v[0]);
            println(v[4]);
        }
    "#);
    assert_eq!(out, "0\n5\n0\n40\n");
}

#[test]
fn test_vec_with_capacity_zero_is_legal() {
    // `Vec.with_capacity(0)` is the degenerate case — same shape as
    // `Vec.new()`. Subsequent push grows from there.
    let out = run(r#"
        fn main() {
            let mut v: Vec[i64] = Vec.with_capacity(0);
            println(v.len());
            v.push(42);
            println(v.len());
            println(v[0]);
        }
    "#);
    assert_eq!(out, "0\n1\n42\n");
}

#[test]
fn test_vec_nested_indexed_write_round_trip() {
    // `rows[r][c] = val` on `Vec[Vec[T]]` — the kata-6 _faster
    // shape that previously needed a flat-layout workaround.
    // Pre-fix, the interpreter's set_index silently no-op'd on
    // non-Identifier targets, and codegen errored "Index
    // assignment target must be a variable". Both now route
    // through to the leaf slot.
    let out = run(r#"
        fn main() {
            let mut rows: Vec[Vec[i64]] = Vec.new();
            let r0: Vec[i64] = Vec.filled(3, 0);
            let r1: Vec[i64] = Vec.filled(3, 0);
            rows.push(r0);
            rows.push(r1);
            rows[0][1] = 42;
            rows[1][2] = 99;
            println(rows[0][0]);
            println(rows[0][1]);
            println(rows[1][2]);
        }
    "#);
    assert_eq!(out, "0\n42\n99\n");
}

#[test]
fn test_field_index_write_round_trip_plain_and_shared() {
    // `obj.field[i] = val` — the write half of the kata-133-audit
    // FieldAccess-rooted indexing bug (2026-06-06). Pre-fix, the
    // interpreter's set_index hit the catch-all `_ => return` arm for
    // FieldAccess targets and SILENTLY no-op'd the store (the program
    // ran but printed the stale value); codegen errored "Index
    // assignment target must be a variable". Both now route through:
    // the interpreter evals the field access (Value::Array clones the
    // Arc, aliasing the field's storage), codegen goes through
    // `lower_field_access_ptr` + a synth identifier. Plain and shared
    // structs both covered.
    let out = run_no_errors(
        r#"
        struct Holder { tag: i64, mut items: Vec[i64] }
        shared struct Cell { mut vals: Vec[i64] }
        fn main() {
            let mut v: Vec[i64] = Vec.new();
            v.push(41);
            v.push(42);
            let mut h = Holder { tag: 7, items: v };
            h.items[0] = 99;
            println(h.items[0]);
            println(h.items[1]);

            let mut w: Vec[i64] = Vec.new();
            w.push(5);
            let c = Cell { vals: w };
            c.vals[0] = 6;
            println(c.vals[0]);
        }
    "#,
    );
    assert_eq!(out, "99\n42\n6\n");
}

#[test]
fn test_vec_with_capacity_untyped_let_inference_from_push() {
    // `let mut v = Vec.with_capacity(n); v.push(x);` — no annotation
    // on the let; element type is inferred from the downstream push.
    // Mirrors `let mut v = Vec.new(); v.push(x);`. Without the
    // typechecker arm in expr_call.rs, the call returned
    // Type::Error, the binding's inner-type table stayed empty, and
    // codegen errored "element type unknown — requires `let v:
    // Vec[T] = ...` annotation".
    let out = run(r#"
        fn main() {
            let mut v = Vec.with_capacity(5);
            v.push(10);
            v.push(20);
            v.push(30);
            println(v.len());
            println(v[0]);
            println(v[2]);
        }
    "#);
    assert_eq!(out, "3\n10\n30\n");
}

#[test]
fn test_vec_with_capacity_negative_runtime_error() {
    // Mirrors `Vec.filled`'s negative-length guard. Kāra has no
    // usize, so the typechecker accepts `i64` and the runtime
    // rejects negatives.
    let errs = runtime_errors(
        r#"
        fn main() {
            let v: Vec[i64] = Vec.with_capacity(-1);
            println(v.len());
        }
    "#,
    );
    assert!(
        errs.iter()
            .any(|e| format!("{e:?}").contains("Vec.with_capacity capacity must be non-negative")),
        "expected non-negative-capacity runtime error; got: {errs:?}"
    );
}

// ── `vec.extend_from_slice(other)` ──────────────────────────────

#[test]
fn test_vec_extend_from_slice_from_vec() {
    // Append all elements of `src: Vec[i64]` to `dst: Vec[i64]`.
    let out = run(r#"
        fn main() {
            let src: Vec[i64] = Vec.filled(3, 7);
            let mut dst: Vec[i64] = Vec.new();
            dst.push(1);
            dst.push(2);
            dst.extend_from_slice(src);
            println(dst.len());
            println(dst[0]);
            println(dst[1]);
            println(dst[2]);
            println(dst[4]);
        }
    "#);
    assert_eq!(out, "5\n1\n2\n7\n7\n");
}

#[test]
fn test_vec_extend_from_slice_into_empty() {
    // Extending an empty `dst` should just clone source elements.
    let out = run(r#"
        fn main() {
            let src: Vec[i64] = Vec.filled(4, 9);
            let mut dst: Vec[i64] = Vec.new();
            dst.extend_from_slice(src);
            println(dst.len());
            println(dst[0]);
            println(dst[3]);
        }
    "#);
    assert_eq!(out, "4\n9\n9\n");
}

#[test]
fn test_vec_extend_from_slice_nested_index_source() {
    // `rows[r]` (Index expr on Vec[Vec[T]]) as source — the
    // kata-6 use case. The interpreter resolves the Index to a
    // fresh Vec value; per-element `deep_clone_value` keeps source
    // and dest independent.
    let out = run(r#"
        fn main() {
            let mut rows: Vec[Vec[i64]] = Vec.new();
            let mut r0: Vec[i64] = Vec.new();
            r0.push(10);
            r0.push(20);
            rows.push(r0);
            let mut r1: Vec[i64] = Vec.new();
            r1.push(30);
            rows.push(r1);

            let mut out: Vec[i64] = Vec.with_capacity(8);
            let mut i = 0i64;
            while i < 2 {
                out.extend_from_slice(rows[i]);
                i = i + 1;
            }
            println(out.len());
            println(out[0]);
            println(out[1]);
            println(out[2]);
        }
    "#);
    assert_eq!(out, "3\n10\n20\n30\n");
}

#[test]
fn test_comparison() {
    assert_eq!(run("fn main() { println(3 > 2); }"), "true\n");
    assert_eq!(run("fn main() { println(3 < 2); }"), "false\n");
    assert_eq!(run("fn main() { println(5 == 5); }"), "true\n");
}

#[test]
fn test_comparison_and_equality_post_lowering() {
    // Exercises every comparison/equality op going through the lowered
    // `T.eq` / `T.lt` / etc. Call-path at runtime.
    assert_eq!(run("fn main() { println(3 != 4); }"), "true\n");
    assert_eq!(run("fn main() { println(3 != 3); }"), "false\n");
    assert_eq!(run("fn main() { println(4 <= 4); }"), "true\n");
    assert_eq!(run("fn main() { println(4 >= 5); }"), "false\n");
    assert_eq!(
        run(r#"fn main() { let a: String = "foo"; let b: String = "foo"; println(a == b); }"#),
        "true\n"
    );
    assert_eq!(
        run(r#"fn main() { let a: String = "foo"; let b: String = "bar"; println(a != b); }"#),
        "true\n"
    );
}

#[test]
fn test_bitwise_ops_post_lowering() {
    // `&`, `|`, `^`, `<<`, `>>` all flow through the lowered Call path.
    assert_eq!(run("fn main() { println(0b1100 & 0b1010); }"), "8\n");
    assert_eq!(run("fn main() { println(0b1100 | 0b1010); }"), "14\n");
    assert_eq!(run("fn main() { println(0b1100 ^ 0b1010); }"), "6\n");
    assert_eq!(run("fn main() { println(1 << 3); }"), "8\n");
    assert_eq!(run("fn main() { println(16 >> 2); }"), "4\n");
}

#[test]
fn test_bitnot_and_not_post_lowering() {
    // `~int` lowers to `int.not`, `not bool` lowers to `bool.not`.
    assert_eq!(run("fn main() { println(~0); }"), "-1\n");
    assert_eq!(run("fn main() { println(not false); }"), "true\n");
}

#[test]
fn test_user_impl_eq_drives_equality_operator() {
    // `impl Eq for Point` is registered, and `a == b` lowers to
    // `Point.eq(a, b)` — routed through the user-defined method rather than
    // any structural fallback. CR-202 slice 5b: companion
    // `impl PartialEq for Point` satisfies the new `Eq: PartialEq`
    // supertrait edge so the typecheck pass stays clean.
    assert_eq!(
        run("struct Point { x: i64, y: i64 }
             impl PartialEq for Point {
                 fn eq(ref self, other: ref Point) -> bool {
                     self.x == other.x and self.y == other.y
                 }
             }
             impl Eq for Point {
                 fn eq(self, other: Point) -> bool {
                     self.x == other.x and self.y == other.y
                 }
             }
             fn main() {
                 let a = Point { x: 1, y: 2 };
                 let b = Point { x: 1, y: 2 };
                 let c = Point { x: 9, y: 9 };
                 println(a == b);
                 println(a != c);
             }"),
        "true\ntrue\n"
    );
}

#[test]
fn test_user_impl_ord_cmp_body_drives_comparison_operators() {
    // B-2026-08-26-10 — the IDIOMATIC ordering impl: `trait Ord` declares
    // exactly one method, `cmp`, so this is the shape an author who reads
    // design.md writes. It used to lower to `Item.lt(a, b)` — a method the
    // trait does not declare and this impl does not define — and died with
    // `path 'Item.lt' has no interpreter evaluation rule`. It now lowers to
    // `Item.cmp(a, b).is_lt()`.
    //
    // The `cmp` REVERSES the order on purpose. That is what makes this a test
    // of DISPATCH rather than of compilation: field declaration order would
    // answer `true false true false` for ids 1 vs 5, and the body demands the
    // exact opposite. A `cmp` that merely agreed with declaration order would
    // pass this test while dispatching nowhere.
    assert_eq!(
        run("struct Item { id: i64 }
             impl PartialEq for Item { fn eq(ref self, other: ref Item) -> bool { self.id == other.id } }
             impl Eq for Item {}
             impl PartialOrd for Item {
                 fn partial_cmp(ref self, other: ref Item) -> Option[Ordering] { Some(other.id.cmp(self.id)) }
             }
             impl Ord for Item {
                 fn cmp(ref self, other: ref Item) -> Ordering { other.id.cmp(self.id) }
             }
             fn main() {
                 let a = Item { id: 1 };
                 let b = Item { id: 5 };
                 println(a < b);
                 println(a > b);
                 println(a <= b);
                 println(a >= b);
             }"),
        "false\ntrue\nfalse\ntrue\n"
    );
}

#[test]
fn test_user_cmp_method_call_is_not_answered_by_the_builtin_comparator() {
    // The `.cmp()` half of B-2026-08-26-10, which is what made the operator fix
    // land on a wrong answer in compiled output until it was fixed too: codegen's
    // builtin `method == "cmp"` arm answered for a user `impl Ord` whose receiver
    // flattened to an int, comparing the FIELD instead of running the body.
    //
    // `cmp` here returns `Ordering.Greater` unconditionally, so a backend that
    // runs the body must print `false` and one that compares `id` (1 vs 5) must
    // print `true`. The interpreter always got this right; this pins the answer
    // it must keep agreeing with (see the codegen twin,
    // `e2e_user_cmp_method_call_is_not_answered_by_the_builtin_comparator`).
    assert_eq!(
        run("struct Item { id: i64 }
             impl PartialEq for Item { fn eq(ref self, other: ref Item) -> bool { self.id == other.id } }
             impl Eq for Item {}
             impl PartialOrd for Item {
                 fn partial_cmp(ref self, other: ref Item) -> Option[Ordering] { Some(Ordering.Greater) }
             }
             impl Ord for Item {
                 fn cmp(ref self, other: ref Item) -> Ordering { Ordering.Greater }
             }
             fn main() {
                 let a = Item { id: 1 };
                 let b = Item { id: 5 };
                 println(a.cmp(b).is_lt());
                 println(a < b);
             }"),
        "false\nfalse\n"
    );
}

#[test]
fn interp_map_and_set_honour_a_hand_written_hash_and_eq() {
    // The interpreter half of B-2026-08-26-10's `Map` hashing, pinned separately
    // because it reaches the user's impl by a different route: codegen calls a
    // synthesized `karac_hash_bytes_of_T`, while the interpreter runs the impl in
    // a sub-interpreter from inside `MapData`, which has no interpreter of its own.
    //
    // Both impls key on `id` alone while `tag` varies, so every line fails under
    // structural hashing or structural equality.
    assert_eq!(
        run("struct Item { id: i64, tag: i64 }
             impl PartialEq for Item { fn eq(ref self, other: ref Item) -> bool { self.id == other.id } }
             impl Eq for Item {}
             impl Hash for Item { fn hash[H: Hasher](ref self, hasher: mut ref H) { hasher.write_i64(self.id) } }
             fn main() {
                 let mut m: Map[Item, i64] = Map.new();
                 m.insert(Item { id: 1, tag: 100 }, 10);
                 m.insert(Item { id: 2, tag: 200 }, 20);
                 m.insert(Item { id: 1, tag: 999 }, 11);
                 println(m.len());
                 match m.get(Item { id: 1, tag: 0 }) { Some(v) => println(v), None => println(-1) }
                 println(m.contains_key(Item { id: 2, tag: 7 }));
                 m.remove(Item { id: 2, tag: 12345 });
                 println(m.len());
                 let mut s: Set[Item] = Set.new();
                 s.insert(Item { id: 5, tag: 1 });
                 s.insert(Item { id: 5, tag: 2 });
                 println(s.len());
                 println(s.contains(Item { id: 5, tag: 3 }));
             }"),
        "2\n11\ntrue\n1\n1\ntrue\n"
    );
    // The derive path must be undisturbed — every answer structural.
    assert_eq!(
        run("#[derive(Hash, Eq, PartialEq)]
             struct Item { id: i64, tag: i64 }
             fn main() {
                 let mut m: Map[Item, i64] = Map.new();
                 m.insert(Item { id: 1, tag: 100 }, 10);
                 m.insert(Item { id: 1, tag: 999 }, 11);
                 println(m.len());
                 match m.get(Item { id: 1, tag: 0 }) { Some(v) => println(v), None => println(-1) }
             }"),
        "2\n-1\n"
    );
}

#[test]
fn interp_priority_queue_honours_a_hand_written_ord_impl() {
    // The INTERPRETER half of B-2026-08-26-24, and it needed a different fix
    // from the compiled half — which is the point of pinning it separately.
    //
    // Lowering rewrites `a < b` into `a.cmp(b).is_lt()` when it can see the
    // operand's type, and for a `T: Ord` param it reads the bound. It cannot see
    // either inside a STDLIB body: the baked stdlib is signature-registered, not
    // type-checked in the user's pipeline, so `expr_types` is empty for it and
    // the rewrite is skipped. `PriorityQueue`'s `self.xs[i] < self.xs[j]` is
    // exactly that. codegen was unaffected because it lowers its stdlib from
    // source — so fixing only lowering left the two backends DISAGREEING, with
    // the compiled binary right and the interpreter erroring. The interpreter
    // now dispatches to a hand-written comparator at runtime.
    //
    // The impl reverses, so the queue pops 3, 2, 1; a derive pops 1, 2, 3.
    assert_eq!(
        run("struct Item { id: i64 }
             impl PartialEq for Item { fn eq(ref self, other: ref Item) -> bool { self.id == other.id } }
             impl Eq for Item {}
             impl PartialOrd for Item { fn partial_cmp(ref self, other: ref Item) -> Option[Ordering] { Some(other.id.cmp(self.id)) } }
             impl Ord for Item { fn cmp(ref self, other: ref Item) -> Ordering { other.id.cmp(self.id) } }
             fn main() {
                 let mut q: PriorityQueue[Item] = PriorityQueue.new();
                 q.push(Item { id: 1 });
                 q.push(Item { id: 3 });
                 q.push(Item { id: 2 });
                 while q.len() > 0 { match q.pop() { Some(it) => println(it.id), None => {} } }
             }"),
        "3\n2\n1\n"
    );
    // The derive path must be untouched.
    assert_eq!(
        run("#[derive(PartialEq, Eq, PartialOrd, Ord)]
             struct Item { id: i64 }
             fn main() {
                 let mut q: PriorityQueue[Item] = PriorityQueue.new();
                 q.push(Item { id: 1 });
                 q.push(Item { id: 3 });
                 q.push(Item { id: 2 });
                 while q.len() > 0 { match q.pop() { Some(it) => println(it.id), None => {} } }
             }"),
        "1\n2\n3\n"
    );
}

#[test]
fn test_user_impl_ord_drives_comparison_operators() {
    // `impl Ord for Point` with direct `lt`/`le`/`gt`/`ge` methods — `<`
    // lowers to `Point.lt(a, b)`, etc. Domain-specific ordering (here by x
    // only) rather than the interpreter's hardcoded primitive path.
    // CR-202 slice 5d: companion PartialEq/Eq/PartialOrd impls satisfy
    // the new `Ord: PartialOrd + Eq` supertrait edges (typecheck-clean;
    // interpreter execution behavior is unchanged).
    assert_eq!(
        run("struct Point { x: i64, y: i64 }
             impl PartialEq for Point {
                 fn eq(ref self, other: ref Point) -> bool { self.x == other.x and self.y == other.y }
             }
             impl Eq for Point {}
             impl PartialOrd for Point {
                 fn partial_cmp(ref self, other: ref Point) -> Option[Ordering] { Some(self.x.cmp(other.x)) }
             }
             impl Ord for Point {
                 fn lt(self, other: Point) -> bool { self.x < other.x }
                 fn le(self, other: Point) -> bool { self.x <= other.x }
                 fn gt(self, other: Point) -> bool { self.x > other.x }
                 fn ge(self, other: Point) -> bool { self.x >= other.x }
             }
             fn main() {
                 let a = Point { x: 1, y: 99 };
                 let b = Point { x: 5, y: 1 };
                 println(a < b);
                 println(a > b);
                 println(a <= b);
             }"),
        "true\nfalse\ntrue\n"
    );
}

#[test]
fn test_eq_ord_direct_method_calls() {
    // `i32.lt(a, b)` and peers are callable directly in user code, matching
    // the lowered form of the operator. Verifies the whole typecheck → lower
    // → interpret pipeline for the Eq/Ord method names.
    assert_eq!(
        run("fn main() {
                 let a: i32 = 3;
                 let b: i32 = 5;
                 println(i32.lt(a, b));
                 println(i32.ge(a, b));
                 println(i32.eq(a, a));
                 println(i32.ne(a, b));
             }"),
        "true\nfalse\ntrue\ntrue\n"
    );
}

#[test]
fn test_derive_ord_cmp_method() {
    // roadmap Phase 8 § Eq/Ord: `.cmp() -> Ordering` on a `#[derive(Ord)]`
    // struct/enum — the method form of the already-working `<`/`>` operators,
    // reusing the same lexicographic order (`value_compare`). Struct fields
    // compare in DECLARATION order; enum variants by declaration index. This
    // is what unblocks `min`/`max`/`clamp` and `sort_by` on user Ord types.
    assert_eq!(
        run(r#"
            #[derive(Ord, Eq, PartialEq, PartialOrd)]
            struct Rec { name: String, age: i64 }
            #[derive(Ord, Eq, PartialEq, PartialOrd)]
            enum Priority { Low, Med, High }
            fn tag(o: Ordering) -> String {
                match o { Less => "lt".to_string(), Equal => "eq".to_string(), Greater => "gt".to_string() }
            }
            fn main() {
                let r1 = Rec { name: "alice".to_string(), age: 30 };
                let r2 = Rec { name: "alice".to_string(), age: 40 };
                let r3 = Rec { name: "bob".to_string(), age: 10 };
                println(tag(r1.cmp(r2)));
                println(tag(r1.cmp(r3)));
                println(tag(r2.cmp(r1)));
                let lo = Priority.Low;
                let hi = Priority.High;
                let md = Priority.Med;
                println(tag(lo.cmp(hi)));
                println(tag(hi.cmp(md)));
                println(tag(md.cmp(md)));
                // min/max/clamp on struct types now resolve (they call .cmp)
                let mx = max(r1, r3);
                println(mx.name);
            }
        "#),
        "lt\nlt\ngt\nlt\ngt\neq\nbob\n"
    );
}

