#[test]
fn test_vec_remove_local() {
    // `Vec.remove(idx) -> T` on a local: returns the removed element,
    // shifts the tail down, decrements len. Interpreter parity with
    // codegen's `test_e2e_vec_remove_local` (same program + output).
    assert_eq!(
        run("fn main() {\n\
                 let mut xs: Vec[i64] = Vec.new();\n\
                 xs.push(10);\n\
                 xs.push(20);\n\
                 xs.push(30);\n\
                 let removed: i64 = xs.remove(1);\n\
                 println(removed);\n\
                 println(xs.len());\n\
                 println(xs[0]);\n\
                 println(xs[1]);\n\
             }"),
        "20\n2\n10\n30\n"
    );
}

#[test]
fn test_vec_remove_first_and_last() {
    // Remove the head (memmoves the whole tail down) then the new last.
    // Mirrors codegen's `test_e2e_vec_remove_first` / `_last` semantics.
    assert_eq!(
        run("fn main() {\n\
                 let mut xs: Vec[i64] = Vec.new();\n\
                 xs.push(1);\n\
                 xs.push(2);\n\
                 xs.push(3);\n\
                 let _ = xs.remove(0);\n\
                 println(xs[0]);\n\
                 println(xs.len());\n\
                 let _ = xs.remove(1);\n\
                 println(xs[0]);\n\
                 println(xs.len());\n\
             }"),
        "2\n2\n2\n1\n"
    );
}

#[test]
fn test_vec_remove_through_mut_ref_param() {
    // The case that first surfaced this gap: `Vec.remove` on a
    // `mut ref Vec[T]` receiver must write back to the caller's vector.
    // The interpreter's `Value::Array` shares its `Arc`-backed storage
    // across the borrow, so the removal propagates — same aliasing the
    // `push` arm relies on.
    assert_eq!(
        run("fn drain_first(v: mut ref Vec[i64]) -> i64 {\n\
                 v.remove(0)\n\
             }\n\
             fn main() {\n\
                 let mut xs: Vec[i64] = Vec.new();\n\
                 xs.push(10);\n\
                 xs.push(20);\n\
                 xs.push(30);\n\
                 let a = drain_first(mut xs);\n\
                 println(a);\n\
                 println(xs.len());\n\
                 println(xs[0]);\n\
             }"),
        "10\n2\n20\n"
    );
}

#[test]
fn test_scalar_mut_ref_writeback_through_forwarded_call() {
    // A `mut ref i64` scalar accumulator FORWARDED into a nested call must
    // still propagate the callee's mutation back to the caller. The CICO
    // write-back keys on the callee's `mut ref` param mode, not the call-site
    // `mut` marker — a forwarded in-scope borrow carries no marker (design.md
    // § Call-site mutation markers), so a marker-only gate would drop the
    // chain and the accumulator would read 0. Regression for B-2026-07-03-13
    // (LeetCode #52 N-Queens II marker-array counter, all-zeros under `run`).
    assert_eq!(
        run("fn inc(x: mut ref i64) { x = x + 1i64; }\n\
             fn wrap(x: mut ref i64) { inc(x); }\n\
             fn main() {\n\
                 let mut t: i64 = 0;\n\
                 wrap(mut t);\n\
                 println(t);\n\
             }"),
        "1\n"
    );
}

#[test]
fn test_scalar_mut_ref_accumulator_through_recursion() {
    // The N-Queens-II shape: a `mut ref i64` total threaded down a recursion,
    // bumped only at the leaves. Each recursive call forwards the borrow
    // unmarked; every level must chain the write-back. bump(3) visits 2^3 = 8
    // leaves, so `total` must read 8.
    assert_eq!(
        run("fn bump(d: i64, t: mut ref i64) {\n\
                 if d == 0i64 { t = t + 1i64; return; }\n\
                 bump(d - 1i64, t);\n\
                 bump(d - 1i64, t);\n\
             }\n\
             fn main() {\n\
                 let mut t: i64 = 0;\n\
                 bump(3i64, mut t);\n\
                 println(t);\n\
             }"),
        "8\n"
    );
}

#[test]
fn test_vec_remove_out_of_bounds_is_runtime_error() {
    // design.md pins OOB as UB, but the tree-walk interpreter surfaces a
    // clean runtime error at the call site rather than panicking deep in
    // `Vec::remove` — matching the `index out of bounds` shape.
    let errs = runtime_errors(
        "fn main() {\n\
             let mut v: Vec[i64] = Vec.new();\n\
             v.push(1);\n\
             v.push(2);\n\
             let _ = v.remove(5);\n\
         }",
    );
    assert!(
        errs.iter()
            .any(|e| e.message.contains("Vec.remove: index 5 out of bounds")),
        "expected OOB runtime error, got: {:?}",
        errs
    );
}

