#[test]
fn test_e2e_enum_state_machine() {
    assert_eq!(
        run("enum State { Idle, Running(i64), Done }\n\
             fn step(s: State) -> State {\n\
                 match s {\n\
                     Idle => Running(0),\n\
                     Running(n) => {\n\
                         if n >= 3 { Done } else { Running(n + 1) }\n\
                     },\n\
                     Done => Done,\n\
                 }\n\
             }\n\
             fn is_done(s: State) -> bool {\n\
                 match s {\n\
                     Done => true,\n\
                     _ => false,\n\
                 }\n\
             }\n\
             fn main() {\n\
                 let s1 = step(Idle);\n\
                 println(is_done(s1));\n\
                 let s2 = step(s1);\n\
                 let s3 = step(s2);\n\
                 let s4 = step(s3);\n\
                 let s5 = step(s4);\n\
                 println(is_done(s5));\n\
             }"),
        "false\ntrue\n"
    );
}

