#[test]
fn test_labeled_break_exits_outer_loop() {
    // `break label expr` syntax is required; `break label;` alone parses as break-with-value
    assert_eq!(
        run("fn main() {\n\
                 let mut count = 0;\n\
                 outer: for x in [1, 2, 3] {\n\
                     for y in [10, 20, 30] {\n\
                         count = count + 1;\n\
                         break outer ();\n\
                     }\n\
                 }\n\
                 println(count);\n\
             }"),
        "1\n"
    );
}

#[test]
fn test_labeled_continue_skips_outer_iteration() {
    assert_eq!(
        run("fn main() {\n\
                 let mut count = 0;\n\
                 outer: for x in [1, 2, 3] {\n\
                     for y in [10, 20] {\n\
                         count = count + 1;\n\
                         continue outer;\n\
                     }\n\
                 }\n\
                 println(count);\n\
             }"),
        "3\n"
    );
}

#[test]
fn test_labeled_break_with_value() {
    assert_eq!(
        run("fn main() {\n\
                 let result = outer: loop {\n\
                     loop {\n\
                         break outer 42;\n\
                     }\n\
                 };\n\
                 println(result);\n\
             }"),
        "42\n"
    );
}

#[test]
fn test_labeled_break_while_loop() {
    assert_eq!(
        run("fn main() {\n\
                 let mut i = 0;\n\
                 outer: while i < 5 {\n\
                     let mut j = 0;\n\
                     while j < 5 {\n\
                         if j == 2 {\n\
                             break outer ();\n\
                         }\n\
                         j = j + 1;\n\
                     }\n\
                     i = i + 1;\n\
                 }\n\
                 println(i);\n\
             }"),
        "0\n"
    );
}

#[test]
fn test_unlabeled_break_still_works() {
    assert_eq!(
        run("fn main() {\n\
                 let mut count = 0;\n\
                 outer: for x in [1, 2, 3] {\n\
                     for y in [10, 20, 30] {\n\
                         count = count + 1;\n\
                         break;\n\
                     }\n\
                 }\n\
                 println(count);\n\
             }"),
        "3\n"
    );
}

// ── Labeled blocks runtime ───────────────────────────────────
//
// Sibling slice to `tests/codegen.rs` "Labeled blocks runtime" — the
// interpreter side of the LBC4 design choice. The labeled-block expr
// arm in `eval_expr_inner` matches `ControlFlow::Break { label, value
// }` against its own label; non-matching labels propagate. See
// `docs/implementation_checklist/phase-5-diagnostics.md` § 5.2.

#[test]
fn test_interpreter_labeled_block_break_with_value() {
    // Mirror of codegen test 1: `lbl: { break lbl 42; -1 }` evaluates
    // to 42 through the tree-walk path.
    assert_eq!(
        run("fn main() {\n\
             let x: i64 = lbl: { break lbl 42; -1 };\n\
             println(x);\n\
         }"),
        "42\n"
    );
}

#[test]
fn test_interpreter_labeled_block_bare_break_unit() {
    // Bare `break label` exits with `Value::Unit`. Observable check:
    // post-block println runs.
    assert_eq!(
        run("fn main() {\n\
             lbl: { break lbl; };\n\
             println(7);\n\
         }"),
        "7\n"
    );
}

#[test]
fn test_interpreter_labeled_block_tail_expression() {
    // No break: the block falls through normally and the tail value
    // becomes the labeled block's value.
    assert_eq!(
        run("fn main() {\n\
             let x: i64 = lbl: { 99 };\n\
             println(x);\n\
         }"),
        "99\n"
    );
}

#[test]
fn test_interpreter_lock_break_releases_then_reacquire() {
    // Parity with codegen `test_e2e_lock_break_releases_then_reacquire`:
    // a `break` out of a lock body persists the mutations made before it
    // and releases the lock (the interpreter drops the guard before
    // propagating the control flow), so the post-loop re-acquire succeeds.
    // 3 pre-break increments, then the re-read prints 3.
    assert_eq!(
        run("fn main() {\n\
             let m = Mutex.new(0);\n\
             let mut i = 0;\n\
             loop {\n\
                 lock m x {\n\
                     if i >= 3 { break; }\n\
                     x = x + 1;\n\
                 }\n\
                 i = i + 1;\n\
             }\n\
             lock m v { println(v); }\n\
         }"),
        "3\n"
    );
}

#[test]
fn test_interpreter_lock_return_releases_then_reacquire() {
    // Parity with codegen `test_e2e_lock_return_releases_then_reacquire`:
    // an early `return` out of a lock body releases the lock, so the
    // caller can re-acquire the same mutex. 7 (returned) + 7 (re-read).
    assert_eq!(
        run("fn take(m: mut ref Mutex[i64]) -> i64 {\n\
             lock m x { return x; }\n\
             0\n\
         }\n\
         fn main() {\n\
             let mut m = Mutex.new(7);\n\
             let a = take(mut m);\n\
             lock m v { println(a + v); }\n\
         }"),
        "14\n"
    );
}

#[test]
fn test_interpreter_nested_labeled_break_outer() {
    // Mirror of codegen latent-bug regression gate: `outer: while {
    // inner: while { break outer; } }` exits the outer loop. Pre-slice
    // interpreter already routed through `ControlFlow::Break.label`
    // correctly, but the test pins the contract to prevent a future
    // regression that flattens the label match.
    assert_eq!(
        run("fn main() {\n\
             let mut count = 0;\n\
             outer: while true {\n\
                 inner: while true {\n\
                     count = count + 1;\n\
                     break outer ();\n\
                 }\n\
                 count = count + 100;\n\
             }\n\
             println(count);\n\
         }"),
        "1\n"
    );
}

// ── Error Return Trace Tests ──────────────────────────────────

#[test]
fn test_error_trace_single_question_mark() {
    let (_output, trace, truncated) = run_program_with_trace(
        "fn might_fail() {\n\
             let r = Err(42);\n\
             r?\n\
         }\n\
         fn main() {\n\
             let result = might_fail();\n\
             match result {\n\
                 Ok(v) => println(v),\n\
                 Err(e) => println(e),\n\
             }\n\
         }",
    );
    assert!(
        !trace.is_empty(),
        "Error trace should have at least one frame"
    );
    assert!(!truncated);
    assert_eq!(trace.len(), 1);
    // The ? is on line 3
    assert_eq!(trace[0].line, 3);
}

#[test]
fn test_error_trace_multi_level_propagation() {
    let (_output, trace, truncated) = run_program_with_trace(
        "fn inner() {\n\
             let r = Err(99);\n\
             r?\n\
         }\n\
         fn middle() {\n\
             let v = inner()?;\n\
             v\n\
         }\n\
         fn outer() {\n\
             let v = middle()?;\n\
             v\n\
         }\n\
         fn main() {\n\
             let result = outer();\n\
             match result {\n\
                 Ok(v) => println(v),\n\
                 Err(e) => println(e),\n\
             }\n\
         }",
    );
    assert!(!truncated);
    // inner's ?, middle's ?, outer's ? = 3 frames
    assert_eq!(trace.len(), 3, "Expected 3 trace frames, got {:?}", trace);
}

#[test]
fn test_error_trace_cleared_on_ok() {
    let (_output, trace, _truncated) = run_program_with_trace(
        "fn try_thing() {\n\
             let r = Ok(10);\n\
             r?\n\
         }\n\
         fn main() {\n\
             let v = try_thing();\n\
             println(v);\n\
         }",
    );
    assert!(
        trace.is_empty(),
        "Trace should be empty after Ok(?), got {:?}",
        trace
    );
}

#[test]
fn test_error_trace_none_propagation() {
    let (_output, trace, truncated) = run_program_with_trace(
        "fn find() {\n\
             let r = None;\n\
             r?\n\
         }\n\
         fn search() {\n\
             let v = find()?;\n\
             v\n\
         }\n\
         fn main() {\n\
             let result = search();\n\
             match result {\n\
                 Some(v) => println(v),\n\
                 None => println(\"not found\"),\n\
             }\n\
         }",
    );
    assert!(!truncated);
    assert_eq!(
        trace.len(),
        2,
        "Expected 2 trace frames for None propagation, got {:?}",
        trace
    );
}

#[test]
fn test_error_trace_truncation_at_64() {
    // Build a deeply nested chain of ? propagation (65 levels).
    // Needs a larger stack for deep recursion in debug builds.
    let result = std::thread::Builder::new()
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let mut source = String::new();
            source.push_str("fn func0() {\n    let r = Err(1);\n    r?\n}\n");
            for i in 1..=64 {
                source.push_str(&format!(
                    "fn func{i}() {{\n    let v = func{}()?;\n    v\n}}\n",
                    i - 1
                ));
            }
            source.push_str(
                "fn main() {\n\
                     let result = func64();\n\
                     match result {\n\
                         Ok(v) => println(v),\n\
                         Err(e) => println(e),\n\
                     }\n\
                 }",
            );
            let (_output, trace, truncated) = run_program_with_trace(&source);
            // 65 frames total, but max is 64, so oldest is dropped
            assert!(truncated, "Trace should be truncated at 64 frames");
            assert_eq!(trace.len(), 64, "Trace should have exactly 64 frames");
        })
        .expect("failed to spawn thread")
        .join();
    result.expect("test thread panicked");
}

// ── Par Block Tests ────────────────────────────────────────────

#[test]
fn test_par_block_basic() {
    let output = run("fn a() -> i32 { println(\"A\"); 1 }
         fn b() -> i32 { println(\"B\"); 2 }
         fn main() {
             par {
                 let x = a();
                 let y = b();
             };
             println(\"done\");
         }");
    // Both tasks run, output is merged in source order
    assert!(output.contains("A"));
    assert!(output.contains("B"));
    assert!(output.contains("done"));
}

#[test]
fn test_par_block_single_statement() {
    // Single statement in par — runs without threading
    let output = run("fn main() {
             par {
                 println(\"solo\");
             };
         }");
    assert!(output.contains("solo"));
}

#[test]
fn test_par_block_empty() {
    // Empty par block is valid
    let output = run("fn main() { par { }; println(\"ok\"); }");
    assert!(output.contains("ok"));
}

#[test]
fn test_par_block_join_does_not_shadow_enclosing_bindings() {
    // B-2026-08-07-22 — the SILENT half, and the one worth guarding hardest.
    //
    // The join merges each branch's bindings into the enclosing scope. It used
    // to merge the whole seeded environment snapshot, so every enclosing
    // variable was re-`define`d into the parent's CURRENT scope. At function
    // top level that rewrites bindings in their own scope and nothing is
    // observable — which is exactly why every par test above passed. One block
    // deeper the current scope is the block's, so `n` gained a shadow there and
    // `n = n + 5` updated the shadow, which died with the block: this printed
    // `0` under `--interp` while the AOT twin printed `5`.
    //
    // Two statements in the par block is load-bearing: at one or fewer,
    // `eval_par_block` returns early and never reaches the join.
    let output = run("fn main() {
             let mut n: i64 = 0;
             if 1 < 2 {
                 par { let a = 1; let b = 2; }
                 n = n + 5;
             }
             println(n);
         }");
    assert_eq!(
        output.trim(),
        "5",
        "an assignment after a par join must reach the ENCLOSING binding, not a \
         shadow created in the current block scope"
    );
}

#[test]
fn test_par_block_inside_while_loop_terminates() {
    // B-2026-08-07-22 — the loud half of the same defect. When the shadowed
    // binding is a loop counter, `i = i + 1` never reaches the real `i`, the
    // condition stays true forever, and `karac run --interp` hangs on a program
    // whose AOT twin prints instantly.
    //
    // Run on a worker with a deadline: a regression here does not fail, it
    // spins, and an un-timed assertion would hang the whole suite rather than
    // report.
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::Builder::new()
        .stack_size(32 * 1024 * 1024)
        .spawn(move || {
            let out = run("fn main() {
                     let mut total: i64 = 0;
                     let mut i: i64 = 0;
                     while i < 2 {
                         let (a, b) = par {
                             let a = i + 1;
                             let b = i + 2;
                             (a, b)
                         };
                         total = total + a + b;
                         i = i + 1;
                     }
                     println(total);
                 }");
            let _ = tx.send(out);
        })
        .expect("failed to spawn worker");

    match rx.recv_timeout(std::time::Duration::from_secs(60)) {
        Ok(out) => assert_eq!(
            out.trim(),
            "8",
            "par inside a while loop must produce the same value as the AOT build"
        ),
        Err(_) => panic!(
            "`par {{}}` inside a `while` loop did not terminate within 60s — the loop \
             counter's update is being lost to a shadow created by the par join"
        ),
    }
}

// ── IEEE 754 Float Semantics ──────────────────────────────────

#[test]
fn test_float_nan_not_equal() {
    // IEEE 754: NaN != NaN
    let output = run("fn main() { let nan = 0.0 / 0.0; println(nan == nan); }");
    assert_eq!(output, "false\n");
}

#[test]
fn test_sort_by_key_float_nan_sorts_largest_interp_parity() {
    // B-2026-08-11-17 — the INTERPRETER twin of
    // `test_e2e_vec_sort_by_key_float_nan_sorts_largest` (tests/codegen.rs),
    // same input and same expected order. Only the compiled side was ever
    // asserted, which is why this survived: `value_compare` ordered floats
    // with `partial_cmp(…).unwrap_or(Equal)`, so EVERY comparison involving a
    // NaN answered "equal". That is not merely a misplaced NaN — it makes the
    // order intransitive and the whole sort incoherent. This exact input came
    // back `3.5 NaN -2 1.2 2.7`, not sorted in any order, while both compiled
    // backends gave `-2 1.2 2.7 3.5 NaN`.
    //
    // The typechecker deliberately ALLOWS a float sort KEY (the concession is
    // documented at `check_sort_key_closure`) on the grounds that the backends
    // implement bit-level total order — true of codegen via `karac_float_cmp`,
    // and now true of the interpreter. It is also the last remaining way to
    // get an incoherent float ordering without a diagnostic, since
    // B-2026-08-11-7 gated `sort`/`sorted`/`binary_search` and -15 gated
    // `max`/`min` on `Vec[f64]`.
    let out = run("fn main() {\n\
             let mut v: Vec[f64] = Vec.new();\n\
             let nan: f64 = 0.0 / 0.0;\n\
             v.push(3.5); v.push(nan); v.push(1.2); v.push(0.0 - 2.0); v.push(2.7);\n\
             v.sort_by_key(|x| x);\n\
             for x in v.iter() { println(x); }\n\
         }");
    assert_eq!(out, "-2\n1.2\n2.7\n3.5\nNaN\n", "got {out:?}");
}

#[test]
fn test_sort_by_key_float_nan_order_is_provenance_independent() {
    // B-2026-08-11-17, second half. `total_cmp` alone fixes the incoherence
    // but NOT the run-vs-build split, because it is sign-sensitive: a NEGATIVE
    // NaN sorts before `-Infinity` while a POSITIVE one sorts after
    // `+Infinity`, and nothing in the source chooses which you get — an x86
    // runtime `z / z` yields a negative NaN, LLVM's constant folder a positive
    // one. Mid-fix this was measured NaN-first under interp and JIT but
    // NaN-LAST under AOT, which inlined `zero()` and folded the division.
    //
    // Both NaNs must therefore sort identically. `zero()` defeats constant
    // folding so the two provenances appear in one program.
    let out = run("fn zero() -> f64 { return 0.0; }\n\
         fn main() {\n\
             let z = zero();\n\
             let rt = z / z;\n\
             let ct = 0.0 / 0.0;\n\
             let mut a: Vec[f64] = Vec.new();\n\
             a.push(1.0); a.push(rt); a.push(0.0 - 1.0);\n\
             a.sort_by_key(|x| x);\n\
             let mut b: Vec[f64] = Vec.new();\n\
             b.push(1.0); b.push(ct); b.push(0.0 - 1.0);\n\
             b.sort_by_key(|x| x);\n\
             for x in a.iter() { println(x); }\n\
             for x in b.iter() { println(x); }\n\
         }");
    assert_eq!(out, "-1\n1\nNaN\n-1\n1\nNaN\n", "got {out:?}");
}

// ── F64/F32 Total-Order Types ─────────────────────────────────

// B-2026-08-11-8: these two asserted `F64(3.14)` / `F32(2.5…)`, a rendering
// that no CHECKED program could ever observe — both `println(x)` and `f"{x}"`
// rejected `F64` at typecheck ("does not implement Display"), and this
// harness's `run()` bypasses that gate. Giving the wrapper Display meant
// choosing a rendering, and it renders as the inner float so that wrapping a
// value for its `Ord` contract does not change how it prints. Codegen's
// `synth_display.rs` arm reuses the same shortest-round-trip float formatter,
// so the two backends cannot drift.
#[test]
fn test_f64_from_constructor() {
    let output = run("fn main() { let x = F64.from(3.14); println(x); }");
    assert_eq!(output, "3.14\n");
}

#[test]
fn test_f32_from_constructor() {
    let output = run("fn main() { let x = F32.from(2.5); println(x); }");
    assert!(output.starts_with("2.5"), "got {output:?}");
}

#[test]
fn test_total_order_wrapper_compare_map_sort_interp_parity() {
    // B-2026-07-22-11 — the interpreter must match codegen's TOTAL order for
    // the `F32`/`F64` wrappers. Before the fix, `F32 { value: x }` built a
    // plain `Value::Struct` compared with the IEEE partial order (diverging
    // from codegen on -0/NaN), F32 ordering ops were missing from `eval_ops`,
    // and `value_compare`/the lowered `F32.gt` dispatch had no wrapper arm.
    // Now the struct literal builds a `TotalFloat32/64` (like `F32.from`), so
    // comparison, sort, and Map keys all use `total_cmp`. Same program +
    // expected output as the codegen E2E test
    // (`test_e2e_total_order_float_wrappers`).
    let output = run("fn main() {\n\
             let a: F32 = F32 { value: 2.5 };\n\
             let b: F32 = F32 { value: 1.5 };\n\
             println(a > b);\n\
             println(a < b);\n\
             println(a == a);\n\
             println(a == b);\n\
             println(a.value + b.value);\n\
             let mut m: Map[F32, i64] = Map.new();\n\
             let _ = m.insert(F32 { value: 2.0 }, 20);\n\
             let _ = m.insert(F32 { value: 3.0 }, 30);\n\
             match m.get(F32 { value: 2.0 }) { Some(v) => println(v), None => println(0 - 1) }\n\
             let mut v: Vec[F32] = Vec.new();\n\
             v.push(F32 { value: 3.0 });\n\
             v.push(F32 { value: 1.0 });\n\
             v.push(F32 { value: 2.0 });\n\
             v.sort();\n\
             println(v[0].value);\n\
             println(v[2].value);\n\
             let neg0: F64 = F64 { value: 0.0 * (0.0 - 1.0) };\n\
             let pos0: F64 = F64 { value: 0.0 };\n\
             println(neg0 < pos0);\n\
             println(neg0 == pos0);\n\
         }");
    assert_eq!(
        output,
        "true\nfalse\ntrue\nfalse\n4\n20\n1\n3\ntrue\nfalse\n"
    );
}

#[test]
fn test_total_order_wrapper_nan_canonicalized_interp_parity() {
    // B-2026-08-11-13 — the wrapper orders and compares by BIT pattern, so
    // before the fix the sign of a NaN decided the answer, and nothing in the
    // source chooses that sign: x86 runtime division yields a NEGATIVE NaN
    // while LLVM's constant folder yields a POSITIVE one, and totalOrder puts
    // the first before `-Infinity` and the second after `+Infinity`. One
    // program therefore gave four different results — interp, JIT, AOT at -O2,
    // and AOT at -O0 — including a `Vec[F64].sort()` that put NaN at BOTH ends
    // (correctly sorted under raw totalOrder; nonsense to a reader, since both
    // print `NaN`) and a two-NaN `Map` whose LEN differed by backend.
    //
    // Every NaN is now canonicalized to one quiet NaN at construction, so all
    // of it collapses to a single answer. Same program + expected output as
    // the codegen E2E twin (`test_e2e_total_order_wrapper_nan_canonicalized`);
    // that pairing is the actual contract — run == build.
    //
    // B-2026-08-14-12: the `F32.from` line carries an explicit `as f32`, in
    // both twins. `z` is `f64`, so `z / z` is a runtime f64 NaN and putting it
    // in an f32 slot is a genuine narrowing — the only real one the float gate
    // found in the suite. The cast preserves the behaviour (NaN narrows to
    // NaN) and states it.
    let output = run("fn main() {\n\
            let n = env.args().len();\n\
            let z = (n as f64) - (n as f64);\n\
            let c: F64 = F64 { value: 0.0 / 0.0 };\n\
            let r: F64 = F64.from(z / z);\n\
            let one: F64 = F64 { value: 1.0 };\n\
            let inf: F64 = F64 { value: 1.0 / 0.0 };\n\
            println(c == r);\n\
            println(c < one);\n\
            println(r < one);\n\
            println(r > inf);\n\
            let mut v: Vec[F64] = Vec.new();\n\
            v.push(r);\n\
            v.push(one);\n\
            v.push(c);\n\
            v.push(F64 { value: 0.0 - 1.0 });\n\
            v.sort();\n\
            println(v[0].value);\n\
            println(v[1].value);\n\
            println(v[3].value);\n\
            let mut m: Map[F64, i64] = Map.new();\n\
            let _ = m.insert(c, 1);\n\
            let _ = m.insert(r, 2);\n\
            println(m.len());\n\
            match m.get(r) { Some(x) => println(x), None => println(0 - 1) }\n\
            let n0: F64 = F64 { value: 0.0 * (0.0 - 1.0) };\n\
            let p0: F64 = F64 { value: 0.0 };\n\
            println(n0 < p0);\n\
            println(n0 == p0);\n\
            let c32: F32 = F32 { value: 0.0 / 0.0 };\n\
            let r32: F32 = F32.from((z / z) as f32);\n\
            println(c32 == r32);\n\
        }");
    // The two `< one` lines are the crux: pre-fix they DISAGREED with each
    // other (the const NaN sorted last, the runtime NaN first) even though
    // both print `NaN`. Then: c==r across provenance, r>inf, sort[0]/[1]/[3],
    // map len (1, not 2), map get, -0<+0 and -0==+0 (B-2026-08-11-14: still
    // DISTINCT — only NaN is normalized), and the F32 twin.
    assert_eq!(
        output,
        "true\nfalse\nfalse\ntrue\n-1\n1\nNaN\n1\n2\ntrue\nfalse\ntrue\n"
    );
}

#[test]
fn test_float_wrapper_value_from_enum_payload_interp_parity() {
    // B-2026-07-23-2 — `.value` on a float-wrapper bound out of a user-enum
    // payload, in a match arm beside an `f64` arm. The interpreter was already
    // correct here (the bug was codegen's phi-type mismatch bailing to `ret i64
    // 0`); this pins the run==build contract for the codegen E2E fix. Same
    // program + output as `test_e2e_float_wrapper_value_field_from_enum_payload`.
    let output = run("enum Num { I(i64), F(F32) }\n\
             enum Dbl { I(i64), D(F64) }\n\
             fn show(n: Num) -> f64 { match n { I(x) => x as f64, F(f) => f.value } }\n\
             fn show_ref(n: ref Num) -> f64 { match n { I(x) => x as f64, F(f) => f.value } }\n\
             fn show_first(n: Num) -> f64 { match n { F(f) => f.value, I(x) => x as f64 } }\n\
             fn show_arith(n: Num) -> f64 { match n { I(x) => x as f64, F(f) => f.value + 1.0 } }\n\
             fn show_d(n: Dbl) -> f64 { match n { I(x) => x as f64, D(d) => d.value } }\n\
             fn main() {\n\
                 let a = Num.F(F32 { value: 2.5 });\n\
                 println(show(a));\n\
                 println(show(Num.I(7)));\n\
                 let b = Num.F(F32 { value: 4.0 });\n\
                 println(show_ref(b));\n\
                 println(show_first(Num.F(F32 { value: 1.5 })));\n\
                 println(show_arith(Num.F(F32 { value: 2.5 })));\n\
                 println(show_d(Dbl.D(F64 { value: 3.25 })));\n\
                 println(show_d(Dbl.I(9)));\n\
             }");
    assert_eq!(output, "2.5\n7\n4\n1.5\n3.5\n3.25\n9\n");
}

#[test]
fn test_map_set_from_enum_payload_interp_parity() {
    // B-2026-07-23-3 — a `Map`/`Set`-family collection bound out of a user-enum
    // payload, method-dispatched (`m.len()` / `s.contains(x)`). The interpreter
    // already handled this; pins run==build for the codegen dispatch fix. Same
    // program + output as `test_e2e_map_set_method_dispatch_from_enum_payload`.
    let output = run("enum MapBox { Table(Map[String, i64]) }\n\
             enum SetBox { Items(Set[i64]) }\n\
             enum SmapBox { T(SortedMap[i64, i64]) }\n\
             enum SsetBox { S(SortedSet[i64]) }\n\
             fn map_len_ref(v: ref MapBox) -> i64 { match v { Table(m) => m.len() as i64 } }\n\
             fn map_len_val(v: MapBox) -> i64 { match v { Table(m) => m.len() as i64 } }\n\
             fn set_len_ref(v: ref SetBox) -> i64 { match v { Items(s) => s.len() as i64 } }\n\
             fn set_has_ref(v: ref SetBox, x: i64) -> bool { match v { Items(s) => s.contains(x) } }\n\
             fn smap_len_ref(v: ref SmapBox) -> i64 { match v { T(m) => m.len() as i64 } }\n\
             fn sset_len_ref(v: ref SsetBox) -> i64 { match v { S(s) => s.len() as i64 } }\n\
             fn main() {\n\
                 let mut mp: Map[String, i64] = Map.new();\n\
                 let _ = mp.insert(\"a\", 1);\n\
                 let _ = mp.insert(\"b\", 2);\n\
                 let t = MapBox.Table(mp);\n\
                 println(map_len_ref(t));\n\
                 let mut mp2: Map[String, i64] = Map.new();\n\
                 let _ = mp2.insert(\"x\", 9);\n\
                 println(map_len_val(MapBox.Table(mp2)));\n\
                 let mut st: Set[i64] = Set.new();\n\
                 st.insert(1); st.insert(2); st.insert(2);\n\
                 let sv = SetBox.Items(st);\n\
                 println(set_len_ref(sv));\n\
                 println(set_has_ref(sv, 2));\n\
                 println(set_has_ref(sv, 5));\n\
                 let mut sm: SortedMap[i64, i64] = SortedMap.new();\n\
                 let _ = sm.insert(3, 1);\n\
                 let _ = sm.insert(1, 2);\n\
                 println(smap_len_ref(SmapBox.T(sm)));\n\
                 let mut ss: SortedSet[i64] = SortedSet.new();\n\
                 ss.insert(7); ss.insert(4); ss.insert(7);\n\
                 println(sset_len_ref(SsetBox.S(ss)));\n\
             }");
    assert_eq!(output, "2\n1\n2\ntrue\nfalse\n2\n2\n");
}

#[test]
