fn test_channel_try_recv_non_empty() {
    let output = run("fn main() {\n\
             let (sender, receiver) = Channel.new();\n\
             sender.send(7_i64);\n\
             match receiver.try_recv() {\n\
                 Some(v) => println(f\"{v}\"),\n\
                 None    => println(\"empty\"),\n\
             }\n\
         }");
    assert_eq!(output, "7\n");
}

