// ── Distinct types — constructor + .raw() (zero-cost) ──────────────

#[test]
fn test_distinct_constructor_and_raw_roundtrip() {
    // `UserId(42)` wraps a base value (zero-cost) and `.raw()` unwraps it.
    let output = run_no_errors(
        "distinct type UserId = i64;\n\
         fn main() {\n\
             let u = UserId(42);\n\
             let raw: i64 = u.raw();\n\
             println(raw);\n\
         }",
    );
    assert_eq!(output, "42\n");
}

#[test]
fn test_distinct_constructor_float_base() {
    // The wrap is value-preserving for non-integer bases too.
    let output = run_no_errors(
        "distinct type Meters = f64;\n\
         fn main() {\n\
             let m = Meters(3.5);\n\
             println(m.raw());\n\
         }",
    );
    assert_eq!(output, "3.5\n");
}

#[test]
fn test_distinct_constructor_passed_through_function() {
    // A distinct value round-trips through a function call and back out
    // via `.raw()` — the wrapper is purely a type-level distinction.
    let output = run_no_errors(
        "distinct type UserId = i64;\n\
         fn identity(id: UserId) -> UserId { id }\n\
         fn main() {\n\
             let u = identity(UserId(7));\n\
             println(u.raw());\n\
         }",
    );
    assert_eq!(output, "7\n");
}

#[test]
fn test_distinct_where_constructor_runtime_holds() {
    // Combined `distinct type Even = i64 where self % 2 == 0`: a runtime
    // argument that satisfies the predicate constructs successfully.
    let output = run_no_errors(
        "distinct type Even = i64 where self % 2 == 0;\n\
         fn mk(n: i64) -> Even { Even(n) }\n\
         fn main() { println(mk(8).raw()); }",
    );
    assert_eq!(output, "8\n");
}

#[test]
fn test_distinct_where_constructor_runtime_fails() {
    // A runtime argument that violates the predicate faults with a
    // `contract violated` runtime error.
    let errors = runtime_errors(
        "distinct type Even = i64 where self % 2 == 0;\n\
         fn mk(n: i64) -> Even { Even(n) }\n\
         fn main() { println(mk(7).raw()); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a `contract violated` fault, got: {errors:?}"
    );
}

// ── ExitCode (Phase-8 entry-point contract Slice B) ────────────

#[test]
fn test_exitcode_success_failure_values() {
    // `ExitCode.SUCCESS` / `ExitCode.FAILURE` evaluate to 0 / 1. The
    // interpreter can't observe the process exit (that happens in
    // `cmd_run`), so the value is checked through `.raw()`.
    let output = run_no_errors(
        "fn main() {\n\
             let ok = ExitCode.SUCCESS;\n\
             let bad = ExitCode.FAILURE;\n\
             println(ok.raw());\n\
             println(bad.raw());\n\
         }",
    );
    assert_eq!(output, "0\n1\n");
}

#[test]
fn test_exitcode_from_arbitrary_code() {
    // `ExitCode.from(code)` wraps an arbitrary code (the stdlib
    // identity-wrap body `{ ExitCode(code) }`).
    let output = run_no_errors("fn main() { println(ExitCode.from(42).raw()); }");
    assert_eq!(output, "42\n");
}

#[test]
fn test_match_ok_unit_payload_selects_correct_arm() {
    // `match Result[(), E] { Ok(()) => .., Err(_) => .. }` — the `Ok(())`
    // unit-payload pattern matches `Ok` and the `Err` value routes to the
    // Err arm. Parity peer to the codegen E2E regression for the
    // exhaustiveness / unit-tuple-pattern fix.
    let output = run_no_errors(
        "fn classify(r: Result[(), String]) -> i64 {\n\
             match r { Ok(()) => 10, Err(e) => 20 }\n\
         }\n\
         fn main() {\n\
             println(classify(Err(\"x\")));\n\
             println(classify(Ok(())));\n\
         }",
    );
    assert_eq!(output, "20\n10\n");
}

#[test]
fn test_match_freshtemp_result_struct_field_moved_to_free_fn() {
    // B-2026-07-23-4 interpreter parity: matching a fresh-temp `Result[W, _]`
    // whose `Ok(w)` struct payload has a heap `String` field and passing that
    // field by value to a free fn (`println(w.s)` / `use_s(w.s)`) is clean in
    // the tree-walk interpreter (the bug was codegen-only — a double-free under
    // `karac build`). This pins the reference behavior the codegen fix matches.
    let output = run_no_errors(
        "struct W { s: String }\n\
         fn use_s(x: String) -> i64 { x.len() }\n\
         fn f() -> Result[W, i64] { Ok(W { s: \"boom\".to_string() }) }\n\
         fn main() {\n\
             match f() { Ok(w) => println(w.s), Err(e) => println(e.to_string()) }\n\
             match f() { Ok(w) => println(use_s(w.s).to_string()), Err(e) => println(e.to_string()) }\n\
         }",
    );
    assert_eq!(output, "boom\n4\n");
}

#[test]
fn test_distinct_derived_comparison_runs() {
    // With `#[derive(Eq, Ord)]` the comparison operators are admitted and
    // run on the base layout — `UserId(3) < UserId(5)` is `true`,
    // `UserId(5) == UserId(5)` is `true`.
    let output = run_no_errors(
        "#[derive(Eq, Ord)]\n\
         distinct type UserId = i64;\n\
         fn main() {\n\
             println(UserId(3) < UserId(5));\n\
             println(UserId(5) == UserId(5));\n\
         }",
    );
    assert_eq!(output, "true\ntrue\n");
}

#[test]
fn test_distinct_where_try_from_ok_and_err() {
    // `Even.try_from` returns `Ok` for an even value and `Err` for an odd.
    let ok = run_no_errors(
        "distinct type Even = i64 where self % 2 == 0;\n\
         fn main() {\n\
             match Even.try_from(8) { Ok(e) => println(e.raw()), Err(_) => println(-1) }\n\
         }",
    );
    assert_eq!(ok, "8\n");
    let err = run_no_errors(
        "distinct type Even = i64 where self % 2 == 0;\n\
         fn main() {\n\
             match Even.try_from(7) { Ok(e) => println(e.raw()), Err(_) => println(-1) }\n\
         }",
    );
    assert_eq!(err, "-1\n");
}

