// ── Implicit assign-through on a `mut ref` scalar (B-2026-06-30-9/10) ──
// design.md § "Compound assignment on `mut ref` lvalues" (:5306): `a = a + b`
// on a `mut ref T` lvalue desugars to `*a = *a + b` — no explicit deref
// needed. The interpreter already applied this; these lock in run/build parity
// (the codegen counterparts live in tests/codegen.rs).
#[test]
fn test_mut_ref_scalar_implicit_assign_through() {
    // `x = x + 1i64` (no `*`) reads through the borrow and writes back.
    let output = run("fn inc(x: mut ref i64) { x = x + 1i64; }\n\
         fn main() { let mut n: i64 = 10i64; inc(mut n); println(n); }");
    assert_eq!(output, "11\n");
}

#[test]
fn test_mut_ref_scalar_compound_assign_through() {
    // `x += 1i64` on a `mut ref i64` — the compound-assign sibling.
    let output = run("fn inc(x: mut ref i64) { x += 1i64; }\n\
         fn main() { let mut n: i64 = 10i64; inc(mut n); println(n); }");
    assert_eq!(output, "11\n");
}

#[test]
fn test_mut_ref_scalar_narrow_int_assign_through() {
    // `mut ref i32` with an unsuffixed literal — the pointee width is preserved.
    let output = run("fn inc(x: mut ref i32) { x = x + 1; }\n\
         fn main() { let mut n: i32 = 41; inc(mut n); println(n); }");
    assert_eq!(output, "42\n");
}

// ── Match write-through on a `mut ref` enum payload (B-2026-07-23-12) ──
// The interpreter binds a match payload BY VALUE, so mutating a bound payload
// (`match v { Table(m) => m.insert(..) }`) updated only the arm-local copy and
// the change was lost — codegen writes through correctly. `eval_match` now
// reconstructs the scrutinee from the (mutated) arm bindings and stores it back
// to a bare-identifier / `self` place, so the `mut ref` mutation propagates.
#[test]
fn test_mut_ref_enum_payload_map_write_through() {
    // The ledger repro: an insert into a `Map` enum payload through `mut ref V`.
    let output = run("enum V { Table(Map[String, i64]) }\n\
         fn add(v: mut ref V) { match v { Table(m) => { m.insert(\"z\", 99); } } }\n\
         fn size(v: ref V) -> i64 { match v { Table(m) => m.len() as i64 } }\n\
         fn main() {\n\
             let mut mp: Map[String, i64] = Map.new();\n\
             mp.insert(\"a\", 1);\n\
             let mut t = V.Table(mp);\n\
             add(mut t);\n\
             println(size(t));\n\
         }");
    assert_eq!(output, "2\n");
}

#[test]
fn test_mut_ref_enum_struct_variant_payload_map_write_through() {
    // Struct-variant payload form of the same write-through.
    let output = run("enum V { Table { m: Map[String, i64], tag: i64 } }\n\
         fn add(v: mut ref V) { match v { Table { m, tag } => { m.insert(\"z\", 99); } } }\n\
         fn size(v: ref V) -> i64 { match v { Table { m, tag } => m.len() as i64 } }\n\
         fn main() {\n\
             let mut mp: Map[String, i64] = Map.new();\n\
             mp.insert(\"a\", 1);\n\
             let mut t = V.Table { m: mp, tag: 7 };\n\
             add(mut t);\n\
             println(size(t));\n\
         }");
    assert_eq!(output, "2\n");
}

#[test]
fn test_mut_ref_enum_payload_vec_write_through() {
    // A `Vec` enum payload (also stored by value in the interpreter) writes
    // through the same reconstruction path.
    let output = run("enum V { List(Vec[i64]) }\n\
         fn add(v: mut ref V) { match v { List(xs) => { xs.push(99); } } }\n\
         fn size(v: ref V) -> i64 { match v { List(xs) => xs.len() as i64 } }\n\
         fn main() {\n\
             let mut xs: Vec[i64] = [1, 2];\n\
             let mut t = V.List(xs);\n\
             add(mut t);\n\
             println(size(t));\n\
         }");
    assert_eq!(output, "3\n");
}

#[test]
fn test_match_readonly_enum_payload_not_corrupted() {
    // Guard against over-firing: a read-only `ref V` match must leave the
    // scrutinee unchanged across repeated matches (both reads see size 1).
    let output = run("enum V { Table(Map[String, i64]) }\n\
         fn size(v: ref V) -> i64 { match v { Table(m) => m.len() as i64 } }\n\
         fn main() {\n\
             let mut mp: Map[String, i64] = Map.new();\n\
             mp.insert(\"a\", 1);\n\
             let t = V.Table(mp);\n\
             println(size(t));\n\
             println(size(t));\n\
         }");
    assert_eq!(output, "1\n1\n");
}

// ── Arrow IPC constructors verify the binding annotation (B-2026-07-28-10) ────
// `Column.from_arrow_ipc` / `Tensor.from_arrow_ipc` take an opaque byte stream,
// so nothing in the argument says what the result's element type or shape is.
// Codegen recovers both from the `let` annotation and has the runtime reject a
// stream that does not convert; the interpreter built straight from whatever the
// stream decoded, so an ill-typed program printed a plausible answer under
// `karac run` while `karac build` trapped. `pending_let_ty` threads the
// annotation into the RHS so both backends now reject the same programs.

#[test]
fn test_column_from_arrow_ipc_rejects_element_type_mismatch() {
    // A Utf8 stream bound at `Column[i64]`. Codegen traps; the interpreter used
    // to hand back a Column of Strings and print 2.
    let errors = runtime_errors(
        "fn main() {\n\
             let s: Column[String] = Column.from_vec([\"a\", \"b\"]);\n\
             let bad: Column[i64] = Column.from_arrow_ipc(s.to_arrow_ipc());\n\
             println(bad.len());\n\
         }",
    );
    assert!(
        errors.iter().any(|e| e
            .message
            .contains("do not convert to the declared element type")),
        "expected an element-type rejection, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_column_from_arrow_ipc_accepts_matching_element_types() {
    // The guard must not over-fire: a well-typed round-trip is unchanged on
    // every checkable element class (numeric, String, float).
    assert_eq!(
        run("fn main() {\n\
                 let a: Column[i64] = Column.from_vec([1, 2, 3]);\n\
                 let ra: Column[i64] = Column.from_arrow_ipc(a.to_arrow_ipc());\n\
                 println(ra.len());\n\
                 let b: Column[String] = Column.from_vec([\"a\", \"b\"]);\n\
                 let rb: Column[String] = Column.from_arrow_ipc(b.to_arrow_ipc());\n\
                 println(rb.len());\n\
                 let c: Column[f64] = Column.from_vec([1.5, 2.5]);\n\
                 let rc: Column[f64] = Column.from_arrow_ipc(c.to_arrow_ipc());\n\
                 println(rc.len());\n\
             }"),
        "3\n2\n2\n"
    );
}

#[test]
fn test_tensor_from_arrow_ipc_rejects_shape_mismatch() {
    // A [2,3] stream bound at `Tensor[i64, [3, 2]]`. Same channel, shape face.
    let errors = runtime_errors(
        "fn main() {\n\
             let a: Tensor[i64, [2, 3]] = Tensor.zeros([2, 3]);\n\
             let bad: Tensor[i64, [3, 2]] = Tensor.from_arrow_ipc(a.to_arrow_ipc());\n\
             println(bad.rank());\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("does not match the declared shape")),
        "expected a shape rejection, got: {:?}",
        errors.iter().map(|e| &e.message).collect::<Vec<_>>()
    );
}

#[test]
fn test_tensor_from_arrow_ipc_accepts_matching_shape() {
    assert_eq!(
        run("fn main() {\n\
                 let a: Tensor[i64, [2, 3]] = Tensor.zeros([2, 3]);\n\
                 let ok: Tensor[i64, [2, 3]] = Tensor.from_arrow_ipc(a.to_arrow_ipc());\n\
                 println(ok.rank());\n\
                 println(ok.shape());\n\
             }"),
        "2\n[2, 3]\n"
    );
}

// ── Match-arm assignment to the scrutinee (B-2026-07-28-7) ────────────────────
// The write-through above reconstructed the scrutinee from its arm bindings and
// stored it back UNCONDITIONALLY, which silently REVERTED an assignment the arm
// body made to the scrutinee place itself. `match cur { Some(n) => { cur = ..
// } }` is the shape of every linked-structure walk and most state machines, so
// the revert turned them into infinite loops. `eval_match` now watches the
// scrutinee's slot across the arm body and skips the write-through when the
// body replaced it.
#[test]
fn test_match_arm_assignment_to_scrutinee_survives() {
    // Minimal shape: the arm assigns `None` to the very variable being matched.
    // Before the fix the second match still saw `Some(1)`.
    let output = run("fn main() {\n\
             let mut cur = Some(1);\n\
             match cur { None => {} Some(n) => { println(n); cur = None; } }\n\
             match cur { None => { println(\"none\") } Some(m) => { println(m) } }\n\
         }");
    assert_eq!(output, "1\nnone\n");
}

#[test]
fn test_match_arm_scrutinee_countdown_terminates() {
    // Assigning a fresh `Some` (not just `None`) must stick too — otherwise the
    // loop never makes progress. Ran forever before the fix.
    let output = run("fn main() {\n\
             let mut cur = Some(3);\n\
             let mut guard = 0;\n\
             loop {\n\
                 if guard >= 9 { println(\"CYCLE\"); break; }\n\
                 match cur {\n\
                     None => { println(\"end\"); break; }\n\
                     Some(n) => { println(n); if n <= 1 { cur = None; } else { cur = Some(n - 1); } }\n\
                 }\n\
                 guard = guard + 1;\n\
             }\n\
         }");
    assert_eq!(output, "3\n2\n1\nend\n");
}

#[test]
fn test_match_arm_shared_struct_link_walk_terminates() {
    // The `examples/tangle/src/doubly_linked.kara` shape that surfaced this:
    // walking `Option[<shared struct>]` links by reassigning the cursor inside
    // the arm. Before the fix `cur` never advanced past the head, so the walk
    // re-read node 1 forever.
    let output = run(
        "shared struct Node { mut val: i64, mut next: Option[Node] }\n\
         fn main() {\n\
             let a = Node { val: 1, next: None };\n\
             let b = Node { val: 2, next: None };\n\
             a.next = Some(b);\n\
             let mut cur = Some(a);\n\
             let mut guard = 0;\n\
             loop {\n\
                 if guard >= 5 { println(\"CYCLE\"); break; }\n\
                 match cur {\n\
                     None => { println(\"end\"); break; }\n\
                     Some(n) => { println(n.val); cur = n.next; }\n\
                 }\n\
                 guard = guard + 1;\n\
             }\n\
         }",
    );
    assert_eq!(output, "1\n2\nend\n");
}

#[test]
fn test_match_arm_assignment_does_not_suppress_sibling_write_through() {
    // The skip must be scoped to the scrutinee's OWN slot: an arm that mutates
    // a bound payload while assigning some OTHER variable still writes through
    // (B-2026-07-23-12 must keep working alongside B-2026-07-28-7).
    let output = run("enum V { List(Vec[i64]) }\n\
         fn add(v: mut ref V) {\n\
             let mut touched = 0;\n\
             match v { List(xs) => { xs.push(99); touched = 1; } }\n\
             println(touched);\n\
         }\n\
         fn size(v: ref V) -> i64 { match v { List(xs) => xs.len() as i64 } }\n\
         fn main() {\n\
             let mut xs: Vec[i64] = [1, 2];\n\
             let mut t = V.List(xs);\n\
             add(mut t);\n\
             println(size(t));\n\
         }");
    assert_eq!(output, "1\n3\n");
}

#[test]
fn test_match_arm_assignment_in_nested_match_reaches_outer_scrutinee() {
    // An assignment made from inside a NESTED match must still be seen by the
    // OUTER match's watch — otherwise the inner match hides the write and the
    // outer write-through reverts it. This is why the watch is a stack that
    // marks every frame naming the slot, not just the innermost.
    let output = run("fn main() {\n\
             let mut cur = Some(1);\n\
             let flag = Some(7);\n\
             match cur {\n\
                 None => {}\n\
                 Some(n) => {\n\
                     println(n);\n\
                     match flag { None => {} Some(f) => { cur = Some(n + f); } }\n\
                 }\n\
             }\n\
             match cur { None => { println(\"none\") } Some(m) => { println(m) } }\n\
         }");
    assert_eq!(output, "1\n8\n");
}

