#[test]
fn test_iter_sum_terminal() {
    // B-2026-07-11-19 — the numeric `sum()` terminal. Covers a bare
    // `iter().sum`, a `map().sum`, a `filter().sum`, an f64 sum, an empty
    // source (0), and a range sum.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3, 4];
    println(v.iter().sum().to_string());
    println(v.iter().map(|x: i64| x * 2i64).sum().to_string());
    println(v.iter().filter(|x: i64| x > 2i64).sum().to_string());
    let f: Vec[f64] = [1.5, 2.5, 3.0];
    println(f.iter().sum().to_string());
    let e: Vec[i64] = [];
    println(e.iter().sum().to_string());
    println((1i64..5i64).sum().to_string());
}
"#,
    );
    // 10, 20, 7, 7, 0, 10
    assert_eq!(output, "10\n20\n7\n7\n0\n10\n");
}

#[test]
fn test_closure_bare_mutating_capture_propagates() {
    // B-2026-07-11-23 — a BARE closure that mutates a captured local captures
    // it by `mut ref` (design.md Rule 2), so writes propagate to the outer
    // binding across invocations. Previously the interpreter snapshot-copied
    // the capture and the mutation was lost (printed 0).
    let output = run_no_errors(
        r#"
fn main() {
    let mut c: i64 = 0;
    let f = |x: i64| { c = c + x; };
    f(3i64);
    f(4i64);
    println(f"{c}");
}
"#,
    );
    assert_eq!(output, "7\n");
}

#[test]
fn test_closure_capture_mutation_in_fold_no_run_build_divergence() {
    // B-2026-07-11-23 — a capture-mutating closure in a `fold` terminal. Codegen
    // INLINES the body (mutation propagates = correct); the interpreter used to
    // invoke it over a snapshot (mutation lost = 0), a run-vs-build divergence.
    // With Rule 2 capture inference the interpreter now agrees: count == 3.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3];
    let mut count = 0i64;
    let s = v.iter().fold(0i64, |a: i64, x: i64| { count = count + 1i64; a + x });
    println(f"{s}");
    println(f"{count}");
}
"#,
    );
    assert_eq!(output, "6\n3\n");
}

#[test]
fn test_closure_readonly_capture_unaffected() {
    // A bare closure that only READS a capture keeps by-value (snapshot)
    // semantics — the Rule 2 inference wraps ONLY mutated captures, so a
    // read-only capture is untouched.
    let output = run_no_errors(
        r#"
fn main() {
    let base: i64 = 10;
    let add = |x: i64| { base + x };
    println(add(5i64).to_string());
}
"#,
    );
    assert_eq!(output, "15\n");
}

#[test]
fn test_iter_reduce_terminal() {
    // B-2026-07-11-19 — the `reduce(f) -> Option[A]` terminal. Folds with the
    // first element as the seed; `None` on an empty source. Covers a sum
    // reduce, a max reduce, an empty source (None), and a `map().reduce`.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3, 4];
    match v.iter().reduce(|a: i64, x: i64| a + x) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
    match v.iter().reduce(|a: i64, x: i64| if a > x { a } else { x }) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
    let e: Vec[i64] = [];
    match e.iter().reduce(|a: i64, x: i64| a + x) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
    match v.iter().map(|x: i64| x * 2i64).reduce(|a: i64, x: i64| a + x) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
}
"#,
    );
    // 10, 4, none, 20
    assert_eq!(output, "10\n4\nnone\n20\n");
}

#[test]
fn test_iter_for_each_terminal() {
    // B-2026-07-11-19 / -23 — the side-effecting `for_each` terminal, unblocked
    // by mut-ref closure capture (its natural use mutates a captured
    // accumulator). Covers a bare for_each, a map().for_each, a
    // filter().for_each, and a range for_each.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3, 4];
    let mut total = 0i64;
    v.iter().for_each(|x: i64| { total = total + x; });
    println(f"{total}");
    v.iter().map(|x: i64| x * 2i64).for_each(|x: i64| { total = total + x; });
    println(f"{total}");
    let mut ev = 0i64;
    v.iter().filter(|x: i64| x % 2i64 == 0i64).for_each(|x: i64| { ev = ev + x; });
    println(f"{ev}");
    let mut rng = 0i64;
    (1i64..5i64).for_each(|x: i64| { rng = rng + x; });
    println(f"{rng}");
}
"#,
    );
    // 10, 30 (10+20), 6 (2+4), 10 (1+2+3+4)
    assert_eq!(output, "10\n30\n6\n10\n");
}

#[test]
fn test_option_result_map() {
    // B-2026-07-12-11 — `Option[T].map(f)` / `Result[T, E].map(f)` were
    // unimplemented in both runtimes despite typechecking. The interpreter now
    // applies `f` to a present payload (`Some`/`Ok`) and re-wraps, passing an
    // absent receiver (`None`/`Err`) through. Covers a fn-reference and an
    // annotated closure, a type-changing map (i64 -> bool), and a chain.
    let output = run_no_errors(
        r#"
fn dbl(n: i64) -> i64 { n * 2i64 }
fn main() {
    let a: Option[i64] = Some(5i64);
    println(f"{a.map(dbl).unwrap_or(0i64 - 1i64)}");
    let n: Option[i64] = None;
    println(f"{n.map(dbl).unwrap_or(0i64 - 1i64)}");
    let ok: Result[i64, String] = Ok(21i64);
    println(f"{ok.map(dbl).unwrap_or(0i64 - 1i64)}");
    let er: Result[i64, String] = Err(f"boom");
    println(f"{er.map(dbl).unwrap_or(0i64 - 99i64)}");
    println(f"{a.map(dbl).map(|x: i64| x + 1i64).unwrap_or(0i64 - 1i64)}");
    let m = a.map(|x: i64| x > 3i64);
    match m { Some(b) => { println(f"{b}"); } None => { println("none"); } }
}
"#,
    );
    assert_eq!(output, "10\n-1\n42\n-99\n11\ntrue\n");
}

#[test]
fn test_option_result_combinators() {
    // B-2026-07-14-6 — the standard Option/Result combinator family, previously
    // rejected at typecheck with no runtime dispatch. Non-closure batch:
    // `ok`/`err`/`or`/`and`/`ok_or`/`flatten`. Closure batch: `unwrap_or_else`/
    // `map_or`/`map_or_else`/`map_err`/`and_then`/`or_else`/`filter`. The
    // interpreter is the oracle for the parity that codegen is verified against.
    let output = run_no_errors(
        r#"
fn main() {
    let r: Result[i64, i64] = Ok(5i64);
    println(f"{r.ok().unwrap_or(0i64)}");
    let e: Result[i64, i64] = Err(7i64);
    println(f"{e.err().unwrap_or(0i64)}");
    let n: Option[i64] = None;
    println(f"{n.or(Some(9i64)).unwrap_or(0i64)}");
    let s: Option[i64] = Some(9i64);
    println(f"{s.and(Some(3i64)).unwrap_or(0i64)}");
    let s2: Option[i64] = Some(9i64);
    println(f"{s2.ok_or(99i64).unwrap()}");
    let oo: Option[Option[i64]] = Some(Some(42i64));
    println(f"{oo.flatten().unwrap_or(0i64)}");
    let n2: Option[i64] = None;
    println(f"{n2.unwrap_or_else(|| 42i64)}");
    let s3: Option[i64] = Some(5i64);
    println(f"{s3.map_or(0i64, |x: i64| x + 1i64)}");
    let s4: Option[i64] = Some(5i64);
    println(f"{s4.map_or_else(|| 0i64, |x: i64| x * 2i64)}");
    let er: Result[i64, i64] = Err(3i64);
    println(f"{er.map_err(|x: i64| x * 10i64).unwrap_err()}");
    let s5: Option[i64] = Some(5i64);
    println(f"{s5.and_then(|x: i64| Some(x + 1i64)).unwrap_or(0i64)}");
    let n3: Option[i64] = None;
    println(f"{n3.or_else(|| Some(9i64)).unwrap_or(0i64)}");
    let s6: Option[i64] = Some(5i64);
    println(f"{s6.filter(|x: i64| x > 3i64).unwrap_or(0i64)}");
    let s7: Option[i64] = Some(2i64);
    println(f"{s7.filter(|x: i64| x > 3i64).unwrap_or(0i64 - 1i64)}");
    let mut tk: Option[i64] = Some(5i64);
    let t = tk.take();
    println(f"{t.unwrap_or(0i64)}");
    println(f"{tk.unwrap_or(0i64 - 1i64)}");
    let mut gi: Option[i64] = None;
    println(f"{gi.get_or_insert(9i64)}");
    println(f"{gi.unwrap_or(0i64 - 1i64)}");
}
"#,
    );
    assert_eq!(
        output,
        "5\n7\n9\n3\n9\n42\n42\n6\n10\n30\n6\n9\n5\n-1\n5\n-1\n9\n9\n"
    );
}

#[test]
fn test_for_iter_mut() {
    // B-2026-07-14-10 — `for x in xs.iter_mut()` yields a mutable reference to
    // each element so `*x = …` / `*x += …` write back into the Vec. The
    // interpreter binds each element to a `VecSlotRef` over the shared element
    // storage; write-throughs land in the live Vec. Covers deref-assign,
    // compound deref-assign, a second pass, and a `String` element.
    let output = run_no_errors(
        r#"
fn main() {
    let mut v: Vec[i64] = [1i64, 2i64, 3i64, 4i64];
    for x in v.iter_mut() { *x = *x * 2i64; }
    for x in v.iter_mut() { *x += 1i64; }
    let mut s: i64 = 0i64;
    for y in v { s = s + y; }
    println(f"{s}");
    let mut words: Vec[String] = [f"a", f"bb"];
    for w in words.iter_mut() { *w = f"x"; }
    for w in words { println(f"{w}"); }
}
"#,
    );
    assert_eq!(output, "24\nx\nx\n");
}

#[test]
fn test_match_arm_guard() {
    // B-2026-07-12-9 — a `match` arm guard (`pat if cond => ..`) falls through
    // to the next arm when the condition is false. The interpreter has always
    // been correct here; this is the oracle the codegen fix is verified against
    // (codegen previously ignored the guard entirely). Covers scalar-binding,
    // enum-pattern, and multi-guard cascades.
    let output = run_no_errors(
        r#"
fn classify(n: i64) -> String {
    match n { 0 => f"zero", x if x < 0i64 => f"neg", x if x < 10i64 => f"small", _ => f"big" }
}
fn g(o: Option[i64]) -> i64 { match o { Some(x) if x > 5i64 => 1i64, Some(_) => 2i64, None => 3i64 } }
fn main() {
    println(classify(0i64));
    println(classify(0i64 - 3i64));
    println(classify(5i64));
    println(classify(100i64));
    println(f"{g(Some(10i64))} {g(Some(2i64))} {g(None)}");
}
"#,
    );
    assert_eq!(output, "zero\nneg\nsmall\nbig\n1 2 3\n");
}

/// Interpreter oracle for B-2026-08-27-34 — the branch-leaf `Option[shared]`
/// family, each selected value consumed three times (five on leg 11).
///
/// The interpreter was CORRECT throughout this bug: it has no refcount to get
/// wrong, so it is the oracle rather than a second suspect. This test pins
/// that side independently of the codegen twin, which lives in
/// `tests/codegen.rs` behind `#[cfg(feature = "llvm")]` and so does not run
/// under a plain `cargo test` at all — without this, the semantics the fix
/// restores would have no coverage on the default leg.
#[test]
fn option_shared_branch_leaf_survives_repeated_consumption() {
    let src = "shared struct Node { val: i64 }\n\
            fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
            fn show(t: Option[Node]) -> i64 {\n\
                match t { None => { return 0; } Some(n) => { return n.val; } }\n\
            }\n\
            fn main() {\n\
                let a1 = make(1); let b1 = make(2);\n\
                let t1 = if true { a1 } else { b1 };\n\
                println(f\"{show(t1)} {show(t1)} {show(t1)}\");\n\
                let a2 = make(3); let b2 = make(4);\n\
                let t2 = if false { a2 } else { b2 };\n\
                println(f\"{show(t2)} {show(t2)} {show(t2)}\");\n\
                let a3 = make(5); let b3 = make(6); let o3 = Some(1);\n\
                let t3 = if let Some(x) = o3 { a3 } else { b3 };\n\
                println(f\"{show(t3)} {show(t3)} {show(t3)}\");\n\
                let a4 = make(7); let b4 = make(8); let o4: Option[i64] = None;\n\
                let t4 = if let Some(y) = o4 { a4 } else { b4 };\n\
                println(f\"{show(t4)} {show(t4)} {show(t4)}\");\n\
                let a5 = make(9); let b5 = make(10); let k5 = 0;\n\
                let t5 = match k5 { 0 => a5, _ => b5 };\n\
                println(f\"{show(t5)} {show(t5)} {show(t5)}\");\n\
                let a6 = make(11);\n\
                let t6 = { a6 };\n\
                println(f\"{show(t6)} {show(t6)} {show(t6)}\");\n\
                let a7 = make(12); let b7 = make(13); let c7 = make(14); let k7 = 1;\n\
                let t7 = if k7 == 0 { a7 } else if k7 == 1 { b7 } else { c7 };\n\
                println(f\"{show(t7)} {show(t7)} {show(t7)}\");\n\
                let a8 = make(15); let b8 = make(16);\n\
                let t8 = if true { if true { a8 } else { b8 } } else { make(99) };\n\
                println(f\"{show(t8)} {show(t8)} {show(t8)}\");\n\
                let a9 = make(17);\n\
                let t9 = if true { a9 } else { make(99) };\n\
                println(f\"{show(t9)} {show(t9)} {show(t9)}\");\n\
                let a10 = make(18);\n\
                let t10 = if false { a10 } else { make(19) };\n\
                println(f\"{show(t10)} {show(t10)} {show(t10)}\");\n\
                let a11 = make(20); let b11 = make(21);\n\
                let t11 = if true { a11 } else { b11 };\n\
                println(f\"{show(t11)} {show(t11)} {show(t11)} {show(t11)} {show(t11)}\");\n\
                let a12 = make(22);\n\
                let t12 = if false { a12 } else { None };\n\
                println(f\"{show(t12)} {show(t12)} {show(t12)}\");\n\
            }";
    assert_eq!(
        run_no_errors(src),
        "1 1 1\n4 4 4\n5 5 5\n8 8 8\n9 9 9\n11 11 11\n13 13 13\n15 15 15\n17 17 17\n19 19 19\n20 20 20 20 20\n0 0 0\n",
        "every read of a branch-leaf `Option[shared]` must see the same value"
    );
}

/// Interpreter oracle for B-2026-08-27-43 — the ARM-LOCAL half of the same
/// branch-leaf family, where the arm binds a local and hands the local out.
///
/// Same reason as the sibling oracle above: the interpreter has no refcount to
/// get wrong and was correct throughout, and the codegen twin
/// (`option_shared_from_an_arm_local_leaf_survives_repeated_consumption`) sits
/// behind `#[cfg(feature = "llvm")]` where a plain `cargo test` never reaches
/// it. Leg 4 additionally pins that the enclosing binding the arm-local aliases
/// still reads correctly after the branch's value has been consumed.
#[test]
fn option_shared_arm_local_branch_leaf_survives_repeated_consumption() {
    let src = "shared struct Node { val: i64 }\n\
            fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
            fn show(t: Option[Node]) -> i64 {\n\
                match t { None => { return 0; } Some(n) => { return n.val; } }\n\
            }\n\
            fn main() {\n\
                let b = make(2);\n\
                let t1 = if true { let u = make(1); u } else { b };\n\
                println(f\"{show(t1)} {show(t1)} {show(t1)}\");\n\
                let c = make(3);\n\
                let t2 = if false { c } else { let u = make(4); u };\n\
                println(f\"{show(t2)} {show(t2)} {show(t2)}\");\n\
                let t3 = if true { let u = make(5); u } else { let v = make(6); v };\n\
                println(f\"{show(t3)} {show(t3)} {show(t3)}\");\n\
                let d = make(7);\n\
                let t4 = if true { let u = d; u } else { b };\n\
                println(f\"{show(t4)} {show(t4)} {show(t4)} {show(d)}\");\n\
                let t5 = if true { let u = make(8); u } else { b };\n\
                println(f\"{show(t5)} {show(t5)} {show(t5)} {show(t5)} {show(t5)}\");\n\
                let k = 1;\n\
                let t6 = match k { 1 => { let u = make(9); u } _ => { b } };\n\
                println(f\"{show(t6)} {show(t6)} {show(t6)}\");\n\
                let t7 = if true { { let u = make(10); u } } else { b };\n\
                println(f\"{show(t7)} {show(t7)} {show(t7)}\");\n\
                let t8 = if false { b } else if true { let u = make(11); u } else { b };\n\
                println(f\"{show(t8)} {show(t8)} {show(t8)}\");\n\
                let t9 = if true { let u = make(12); u } else { None };\n\
                println(f\"{show(t9)} {show(t9)} {show(t9)}\");\n\
                let src2 = make(13);\n\
                let t10 = if let Some(n) = src2 { let u = make(n.val); u } else { b };\n\
                println(f\"{show(t10)} {show(t10)} {show(t10)}\");\n\
                let mut i = 0;\n\
                while i < 3 {\n\
                    let t11 = if true { let u = make(20 + i); u } else { b };\n\
                    println(f\"{show(t11)} {show(t11)} {show(t11)}\");\n\
                    i = i + 1;\n\
                }\n\
                let t12 = if true { b } else { b };\n\
                println(f\"{show(t12)} {show(t12)} {show(t12)}\");\n\
            }";
    assert_eq!(
        run_no_errors(src),
        "1 1 1\n4 4 4\n5 5 5\n7 7 7 7\n8 8 8 8 8\n9 9 9\n10 10 10\n11 11 11\n\
         12 12 12\n13 13 13\n20 20 20\n21 21 21\n22 22 22\n2 2 2\n",
        "every read of an arm-local branch-leaf `Option[shared]` must see the same value"
    );
}

/// `.cmp()` on a receiver with no name to look up, under the tree-walker
/// (B-2026-08-27-47).
///
/// The defect this guards was codegen's, but the ORACLE for it lives here:
/// `tests/codegen.rs` twins the compiled answer against the interpreter's, so
/// if the tree-walker ever stops ordering these receivers the E2E fixture
/// keeps passing — both backends would simply agree on a new wrong answer.
/// That is the failure mode a twinned test cannot see by itself, and it is why
/// this half pins literal expected output instead of comparing backends.
///
/// It is also the only coverage of this semantics on the default `cargo test`
/// leg, since `tests/codegen.rs` is entirely `#[cfg(feature = "llvm")]`.
///
/// The `Rev` row is the anti-hijack guard: its hand-written `cmp` reverses the
/// order, so a structural declaration-order comparator would print `0` where
/// the user impl prints `2`.
#[test]
fn cmp_on_a_non_identifier_receiver_under_the_tree_walker() {
    let out = run_no_errors(
        r#"
#[derive(Ord, Eq)]
struct P { a: i64, b: i64 }

#[derive(Ord, Eq)]
enum Suit { Clubs, Hearts, Spades }

struct Rev { v: i64 }
impl PartialEq for Rev { fn eq(ref self, other: ref Rev) -> bool { self.v == other.v } }
impl Eq for Rev {}
impl PartialOrd for Rev { fn partial_cmp(ref self, other: ref Rev) -> Option[Ordering] { Some(other.v.cmp(self.v)) } }
impl Ord for Rev { fn cmp(ref self, other: ref Rev) -> Ordering { other.v.cmp(self.v) } }

fn mk(a: i64) -> P { return P { a: a, b: 0 }; }
fn suit() -> Suit { return Suit.Clubs; }

fn tag(o: Ordering) -> i64 {
    if o.is_lt() { return 0; }
    if o.is_eq() { return 1; }
    return 2;
}

fn main() {
    println(f"{tag(P { a: 1, b: 2 }.cmp(P { a: 1, b: 3 }))}");
    println(f"{tag(P { a: 1, b: 2 }.cmp(P { a: 1, b: 2 }))}");
    println(f"{tag(P { a: 9, b: 0 }.cmp(P { a: 1, b: 0 }))}");
    println(f"{tag(mk(1).cmp(mk(2)))}");
    println(f"{tag(suit().cmp(Suit.Spades))}");
    let v = [P { a: 1, b: 2 }, P { a: 1, b: 3 }];
    println(f"{tag(v[0].cmp(v[1]))}");
    let t = (P { a: 5, b: 0 }, P { a: 1, b: 0 });
    println(f"{tag(t.0.cmp(t.1))}");
    println(f"{tag(Rev { v: 1 }.cmp(Rev { v: 2 }))}");
}
"#,
    );
    assert_eq!(out, "0\n1\n2\n0\n0\n0\n2\n2\n");
}

/// `binary_search` carries element signedness under the tree-walker
/// (B-2026-08-28-6).
///
/// The tree-walker's `sort` has ordered `Vec[u64]` / `Vec[usize]` unsigned
/// since B-2026-07-04-8, but its `binary_search` arm kept calling the signed
/// `value_compare`. So the two disagreed WITHIN one backend: `sort` produced
/// `[1, 2, u64.MAX]`, `is_sorted` called it sorted, and `binary_search` then
/// failed to find elements that are in it.
///
/// Codegen's binary_search was signed too, so the E2E twin in
/// `tests/codegen.rs` could not have caught this — both backends returned the
/// same wrong `None`. This is the only coverage of it on the default
/// `cargo test` leg, and it pins literal output for the same reason.
///
/// The signed row is the over-correction guard: reading every integer as
/// unsigned would satisfy the rows above it.
#[test]
fn binary_search_carries_element_signedness_under_the_tree_walker() {
    let out = run_no_errors(
        r#"
fn main() {
    let a: Vec[u64] = [1u64, 2u64, 18446744073709551615u64];
    let s = a.is_sorted();
    println(f"{s}");
    let r1 = a.binary_search(2u64);
    match r1 { Some(i) => println(f"{i}"), None => println("absent"), }
    let r2 = a.binary_search(18446744073709551615u64);
    match r2 { Some(i) => println(f"{i}"), None => println("absent"), }

    let b: Vec[usize] = [1u64 as usize, 9223372036854775808u64 as usize];
    let r3 = b.binary_search(9223372036854775808u64 as usize);
    match r3 { Some(i) => println(f"{i}"), None => println("absent"), }

    let c: Vec[i64] = [0 - 5, 0 - 1, 3];
    let r4 = c.binary_search(0 - 5);
    match r4 { Some(i) => println(f"{i}"), None => println("absent"), }
}
"#,
    );
    // sorted / 2 at index 1 / MAX at index 2 / 2^63 at index 1 / -5 first.
    assert_eq!(out, "true\n1\n2\n1\n0\n");
}

/// `.cmp()` carries operand signedness under the tree-walker
/// (B-2026-08-28-5).
///
/// The tree-walker stores every integer width in an i64/i128 carrier, so a
/// `u64` / `usize` value at or above 2^63 rides as a NEGATIVE two's-complement
/// number. `<` has reinterpreted those bits since B-2026-07-04-8; `.cmp` never
/// did, so `u64.MAX.cmp(1u64)` answered `Less`.
///
/// This half is invisible to the E2E twin in `tests/codegen.rs`, and was
/// invisible to every run-vs-build differential the repo has: codegen's `.cmp`
/// was hardcoded signed too, so the two backends AGREED on the wrong answer.
/// It only surfaced when the compiled side was fixed and the twin started
/// failing. Pinning literal output here is what keeps it from regressing back
/// into agreement, and this is also its only coverage on the default
/// `cargo test` leg.
///
/// The `bool` rows belong with the integers rather than in a test of their
/// own: `bool` is an unsigned 1-bit integer, and it is the member of this
/// class that the compiled backends got wrong.
#[test]
fn cmp_carries_operand_signedness_under_the_tree_walker() {
    let out = run_no_errors(
        r#"
fn tag(o: Ordering) -> i64 {
    if o.is_lt() { return 0; }
    if o.is_eq() { return 1; }
    return 2;
}

fn main() {
    let a: u8 = 200;
    let b: u8 = 100;
    let c: u64 = 18446744073709551615u64;
    let d: u64 = 1;
    let e: usize = 9223372036854775808u64 as usize;
    let f: usize = 1;
    let g: i64 = 0 - 5;
    let h: i64 = 1;
    println(f"{tag(a.cmp(b))}");
    println(f"{tag(c.cmp(d))}");
    println(f"{tag(e.cmp(f))}");
    println(f"{tag(g.cmp(h))}");
    println(f"{tag(false.cmp(true))}");
    println(f"{tag(true.cmp(false))}");
    println(f"{tag(true.cmp(true))}");
}
"#,
    );
    // 200 > 100, u64.MAX > 1, 2^63 > 1 — then the SIGNED row, which must stay
    // signed: -5 < 1 is `Less`, and would read as `Greater` if the fix had
    // made every integer unsigned instead of consulting the operand's type.
    assert_eq!(out, "2\n2\n2\n0\n0\n2\n1\n");
}

/// `.cmp()` on a TUPLE under the tree-walker (B-2026-08-27-41).
///
/// `tests/codegen.rs` is entirely `#[cfg(feature = "llvm")]`, so without a
/// test here this semantics has NO coverage on the default `cargo test` leg —
/// the leg most contributors and the cheapest CI tier actually run.
///
/// The second half is the one that only exists here. A comparison written
/// against a bounded type PARAMETER lowers to `T.cmp`, and the interpreter is
/// untyped at runtime: `a` simply IS a `Value::Tuple`, so `smaller` answers
/// for a tuple with no substitution channel involved. Both compiled backends
/// still decline that spelling — the mono channel drops a tuple type argument
/// (B-2026-08-27-40) — so it is loud-refused there rather than wrong, and
/// cannot be twinned in `tests/codegen.rs` until that row lands.
///
/// `value_compare` has ordered `Value::Tuple` lexicographically all along;
/// what was missing was the `cmp` dispatch arm reaching it.
#[test]
fn tuple_cmp_dispatches_through_value_compare() {
    let out = run_no_errors(
        r#"
fn tag(o: Ordering) -> i64 {
    if o.is_lt() { return 0; }
    if o.is_eq() { return 1; }
    return 2;
}

fn main() {
    println(f"{tag((1, 2).cmp((1, 3)))}");
    println(f"{tag((1, 2).cmp((1, 2)))}");
    println(f"{tag((1, 2).cmp((0, 9)))}");
    println(f"{tag(("b", 1).cmp(("b", 2)))}");
    println(f"{tag((1, 2, 3).cmp((1, 2, 4)))}");
    println(f"{tag((1, (2, 3)).cmp((1, (2, 4))))}");
    println(f"{tag((true, 'z').cmp((true, 'a')))}");
}
"#,
    );
    assert_eq!(out, "0\n1\n2\n0\n0\n0\n2\n");
}

/// The bare-`T` spelling, which only the interpreter answers today
/// (B-2026-08-27-41; the compiled half waits on B-2026-08-27-40).
///
/// This is the shape the row was filed for: `fn smaller[T: Ord](a: T, b: T)
/// -> bool { a < b }` does not lower to a comparison — it lowers to `T.cmp` —
/// so a tuple argument used to die at "method 'cmp' not found on type
/// 'unknown'" even though `(1, 2) < (1, 3)` written directly had worked since
/// B-2026-08-27-33. `karac check` passed the whole time, which is what made it
/// a run-vs-build hole rather than a rejection.
#[test]
fn tuple_cmp_through_a_bare_type_parameter() {
    let out = run_no_errors(
        r#"
fn smaller[T: Ord](a: T, b: T) -> bool { return a < b; }

fn main() {
    println(f"{smaller((1, 2), (1, 3))}");
    println(f"{smaller((1, 3), (1, 2))}");
    println(f"{smaller((1, 2), (1, 2))}");
    println(f"{smaller(("a", 9), ("b", 0))}");
    println(f"{smaller(1, 2)}");
}
"#,
    );
    assert_eq!(out, "true\nfalse\nfalse\ntrue\ntrue\n");
}

#[test]
fn test_mut_ref_option_shared_writeback() {
    // B-2026-07-12-3 — reassigning through a `mut ref Option[shared]` param
    // propagates to the caller. The interpreter has always been correct; this
    // is the oracle the codegen fix (writeback through the borrow pointer) is
    // verified against.
    let output = run_no_errors(
        r#"
shared struct Node { mut val: i64, mut next: Option[Node] }
fn setit(prev: mut ref Option[Node], n: Node) { prev = Some(n); }
fn main() {
    let mut cur: Option[Node] = Some(Node { val: 1i64, next: None });
    let a = Node { val: 2i64, next: None };
    setit(mut cur, a);
    let b = Node { val: 3i64, next: None };
    setit(mut cur, b);
    match cur {
        None => { println("none"); }
        Some(p) => { println(f"val: {p.val}"); }
    }
}
"#,
    );
    assert_eq!(output, "val: 3\n");
}

#[test]
fn test_match_tuple_pattern() {
    // B-2026-07-12-13 — a `match` on a tuple scrutinee discriminates on each
    // element. The interpreter has always been correct; this is the oracle for
    // the codegen fix (codegen previously always fired the first tuple arm).
    let output = run_no_errors(
        r#"
fn f(a: i64, b: i64) -> i64 { match (a, b) { (0i64, 0i64) => 10i64, (1i64, 2i64) => 20i64, _ => 30i64 } }
fn nested(a: i64, b: i64, c: i64) -> i64 {
    match (a, (b, c)) { (0i64, (1i64, 2i64)) => 1i64, (0i64, (_, _)) => 2i64, _ => 3i64 }
}
fn main() {
    println(f"{f(0i64, 0i64)} {f(1i64, 2i64)} {f(5i64, 5i64)}");
    println(f"{nested(0i64, 1i64, 2i64)} {nested(0i64, 4i64, 5i64)} {nested(8i64, 1i64, 2i64)}");
}
"#,
    );
    assert_eq!(output, "10 20 30\n1 2 3\n");
}

