#[test]
fn test_iter_step_by_yields_every_nth_element() {
    let output = run_no_errors(
        r#"
fn main() {
    let v = [1, 2, 3, 4, 5, 6, 7];
    for x in v.iter().step_by(2) {
        println(x);
    }
}
"#,
    );
    // Yields indices 0, 2, 4, 6 → 1, 3, 5, 7.
    assert_eq!(output, "1\n3\n5\n7\n");
}

