#[test]
fn test_lazyframe_group_by_agg_pipeline() {
    // Phase-11 LazyDataFrame slice 4: the full design-sketch pipeline —
    // filter → group_by(keys) → agg(count/sum/mean with alias_) → sort on
    // a DERIVED column. Groups are first-occurrence-ordered; the output
    // schema is keys then aggregates (alias_ wins, else <col>_<op>);
    // downstream ops validate against the derived schema.
    let out = run_no_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"city\", Column.from_vec([\"oslo\", \"rome\", \"oslo\", \"rome\", \"oslo\"]));\n\
             df.insert(\"name\", Column.from_vec([\"a\", \"b\", \"c\", \"d\", \"e\"]));\n\
             df.insert(\"pop\", Column.from_vec([10i64, 20i64, 30i64, 40i64, 50i64]));\n\
             let plan = df.lazy()\n\
                 .filter(col(\"pop\").gt(15))\n\
                 .group_by(vec![col(\"city\")])\n\
                 .agg(vec![col(\"name\").count().alias_(\"cnt\"), col(\"pop\").sum(), col(\"pop\").mean()])\n\
                 .sort(vec![col(\"pop_sum\").desc()]);\n\
             println(plan.explain());\n\
             let out = plan.collect();\n\
             println(out.width()); println(out.height());\n\
             for n in out.column_names() { println(n); }\n\
             let cities: Column[String] = out.column(\"city\");\n\
             let sums: Column[i64] = out.column(\"pop_sum\");\n\
             let means: Column[f64] = out.column(\"pop_mean\");\n\
             match cities[0] { Some(v) => println(v), None => println(\"null\") }\n\
             match sums[0] { Some(v) => println(v), None => println(-1i64) }\n\
             match means[0] { Some(v) => println(v), None => println(-1.0) }\n\
             match cities[1] { Some(v) => println(v), None => println(\"null\") }\n\
             match sums[1] { Some(v) => println(v), None => println(-1i64) }\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         SORT [pop_sum desc]\n\
         \x20 GROUP BY [city] AGG [count(name) as cnt, sum(pop), mean(pop)]\n\
         \x20   FILTER (pop > 15)\n\
         \x20     SCAN [city, name, pop]\n\
         == optimized ==\n\
         SORT [pop_sum desc]\n\
         \x20 GROUP BY [city] AGG [count(name) as cnt, sum(pop), mean(pop)]\n\
         \x20   FILTER (pop > 15)\n\
         \x20     SCAN cols=[city, name, pop]\n\
         4\n2\ncity\ncnt\npop_sum\npop_mean\noslo\n80\n40\nrome\n60\n",
        "group_by/agg must derive schema and sort on derived columns",
    );
}

#[test]
fn test_lazyframe_group_by_agg_nulls_and_errors() {
    // count() counts NON-NULL only; sum over an all-null group is NULL;
    // a non-aggregate agg entry and an aggregate in filter position are
    // loud errors; a post-groupby ref to a pre-groupby column errors.
    let out = run_no_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"k\", Column.from_vec([\"x\", \"x\", \"y\"]));\n\
             let nn: Vec[Option[i64]] = vec![Some(1i64), None, None];\n\
             df.insert(\"v\", Column.from_iter_nullable(nn));\n\
             let out = df.lazy().group_by(vec![LazyExpr.col(\"k\")]).agg(vec![LazyExpr.col(\"v\").count(), LazyExpr.col(\"v\").sum()]).collect();\n\
             let cnts: Column[i64] = out.column(\"v_count\");\n\
             let sums: Column[i64] = out.column(\"v_sum\");\n\
             match cnts[0] { Some(v) => println(v), None => println(-1i64) }\n\
             match cnts[1] { Some(v) => println(v), None => println(-1i64) }\n\
             match sums[1] { Some(v) => println(v), None => println(\"null-ok\") }\n\
         }",
    );
    assert_eq!(out, "1\n0\nnull-ok\n");
    let errors = runtime_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().group_by(vec![LazyExpr.col(\"a\")]).agg(vec![LazyExpr.col(\"a\")]).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("must be an aggregate")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().filter(LazyExpr.col(\"a\").sum().gt(0)).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("only meaningful inside LazyGroupBy.agg")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"k\", Column.from_vec([\"x\"]));\n\
             df.insert(\"v\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().group_by(vec![LazyExpr.col(\"k\")]).agg(vec![LazyExpr.col(\"v\").sum()]).filter(LazyExpr.col(\"v\").gt(0)).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("no column named 'v' at this plan step")),
        "{errors:?}",
    );
}

#[test]
fn test_lazyframe_join_inner_collision_suffix_and_explain() {
    // Phase-11 LazyDataFrame slice 5: inner `join` — the plan becomes a
    // tree (the right side is a nested sub-plan, rendered compactly on
    // the JOIN line). Output schema = left columns, then right minus the
    // keys with `_right` suffixed onto collisions. Unmatched rows on
    // either side drop; left row order is preserved.
    let out = run_no_errors(
        "fn main() {\n\
             let mut people: DataFrame = DataFrame.new();\n\
             people.insert(\"id\", Column.from_vec([1i64, 2i64, 3i64, 4i64]));\n\
             people.insert(\"name\", Column.from_vec([\"ada\", \"bob\", \"cyd\", \"dee\"]));\n\
             people.insert(\"city\", Column.from_vec([\"rome\", \"oslo\", \"rome\", \"lima\"]));\n\
             let mut cities: DataFrame = DataFrame.new();\n\
             cities.insert(\"city\", Column.from_vec([\"rome\", \"oslo\", \"kiev\"]));\n\
             cities.insert(\"pop\", Column.from_vec([60i64, 80i64, 30i64]));\n\
             cities.insert(\"name\", Column.from_vec([\"Roma\", \"Oslo\", \"Kyiv\"]));\n\
             let plan = people.lazy().join(cities.lazy(), vec![\"city\"]);\n\
             println(plan.explain());\n\
             let out = plan.collect();\n\
             println(out.width()); println(out.height());\n\
             for n in out.column_names() { println(n); }\n\
             let names: Column[String] = out.column(\"name\");\n\
             let rn: Column[String] = out.column(\"name_right\");\n\
             let pops: Column[i64] = out.column(\"pop\");\n\
             for i in 0..out.height() {\n\
                 match names[i] { Some(v) => println(v), None => println(\"null\") }\n\
                 match rn[i] { Some(v) => println(v), None => println(\"null\") }\n\
                 match pops[i] { Some(v) => println(v), None => println(-1i64) }\n\
             }\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         JOIN on=[city] right=(SCAN [city, pop, name])\n\
         \x20 SCAN [id, name, city]\n\
         == optimized ==\n\
         JOIN on=[city] right=(SCAN cols=[*])\n\
         \x20 SCAN cols=[*]\n\
         5\n3\nid\nname\ncity\npop\nname_right\n\
         ada\nRoma\n60\nbob\nOslo\n80\ncyd\nRoma\n60\n",
        "inner join must suffix collisions, drop unmatched rows, keep left order",
    );
}

#[test]
fn test_lazyframe_join_pipeline_nulls_and_fanout() {
    // Ops compose around a join: a right-side select narrows the right
    // sub-plan's scan; filter/select after the join see the joined
    // schema; a left select BEFORE the join renders as an explicit
    // SELECT step under the JOIN (the fold applies it at the join
    // boundary — the rendering must not pretend the scan keeps all
    // columns). NULL keys join nothing; duplicate right matches fan out
    // in left-row-then-right-match order.
    let out = run_no_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut people: DataFrame = DataFrame.new();\n\
             people.insert(\"id\", Column.from_vec([1i64, 2i64, 3i64, 4i64]));\n\
             people.insert(\"name\", Column.from_vec([\"ada\", \"bob\", \"cyd\", \"dee\"]));\n\
             people.insert(\"city\", Column.from_vec([\"rome\", \"oslo\", \"rome\", \"lima\"]));\n\
             let mut cities: DataFrame = DataFrame.new();\n\
             cities.insert(\"city\", Column.from_vec([\"rome\", \"oslo\", \"kiev\"]));\n\
             cities.insert(\"pop\", Column.from_vec([60i64, 80i64, 30i64]));\n\
             cities.insert(\"name\", Column.from_vec([\"Roma\", \"Oslo\", \"Kyiv\"]));\n\
             let plan = people.lazy()\n\
                 .join(cities.lazy().select(vec![\"city\", \"pop\"]), vec![\"city\"])\n\
                 .filter(col(\"pop\").gt(50))\n\
                 .select(vec![\"name\", \"pop\"]);\n\
             println(plan.explain());\n\
             println(plan.collect().height());\n\
             let pre = people.lazy().select(vec![\"name\", \"city\"]).join(cities.lazy(), vec![\"city\"]);\n\
             println(pre.explain());\n\
             println(pre.collect().width());\n\
             let mut left: DataFrame = DataFrame.new();\n\
             let lk: Vec[Option[i64]] = vec![Some(1i64), None, Some(3i64)];\n\
             left.insert(\"k\", Column.from_iter_nullable(lk));\n\
             let mut right: DataFrame = DataFrame.new();\n\
             let rk: Vec[Option[i64]] = vec![Some(1i64), None];\n\
             right.insert(\"k\", Column.from_iter_nullable(rk));\n\
             right.insert(\"w\", Column.from_vec([100i64, 200i64]));\n\
             let nj = left.lazy().join(right.lazy(), vec![\"k\"]).collect();\n\
             println(nj.height());\n\
             let ws: Column[i64] = nj.column(\"w\");\n\
             match ws[0] { Some(v) => println(v), None => println(-1i64) }\n\
             let mut dup: DataFrame = DataFrame.new();\n\
             dup.insert(\"city\", Column.from_vec([\"rome\", \"rome\"]));\n\
             dup.insert(\"tag\", Column.from_vec([\"a\", \"b\"]));\n\
             let fan = people.lazy().select(vec![\"name\", \"city\"]).join(dup.lazy(), vec![\"city\"]).collect();\n\
             println(fan.height());\n\
             let n4: Column[String] = fan.column(\"name\");\n\
             let t4: Column[String] = fan.column(\"tag\");\n\
             for i in 0..fan.height() {\n\
                 match n4[i] { Some(v) => println(v), None => println(\"null\") }\n\
                 match t4[i] { Some(v) => println(v), None => println(\"null\") }\n\
             }\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         SELECT [name, pop]\n\
         \x20 FILTER (pop > 50)\n\
         \x20   JOIN on=[city] right=(SELECT [city, pop] <- SCAN [city, pop, name])\n\
         \x20     SCAN [id, name, city]\n\
         == optimized ==\n\
         SELECT [name, pop]\n\
         \x20 FILTER (pop > 50)\n\
         \x20   JOIN on=[city] right=(SCAN cols=[city, pop])\n\
         \x20     SCAN cols=[*]\n\
         3\n\
         == logical plan ==\n\
         JOIN on=[city] right=(SCAN [city, pop, name])\n\
         \x20 SELECT [name, city]\n\
         \x20   SCAN [id, name, city]\n\
         == optimized ==\n\
         JOIN on=[city] right=(SCAN cols=[*])\n\
         \x20 SELECT [name, city]\n\
         \x20   SCAN cols=[*]\n\
         4\n\
         1\n100\n\
         4\nada\na\nada\nb\ncyd\na\ncyd\nb\n",
        "join must compose with select/filter, drop NULL keys, fan out duplicates",
    );
}

#[test]
fn test_lazyframe_join_errors() {
    // Missing keys validate at collect (RIGHT side checked against the
    // right sub-plan's FINAL schema; LEFT side against the columns
    // visible at the join step); incompatible key types across the two
    // sides are a loud error, not a silent empty join.
    let out = run_no_errors(
        "fn main() {\n\
             let mut l: DataFrame = DataFrame.new();\n\
             l.insert(\"a\", Column.from_vec([1i64]));\n\
             let mut r: DataFrame = DataFrame.new();\n\
             r.insert(\"b\", Column.from_vec([1i64]));\n\
             let bad = l.lazy().join(r.lazy(), vec![\"a\"]);\n\
             println(\"built-ok\");\n\
             println(bad.explain());\n\
         }",
    );
    assert!(
        out.contains("built-ok")
            && out.contains("INVALID PLAN: LazyFrame.join: no column named 'a' on the RIGHT side"),
        "got: {out}",
    );
    let errors = runtime_errors(
        "fn main() {\n\
             let mut l: DataFrame = DataFrame.new();\n\
             l.insert(\"a\", Column.from_vec([1i64]));\n\
             let mut r: DataFrame = DataFrame.new();\n\
             r.insert(\"b\", Column.from_vec([1i64]));\n\
             let _ = l.lazy().join(r.lazy(), vec![\"b\"]).collect();\n\
         }",
    );
    assert!(
        errors.iter().any(|e| e
            .message
            .contains("LazyFrame.join: no column named 'b' on the LEFT side")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "fn main() {\n\
             let mut l: DataFrame = DataFrame.new();\n\
             l.insert(\"k\", Column.from_vec([1i64, 2i64]));\n\
             let mut r: DataFrame = DataFrame.new();\n\
             r.insert(\"k\", Column.from_vec([\"1\", \"2\"]));\n\
             r.insert(\"w\", Column.from_vec([10i64, 20i64]));\n\
             let _ = l.lazy().join(r.lazy(), vec![\"k\"]).collect();\n\
         }",
    );
    assert!(
        errors.iter().any(|e| e
            .message
            .contains("LazyFrame.join: key 'k' has incompatible types on the two sides")),
        "{errors:?}",
    );
}

#[test]
fn test_lazyframe_constant_folding_and_cse() {
    // Phase-11 LazyDataFrame slice 6: constant folding + CSE — the last
    // two passes of the pinned Option A optimizer list. `lit(..)` wraps a
    // runtime scalar as an expression; literal arms fold at PLAN time
    // (the logical plan keeps the verbatim tree, the optimized one shows
    // the folded form): `x and true` → `x` (and the scan projection
    // narrows to what the folded predicate reads), a constant-true
    // filter drops out entirely (single-scan rendering returns), a
    // constant-false one stays honest (`FILTER false`, empty collect,
    // schema preserved), `x or true` collapses the filter away, literal
    // comparisons fold through `not_`, and structurally-identical
    // conjuncts dedupe (CSE) — both within one predicate and across
    // adjacent fused filters.
    let out = run_no_errors(
        "import std.lazy.{col, lit};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64, 5i64, 9i64]));\n\
             df.insert(\"b\", Column.from_vec([10i64, 20i64, 30i64]));\n\
             let enabled = true;\n\
             let plan = df.lazy().filter(col(\"a\").gt(2).and_(lit(enabled))).select(vec![\"a\"]);\n\
             println(plan.explain());\n\
             println(plan.collect().height());\n\
             let t = df.lazy().filter(lit(true)).select(vec![\"b\"]);\n\
             println(t.explain());\n\
             println(t.collect().height());\n\
             let f = df.lazy().filter(lit(false));\n\
             println(f.explain());\n\
             println(f.collect().height());\n\
             println(f.collect().width());\n\
             let dup = df.lazy().filter(col(\"a\").gt(2)).filter(col(\"a\").gt(2));\n\
             println(dup.explain());\n\
             println(dup.collect().height());\n\
             let dom = df.lazy().filter(col(\"a\").gt(2).or_(lit(true)));\n\
             println(dom.explain());\n\
             println(dom.collect().height());\n\
             let cmpf = df.lazy().filter(lit(3).gt(4).not_());\n\
             println(cmpf.explain());\n\
             let inner = df.lazy().filter(col(\"a\").gt(2).and_(col(\"a\").gt(2)));\n\
             println(inner.explain());\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         SELECT [a]\n\
         \x20 FILTER ((a > 2) and true)\n\
         \x20   SCAN [a, b]\n\
         == optimized ==\n\
         SELECT [a]\n\
         \x20 FILTER (a > 2)\n\
         \x20   SCAN cols=[a]\n\
         2\n\
         == logical plan ==\n\
         SELECT [b]\n\
         \x20 FILTER true\n\
         \x20   SCAN [a, b]\n\
         == optimized ==\n\
         SCAN cols=[b]\n\
         3\n\
         == logical plan ==\n\
         FILTER false\n\
         \x20 SCAN [a, b]\n\
         == optimized ==\n\
         FILTER false\n\
         \x20 SCAN cols=[*]\n\
         0\n2\n\
         == logical plan ==\n\
         FILTER (a > 2)\n\
         \x20 FILTER (a > 2)\n\
         \x20   SCAN [a, b]\n\
         == optimized ==\n\
         FILTER (a > 2)\n\
         \x20 SCAN cols=[a]\n\
         2\n\
         == logical plan ==\n\
         FILTER ((a > 2) or true)\n\
         \x20 SCAN [a, b]\n\
         == optimized ==\n\
         SCAN cols=[*]\n\
         3\n\
         == logical plan ==\n\
         FILTER (not (3 > 4))\n\
         \x20 SCAN [a, b]\n\
         == optimized ==\n\
         SCAN cols=[*]\n\
         == logical plan ==\n\
         FILTER ((a > 2) and (a > 2))\n\
         \x20 SCAN [a, b]\n\
         == optimized ==\n\
         FILTER (a > 2)\n\
         \x20 SCAN cols=[a]\n",
        "literal arms must fold at plan time; duplicate conjuncts must dedupe",
    );
}

#[test]
fn test_lazyframe_constant_folding_preserves_errors() {
    // Folding must never mask an error: a bad column name in an elided
    // branch stays loud (validation runs on the ORIGINAL expression);
    // `lit` rejects non-scalar values; a type-mismatched literal
    // comparison stays UNFOLDED and errors at collect.
    let errors = runtime_errors(
        "import std.lazy.{col, lit};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().filter(col(\"nope\").gt(1).and_(lit(false))).collect();\n\
         }",
    );
    assert!(
        errors.iter().any(|e| e
            .message
            .contains("no column named 'nope' at this plan step")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "import std.lazy.{lit};\n\
         fn main() {\n\
             let v: Vec[i64] = vec![1i64];\n\
             let _ = lit(v);\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("LazyExpr.lit expects a scalar literal")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "import std.lazy.{lit};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().filter(lit(1).eq(\"x\")).collect();\n\
         }",
    );
    assert!(
        errors.iter().any(|e| e
            .message
            .contains("cannot compare values of different types")),
        "{errors:?}",
    );
}

#[test]
fn test_stdlib_wrapper_runtime_error_attributed_to_call_site() {
    // B-2026-07-21-17: a runtime error raised inside a spliced gated-stdlib
    // wrapper body (std.lazy's `lit`) carried the MODULE source's own
    // line/col — the wrapper items are cloned from the module's separate
    // parse — which the CLI then renders against the USER file's path
    // (`lit(vec![1i64])` reported "at <user file>:19:5", line 19 of
    // lazy.kara, in a 5-line program). The interpreter now attributes such
    // errors to the OUTERMOST wrapper call site: a real user-file location,
    // and where the faulting argument lives. Line 4 below is the `lit(v)`
    // call; pre-fix the span was the wrapper body's module line (18+). A
    // plain user-code error and an error AFTER a successful wrapper call
    // keep their raise-site spans (the wrapper stack is popped on return).
    let errors = runtime_errors(
        "import std.lazy.{lit};\n\
         fn main() {\n\
             let v: Vec[i64] = vec![1i64];\n\
             let _ = lit(v);\n\
         }",
    );
    let e = errors
        .iter()
        .find(|e| e.message.contains("LazyExpr.lit expects a scalar literal"))
        .expect("lit rejection error missing");
    assert_eq!(
        e.span.line, 4,
        "error must point at the user call site, got line {} (span {:?})",
        e.span.line, e.span
    );
    // Post-wrapper user error: attribution untouched (line 5, the v2[3]).
    let errors = runtime_errors(
        "import std.lazy.{lit};\n\
         fn main() {\n\
             let _ok = lit(5i64);\n\
             let v2: Vec[i64] = vec![];\n\
             let _ = v2[3];\n\
         }",
    );
    let e = errors
        .iter()
        .find(|e| e.message.contains("out of bounds"))
        .expect("oob error missing");
    assert_eq!(
        e.span.line, 5,
        "post-wrapper user error must keep its raise-site line, got {} ({:?})",
        e.span.line, e.span
    );
}

#[test]
fn test_lazyframe_with_columns_arithmetic_pipeline() {
    // Phase-11 LazyDataFrame slice 7: `with_columns` (the expression-
    // projection leg) + arithmetic expression nodes (add/sub/mul/div).
    // Entries need an output name (bare col keeps its own — a rename
    // copy via alias_; computed entries must be aliased); results
    // REPLACE a same-named column in place or APPEND; entries see the
    // step's INPUT frame (Polars parallel semantics). NULL propagates
    // through arithmetic; i64 pairs stay i64, an f64 side widens; a
    // computed bool column comes from a comparison expression; sort
    // works on a computed column. A select BEFORE with_columns flushes
    // as an explicit SELECT step whose columns join the scan set (they
    // flow through to the output); constant folding applies inside
    // entries (`2 + 1` folds to `3`).
    let out = run_no_errors(
        "import std.lazy.{col, lit};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64, 2i64, 3i64]));\n\
             df.insert(\"b\", Column.from_vec([10.5, 20.5, 30.5]));\n\
             df.insert(\"name\", Column.from_vec([\"x\", \"y\", \"z\"]));\n\
             let plan = df.lazy().with_columns(vec![col(\"a\").mul(2).alias_(\"a2\"), col(\"b\").add(col(\"a\")).alias_(\"ab\"), col(\"name\").alias_(\"label\")]);\n\
             println(plan.explain());\n\
             let out = plan.collect();\n\
             println(out.width());\n\
             for n in out.column_names() { println(n); }\n\
             let a2: Column[i64] = out.column(\"a2\");\n\
             let ab: Column[f64] = out.column(\"ab\");\n\
             match a2[2] { Some(v) => println(v), None => println(-1i64) }\n\
             match ab[0] { Some(v) => println(v), None => println(-1.0) }\n\
             let rep = df.lazy().with_columns(vec![col(\"a\").add(100).alias_(\"a\")]).collect();\n\
             for n in rep.column_names() { println(n); }\n\
             let ra: Column[i64] = rep.column(\"a\");\n\
             match ra[0] { Some(v) => println(v), None => println(-1i64) }\n\
             let nn: Vec[Option[i64]] = vec![Some(1i64), None];\n\
             let mut nf: DataFrame = DataFrame.new();\n\
             nf.insert(\"v\", Column.from_iter_nullable(nn));\n\
             let v10: Column[i64] = nf.lazy().with_columns(vec![col(\"v\").mul(10).alias_(\"v10\")]).collect().column(\"v10\");\n\
             match v10[0] { Some(v) => println(v), None => println(\"null\") }\n\
             match v10[1] { Some(v) => println(v), None => println(\"null\") }\n\
             let piped = df.lazy()\n\
                 .select(vec![\"a\", \"b\"])\n\
                 .with_columns(vec![col(\"a\").mul(lit(2).add(1)).alias_(\"a3\")])\n\
                 .filter(col(\"a3\").gt(3));\n\
             println(piped.explain());\n\
             let out4 = piped.collect();\n\
             println(out4.height());\n\
             let a3: Column[i64] = out4.column(\"a3\");\n\
             match a3[0] { Some(v) => println(v), None => println(-1i64) }\n\
             let bg: Column[bool] = df.lazy().with_columns(vec![col(\"a\").ge(2).alias_(\"big\")]).collect().column(\"big\");\n\
             match bg[0] { Some(v) => println(v), None => println(\"null\") }\n\
             match bg[1] { Some(v) => println(v), None => println(\"null\") }\n\
             let s = df.lazy().with_columns(vec![col(\"a\").mul(-1).alias_(\"neg\")]).sort(vec![col(\"neg\")]).collect();\n\
             let sa: Column[i64] = s.column(\"a\");\n\
             match sa[0] { Some(v) => println(v), None => println(-1i64) }\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         WITH [(a * 2) as a2, (b + a) as ab, name as label]\n\
         \x20 SCAN [a, b, name]\n\
         == optimized ==\n\
         WITH [(a * 2) as a2, (b + a) as ab, name as label]\n\
         \x20 SCAN cols=[a, b, name]\n\
         6\na\nb\nname\na2\nab\nlabel\n\
         6\n11.5\n\
         a\nb\nname\n101\n\
         10\nnull\n\
         == logical plan ==\n\
         FILTER (a3 > 3)\n\
         \x20 WITH [(a * (2 + 1)) as a3]\n\
         \x20   SELECT [a, b]\n\
         \x20     SCAN [a, b, name]\n\
         == optimized ==\n\
         FILTER (a3 > 3)\n\
         \x20 WITH [(a * 3) as a3]\n\
         \x20   SELECT [a, b]\n\
         \x20     SCAN cols=[a, b]\n\
         2\n6\n\
         false\ntrue\n\
         3\n",
        "with_columns must compute/replace/append, fold inside entries, flush selects honestly",
    );
}

#[test]
fn test_lazyframe_with_columns_errors() {
    // Unnamed computed entries and duplicate output names are loud at
    // fold (explain shows INVALID PLAN, collect errors); i64 division
    // by zero and arithmetic on non-numeric columns are loud at eval.
    let errors = runtime_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().with_columns(vec![col(\"a\").mul(2)]).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("each entry needs an output name")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().with_columns(vec![col(\"a\").mul(2).alias_(\"z\"), col(\"a\").add(1).alias_(\"z\")]).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("duplicate output name 'z'")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64, 0i64]));\n\
             let _ = df.lazy().with_columns(vec![col(\"a\").div(col(\"a\")).alias_(\"q\")]).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer division by zero")),
        "{errors:?}",
    );
    let errors = runtime_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"s\", Column.from_vec([\"x\"]));\n\
             let _ = df.lazy().with_columns(vec![col(\"s\").add(1).alias_(\"t\")]).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("arithmetic on non-numeric values")),
        "{errors:?}",
    );
}

// ── Script mode (design.md § Script mode, phase-8 Q7) ─────────────────────

#[test]
fn test_script_mode_top_level_statements_execute() {
    // A main-less file of top-level statements runs via the synthesized
    // `fn main()` — previously the statements were silently dropped and
    // the file was a no-op under the interpreter.
    assert_eq!(run("let x = 41;\nprintln(x + 1);\n"), "42\n");
}

#[test]
fn test_script_mode_items_hoist_and_statements_run_in_order() {
    assert_eq!(
        run("fn double(x: i64) -> i64 { x * 2 }\nlet y = double(21);\nprintln(y);\nprintln(y + 1);\n"),
        "42\n43\n"
    );
}

// ── Narrow-float precision (B-2026-07-22-4) ────────────────────────────────

#[test]
fn test_narrow_float_literals_and_casts_round_to_storage_precision() {
    // The interpreter models every float as f64, but a value TYPED f16/bf16
    // must still be representable in that format or it diverges from all
    // three LLVM backends (which materialize `2.7bf16` as the bfloat
    // constant 2.703125 and lower `x as bf16` with an RNE truncation).
    // Literals round at creation; casts round at the cast.
    assert_eq!(run("println(2.7bf16);\n"), "2.703125\n");
    assert_eq!(run("println(2.7f16);\n"), "2.69921875\n");
    // Casts through a fn boundary (the B-2026-07-22-4 filing shape).
    assert_eq!(
        run("fn nar(x: f64) -> bf16 { x as bf16 }\nprintln(nar(2.7));\n"),
        "2.703125\n"
    );
    assert_eq!(
        run("fn narf(x: f64) -> f16 { x as f16 }\nprintln(narf(2.7));\n"),
        "2.69921875\n"
    );
    assert_eq!(
        run("fn nar32(x: f32) -> bf16 { x as bf16 }\nprintln(nar32(2.7f32));\n"),
        "2.703125\n"
    );
    // int → narrow float takes the rounding path too (65505 is not
    // f16-representable; nearest even is 65504).
    assert_eq!(run("println(65505 as f16);\n"), "65504\n");
    // Exact values stay exact.
    assert_eq!(run("println(1.25bf16);\nprintln(1.5f16);\n"), "1.25\n1.5\n");
}

/// B-2026-07-29-27 / B-2026-07-29-31 — the interpreter half of the synthesized
/// `#[derive(Clone)]` method. The worker is `deep_clone_value`, not the derived
/// Rust `Clone`: the latter bumps the `Arc<RwLock<..>>` behind a `Value::Array`
/// FIELD, so the copy would share the source's storage and `b.items.push(..)`
/// would be visible through `a`. Value semantics demand independent storage,
/// and codegen's emitters deep-copy — so a shallow interpreter clone would also
/// be a run-vs-build divergence.
#[test]
fn test_derived_clone_is_deep_on_struct_enum_and_option() {
    assert_eq!(
        run("#[derive(Clone)]\n\
             struct S { n: i64, items: Vec[i64] }\n\
             #[derive(Clone)]\n\
             enum E { A(i64), B(String) }\n\
             fn dup[T: Clone](x: T) -> T { x.clone() }\n\
             let mut a = S { n: 1, items: Vec.new() };\n\
             a.items.push(10);\n\
             let mut b = a.clone();\n\
             b.items.push(20);\n\
             b.n = 99;\n\
             println(f\"{a.n} {a.items.len()} {b.n} {b.items.len()}\");\n\
             let e = E.B(\"payload\");\n\
             match dup(e) { E.A(k) => println(f\"{k}\"), E.B(t) => println(t) }\n\
             let o: Option[String] = Option.Some(\"inner\");\n\
             println(o.clone().unwrap());\n"),
        "1 1 99 2\npayload\ninner\n"
    );
}

/// A hand-written `fn clone` must WIN over the derive-driven synthesis on both
/// surfaces: the typechecker declines the built-in arm when `env.find_method`
/// resolves one, so the interpreter's arm has to decline too or it would shadow
/// the body the typechecker resolved.
#[test]
fn test_user_clone_impl_wins_over_derive_synthesis() {
    assert_eq!(
        run("struct S { n: i64 }\n\
             impl S { fn clone(ref self) -> S { S { n: self.n + 100 } } }\n\
             let s = S { n: 1 };\n\
             println(f\"{s.clone().n}\");\n"),
        "101\n"
    );
}

/// B-2026-07-29-39 — the interpreter half of aggregate field drop glue: a
/// struct holding a Drop-implementing value must run that value's body when it
/// dies. Pre-fix nothing walked an aggregate's fields, so `Holder { r: Res }`
/// dropped nothing and any resource in a field was held for the program's
/// lifetime.
///
/// Pins the same three properties as the codegen twin (`tests/codegen.rs`'s
/// `e2e_aggregate_runs_field_user_drop`), because the pair IS the parity
/// contract: the drop fires, nested aggregates recurse, fields die in reverse
/// declaration order, and a field moved out is dropped once by its destination.
#[test]
fn test_aggregate_runs_field_user_drop() {
    assert_eq!(
        run("struct A { t: i64 }\n\
             impl Drop for A { fn drop(mut ref self) { println(f\"dA{self.t}\"); } }\n\
             struct Mid { a: A }\n\
             struct Outer { m: Mid, a2: A }\n\
             struct Two { x: A, y: A }\n\
             struct Moved { a: A }\n\
             fn main() {\n\
                 { let o = Outer { m: Mid { a: A { t: 1 } }, a2: A { t: 2 } }; println(f\"{o.a2.t}\"); }\n\
                 { let t = Two { x: A { t: 4 }, y: A { t: 5 } }; println(f\"{t.x.t}\"); }\n\
                 { let h = Moved { a: A { t: 7 } }; let x = h.a; println(f\"{x.t}\"); }\n\
                 println(\"end\");\n\
             }\n"),
        "2\ndA2\ndA1\n4\ndA5\ndA4\n7\ndA7\nend\n"
    );
}

/// B-2026-07-30-11 SHAPE 2 — the interpreter half: an owned aggregate TEMP runs
/// its fields' user `impl Drop` in every position a temp can occupy (inline
/// struct-literal argument, fn-call argument, discarded fn result).
///
/// -39 taught the `let`-path this walk; every temp registrar still gated on the
/// type's OWN `drop_method_keys` entry, so `consume(H { .. })` / `consume(mk())`
/// / `mk();` each held the field's resource for the program's lifetime while
/// `let h = H { .. }; consume(h)` worked.
///
/// The passthrough case pins the disarm: `pass` returns its param, so the value
/// flows out to `p` and only `p`'s drop may run the body — `dA4` exactly once.
///
/// Same source and same expected string as `tests/codegen.rs`'s
/// `e2e_owned_aggregate_temp_runs_field_user_drop`; the pair IS the parity
/// contract, which is the whole reason a leak fix on one backend cannot land
/// without its twin.
#[test]
fn test_owned_aggregate_temp_runs_field_user_drop() {
    assert_eq!(
        run("struct A { t: i64 }\n\
             impl Drop for A { fn drop(mut ref self) { println(f\"dA{self.t}\"); } }\n\
             struct H { a: A }\n\
             fn consume(h: H) { println(\"c\"); }\n\
             fn mk(t: i64) -> H { H { a: A { t: t } } }\n\
             fn pass(h: H) -> H { h }\n\
             fn main() {\n\
                 consume(H { a: A { t: 1 } });\n\
                 println(\"-\");\n\
                 consume(mk(2));\n\
                 println(\"-\");\n\
                 mk(3);\n\
                 println(\"-\");\n\
                 let p = pass(H { a: A { t: 4 } });\n\
                 println(f\"{p.a.t}\");\n\
                 println(\"end\");\n\
             }\n"),
        "c\ndA1\n-\nc\ndA2\n-\ndA3\n-\n4\ndA4\nend\n"
    );
}

/// B-2026-07-31 (container-bodies move disarm) — a WHOLE-VALUE move of a
/// binding that carries a container-bodies walk (enum payload, Vec element,
/// tuple element) fires the payload's `Drop` body exactly ONCE, at the
/// destination. Before the disarm, every move shape here double-fired on the
/// interpreter, and under codegen the second fire read the cap-zeroed
/// moved-from slot (`self.id` printed 0 — a silently wrong value, not a
/// leak). Shapes pinned: rebind, tuple rebind, return-move, Vec rebind,
/// reassign, by-value call arg (the pre-existing balanced case).
///
/// Deliberate residual, asserted by ABSENCE: `f = g;` never runs the body of
/// f's OVERWRITTEN original (no 95 in the expected string) — both backends
/// share that silence today, a leak rather than a divergence.
///
/// Same source and expected string as `tests/codegen.rs`'s
/// `e2e_container_bodies_whole_value_move_single_fire` — the pair is the
/// parity contract.
#[test]
fn test_container_bodies_whole_value_move_single_fire() {
    assert_eq!(
        run("struct Res { id: i64 }\n\
             impl Drop for Res { fn drop(mut ref self) { println(90 + self.id); } }\n\
             enum Slot { Empty, Held(Res) }\n\
             fn make() -> Slot {\n\
                 let m = Slot.Held(Res { id: 3 });\n\
                 return m;\n\
             }\n\
             fn consume(s: Slot) {\n\
                 println(70);\n\
             }\n\
             fn main() {\n\
                 let a = Slot.Held(Res { id: 1 });\n\
                 let a2 = a;\n\
                 println(1);\n\
                 let t = (Res { id: 2 }, 10);\n\
                 let t2 = t;\n\
                 println(2);\n\
                 let c = make();\n\
                 println(3);\n\
                 let v: Vec[Res] = [Res { id: 4 }];\n\
                 let v2 = v;\n\
                 println(4);\n\
                 let mut f = Slot.Held(Res { id: 5 });\n\
                 let g = Slot.Held(Res { id: 6 });\n\
                 f = g;\n\
                 println(5);\n\
                 let b = Slot.Held(Res { id: 7 });\n\
                 consume(b);\n\
                 println(6);\n\
             }\n"),
        // `95` is the reassign target's OVERWRITTEN original firing at the
        // assignment — originally a shared residual silence, closed by the
        // B-2026-07-30-11 enum-assign displacement leg.
        "91\n1\n92\n2\n93\n3\n94\n4\n95\n96\n5\n70\n97\n6\n"
    );
}

/// B-2026-07-30-11 (Option/Result leg) — interpreter twin of
/// `tests/codegen.rs`'s `e2e_optres_payload_runs_user_drop_bodies`, same
/// source and expected string. The walk keys on the te the Let arm records
/// through codegen's exact resolution chain (`record_optres_payload_te`), so
/// both backends fire for the same set of bindings; the moved-out sets
/// mirror codegen's compile-time retractions at the match/combinator/ctor
/// sites.
#[test]
fn test_optres_payload_runs_user_drop_bodies() {
    assert_eq!(
        run("struct Res { id: i64 }\n\
             impl Drop for Res { fn drop(mut ref self) { println(90 + self.id); } }\n\
             struct HeapRes { name: String, id: i64 }\n\
             impl Drop for HeapRes { fn drop(mut ref self) { println(80 + self.id); } }\n\
             fn mk(i: i64) -> Option[HeapRes] {\n\
                 return Option.Some(HeapRes { name: \"payload-string-data\", id: i });\n\
             }\n\
             fn main() {\n\
                 let a = Option.Some(Res { id: 1 });\n\
                 println(1);\n\
                 let b: Result[i64, Res] = Err(Res { id: 2 });\n\
                 println(2);\n\
                 let c = mk(3);\n\
                 println(3);\n\
                 let d: Option[Res] = Option.None;\n\
                 println(4);\n\
                 let e = Option.Some(Res { id: 5 });\n\
                 match e {\n\
                     Some(r) => { println(20 + r.id); }\n\
                     None => { println(0); }\n\
                 }\n\
                 println(5);\n\
                 let f = Option.Some(Res { id: 6 });\n\
                 match f {\n\
                     Some(_) => { println(40); }\n\
                     None => { println(0); }\n\
                 }\n\
                 println(6);\n\
                 let g = Option.Some(Res { id: 7 });\n\
                 let r7 = g.unwrap();\n\
                 println(10 + r7.id);\n\
                 println(7);\n\
                 let h = Res { id: 8 };\n\
                 let s = Option.Some(h);\n\
                 println(8);\n\
             }\n"),
        "91\n1\n92\n2\n83\n3\n4\n25\n95\n5\n40\n96\n6\n17\n97\n7\n98\n8\n"
    );
}

/// B-2026-07-30-11 (Map-values leg) — interpreter twin of `tests/codegen.rs`'s
/// `e2e_map_values_run_user_drop_bodies`, same source and expected string.
/// One Drop-bearing value per map because iteration order is per-backend
/// (unordered-map semantics); the walk keys on the te the Let arm records
/// through codegen's exact chain.
#[test]
fn test_map_values_run_user_drop_bodies() {
    assert_eq!(
        run("struct Res { id: i64 }\n\
             impl Drop for Res { fn drop(mut ref self) { println(90 + self.id); } }\n\
             struct HeapRes { name: String, id: i64 }\n\
             impl Drop for HeapRes { fn drop(mut ref self) { println(80 + self.id); } }\n\
             fn main() {\n\
                 let mut m: Map[i64, Res] = Map.new();\n\
                 m.insert(1, Res { id: 1 });\n\
                 println(1);\n\
                 let mut m2: Map[i64, Res] = Map.new();\n\
                 m2.insert(5, Res { id: 5 });\n\
                 let out = m2.remove(5);\n\
                 println(2);\n\
                 let mut m3: Map[i64, Res] = Map.new();\n\
                 m3.insert(7, Res { id: 7 });\n\
                 let m4 = m3;\n\
                 println(3);\n\
                 let mut m5: Map[i64, Res] = Map.new();\n\
                 let r = Res { id: 4 };\n\
                 m5.insert(4, r);\n\
                 println(4);\n\
                 let mut m6: Map[i64, HeapRes] = Map.new();\n\
                 m6.insert(9, HeapRes { name: \"value-payload-string\", id: 9 });\n\
                 println(5);\n\
                 let mut m7: Map[i64, i64] = Map.new();\n\
                 m7.insert(2, 2);\n\
                 println(6);\n\
             }\n"),
        "91\n1\n95\n2\n97\n3\n94\n4\n89\n5\n6\n"
    );
}

/// B-2026-07-31-27 — a whole-map/set rebind (`let m2 = m;`) keeps the value
/// READABLE through the destination: rebind-then-return, chained rebinds with
/// a mutation through the final binding, and a Set rebind. The interpreter's
/// Rc semantics were always correct here; this is the oracle half of the pair
/// with `tests/codegen.rs`'s `e2e_map_whole_rebind_transfers_ownership`, where
/// the move nulls the source slot and `transfer_map_handle_on_rebind` hands
/// the scope-exit free to the destination (before the fix codegen leaked the
/// entire map; a wrong fix that instead dropped the source-null would UAF the
/// rebind-then-return shape — both drifts show up as output divergence here).
#[test]
fn test_map_whole_rebind_transfers_ownership() {
    assert_eq!(
        run("fn make() -> Map[i64, i64] {\n\
                 let mut m: Map[i64, i64] = Map.new();\n\
                 m.insert(1, 11);\n\
                 let m2 = m;\n\
                 m2\n\
             }\n\
             fn main() {\n\
                 let got = make();\n\
                 println(got.get(1).unwrap());\n\
                 let mut a: Map[i64, i64] = Map.new();\n\
                 a.insert(3, 30);\n\
                 let b = a;\n\
                 let mut c = b;\n\
                 c.insert(4, 40);\n\
                 println(c.len());\n\
                 println(c.get(4).unwrap());\n\
                 let mut s: Set[i64] = Set.new();\n\
                 s.insert(9);\n\
                 let s2 = s;\n\
                 println(s2.contains(9));\n\
             }\n"),
        "11\n2\n40\ntrue\n"
    );
}

/// B-2026-07-30-11 (displaced-value leg) — interpreter twin of
/// `tests/codegen.rs`'s `e2e_struct_reassign_displaced_drop_semantics`, same
/// source and expected string. The displaced old value's body fires at the
/// assignment (reading the OLD id — the pre-fix interpreter ran one body
/// AFTER the store and printed the new id), a moved identifier source fires
/// exactly once, and a consumed-by-the-RHS old value fires nothing at the
/// assignment.
#[test]
fn test_struct_reassign_displaced_drop_semantics() {
    assert_eq!(
        run("struct G { id: i64, s: String }\n\
             impl Drop for G {\n\
                 fn drop(mut ref self) {\n\
                     println(f\"drop {self.id}\")\n\
                 }\n\
             }\n\
             fn consume(g: G) -> G {\n\
                 G { id: g.id + 10, s: g.s }\n\
             }\n\
             fn main() {\n\
                 let mut a = G { id: 1, s: \"first\".to_string() };\n\
                 a = G { id: 2, s: \"second\".to_string() };\n\
                 println(\"after overwrite\");\n\
                 let mut x = G { id: 3, s: \"xxx\".to_string() };\n\
                 let y = G { id: 4, s: \"yyy\".to_string() };\n\
                 x = y;\n\
                 println(\"after move\");\n\
                 let mut c = G { id: 5, s: \"ccc\".to_string() };\n\
                 c = consume(c);\n\
                 println(\"after consume\");\n\
             }\n"),
        "drop 1\ndrop 2\nafter overwrite\ndrop 3\ndrop 4\nafter move\ndrop 15\nafter consume\n"
    );
}

/// B-2026-07-30-11 (match-arm leg) — interpreter twin of `tests/codegen.rs`'s
/// `e2e_match_arm_moved_payload_runs_drop_body`, same source and expected
/// string. Block arm bodies adopt the payload binding as a real Drop slot in
/// the block executor; bare-expression bodies fire at arm end when the only
/// uses are field projections.
#[test]
fn test_match_arm_moved_payload_runs_drop_body() {
    assert_eq!(
        run("struct Res { id: i64 }\n\
             impl Drop for Res {\n\
                 fn drop(mut ref self) {\n\
                     println(f\"drop {self.id}\")\n\
                 }\n\
             }\n\
             enum Box2 { Full(Res), Empty }\n\
             fn main() {\n\
                 let b = Box2.Full(Res { id: 4 });\n\
                 match b {\n\
                     Box2.Full(r) => { println(f\"arm sees {r.id}\"); }\n\
                     Box2.Empty => {}\n\
                 }\n\
                 println(\"between\");\n\
                 let c = Box2.Full(Res { id: 9 });\n\
                 match c {\n\
                     Box2.Full(r) => println(r.id),\n\
                     Box2.Empty => {}\n\
                 }\n\
                 println(\"end\");\n\
             }\n"),
        "arm sees 4\ndrop 4\nbetween\n9\ndrop 9\nend\n"
    );
}

